import Foundation

struct PostcardNarrative: Equatable {
    let id: String
    let animalKey: String
    let body: String
}

enum PostcardTextLibrary {
    static func randomEntry(for animal: Animal, excluding consumedIds: Set<String>) -> PostcardNarrative? {
        let key = animalKey(for: animal)
        let available = narratives.filter { $0.animalKey == key && consumedIds.contains($0.id) == false }
        return available.randomElement()
    }

    static func animalKey(for animal: Animal) -> String {
        if animal.id == "xiaoman_hamster" || animal.homeAssetName.contains("xiaoman_hamster") {
            return "xiaoman_hamster"
        }
        if animal.id == "tangyuan_puppy" || animal.homeAssetName.contains("tangyuan_puppy") {
            return "tangyuan_puppy"
        }
        if animal.id == "moji_cat" || animal.homeAssetName.contains("moji_cat") {
            return "moji_cat"
        }
        if animal.id == "dengdeng_rabbit" || animal.homeAssetName.contains("dengdeng_rabbit") {
            return "dengdeng_rabbit"
        }
        if animal.id == "feifei_parrot" || animal.homeAssetName.contains("feifei_parrot") {
            return "feifei_parrot"
        }
        if animal.id == "xiaolu_guinea_pig" || animal.homeAssetName.contains("xiaolu_guinea_pig") {
            return "xiaolu_guinea_pig"
        }
        if animal.id == "deer_visitor" ||
            animal.homeAssetName.contains("deer_visitor") ||
            animal.homeAssetName.contains("jiujiu_deer") {
            return "deer_visitor"
        }
        if animal.id == "fox_visitor" ||
            animal.homeAssetName.contains("fox_visitor") ||
            animal.homeAssetName.contains("aini_fox") {
            return "fox_visitor"
        }
        if animal.id == "bear_visitor" ||
            animal.homeAssetName.contains("bear_visitor") ||
            animal.homeAssetName.contains("dundun_bear") {
            return "bear_visitor"
        }
        return animal.id
    }

    // Generated by Tools/generate_postcard_text_library.py from Content/AnimalDatabase/PostcardTextLibrary_1.0.6.
    static let narratives: [PostcardNarrative] = [
        PostcardNarrative(id: "xiaoman_hamster_textlib106_001", animalKey: "xiaoman_hamster", body: "今天我在街角买到一颗特别饱满的榛子。圆度、重量、香气，都很合格。我把它放进小布袋最中间的位置。很好，今天的快乐有明确来源，可以归档。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_002", animalKey: "xiaoman_hamster", body: "海边的风把我的围巾吹成了一个奇怪的结。我本来准备批评它，但路过的小狗看了我一眼，尾巴摇得很认真。好吧，今天允许围巾自由发挥一次。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_003", animalKey: "xiaoman_hamster", body: "我在面包店门口闻到了刚出炉的黄油香。非常危险，容易让仓鼠忘记计划。我只买了一个小面包。只买一个，说明我仍然自律。吃完后，说明它确实优秀。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_004", animalKey: "xiaoman_hamster", body: "今天坐小火车穿过山谷，窗外的树一棵一棵往后跑，像在排队退场。我数到第八十六棵时笑了。树虽然不守队形，但跑得很有精神。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_005", animalKey: "xiaoman_hamster", body: "我在广场上看见一个喷泉，水柱按固定节奏升起来。很好，节奏稳定，表现优秀。我坐在旁边吃葵花籽，觉得世界今天有一点听话。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_006", animalKey: "xiaoman_hamster", body: "旅馆老板送了我一小块蓝莓派。计划外甜点，原则上需要警惕。但它太香了，我决定把它列入“临时幸福事项”。不是贪吃，是合理调整。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_007", animalKey: "xiaoman_hamster", body: "今天的云像一堆棉花。虽然棉花不能吃，但看起来很软。我趴在窗边看了很久，尾巴慢慢松下来。嗯，天空今天整理得不错。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_008", animalKey: "xiaoman_hamster", body: "我在旧书店找到一本很小很小的旅行地图，刚好能放进我的背包侧袋。太完美了。合适尺寸的东西，会让仓鼠感到世界仍然有秩序。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_009", animalKey: "xiaoman_hamster", body: "今天阳光正好落在我的爪子上，暖得像一小块烤过的饼干。我没有立刻走，延迟行程三分钟。三分钟而已，不算失控，算奖励。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_010", animalKey: "xiaoman_hamster", body: "我在桥上遇到一阵很温柔的风，它没有把我吹倒，只是推了推我的背。像是在说继续往前。好吧，那我就往前走一点点。今天可以勇敢一点点。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_011", animalKey: "xiaoman_hamster", body: "今天看见一家人坐在窗边吃晚饭。灯光很暖，盘子碰到桌面的声音也很轻。我停了一会儿，又假装在看地图。其实路线我早就查好了，只是不太想走开。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_012", animalKey: "xiaoman_hamster", body: "面包店的香味钻进围巾里时，我突然想起很久以前，妈妈也会把烤好的东西掰小，放到我面前。后来桌子还在，椅子还在，他们不在。香味有时候不讲道理。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_013", animalKey: "xiaoman_hamster", body: "我在雪地里踩出一串脚印，排得很整齐。可雪很快落下来，把它们盖住了。我忽然有点难过。原来有些存在过的东西，不出声，也会慢慢不见。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_014", animalKey: "xiaoman_hamster", body: "钟楼响了七下。我数得很认真，一下也没错。小时候爸爸说，数清楚时间，就不会害怕等。可是后来我数了很多很多天，他们也没有回来。这个方法不完全可靠。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_015", animalKey: "xiaoman_hamster", body: "湖边有只小鸭走歪了，鸭妈妈立刻回头等它。我本来笑了，后来没笑。小时候我也常常走歪。那时有人会等我。现在我走得再慢，也只能自己追上队伍。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_016", animalKey: "xiaoman_hamster", body: "旅馆房间很干净，东西放在哪里都不会变。我应该很满意。可是太安静了，安静到没有人会喊我吃饭，没有人会弄乱我的毯子。整齐有时候像一间空房子。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_017", animalKey: "xiaoman_hamster", body: "今天有个小孩把饼干屑分给麻雀。我看着那些麻雀围过去，忽然觉得胸口有点发酸。小小的东西被惦记着，是很幸福的事。我以前也以为自己一直会被惦记。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_018", animalKey: "xiaoman_hamster", body: "我路过一家玩具店，橱窗里有一只小木马。它不会真的去哪里，却一直摆出要出发的样子。很像那段时间的我，背包收好了，门也开着，只是不知道该去哪里。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_019", animalKey: "xiaoman_hamster", body: "晚上听见隔壁房间有人说晚安。我把被子拉到鼻尖，检查了门锁三遍。今天其实很好，风景也很好。只是有些话，别人轻轻说出来，我要在心里想很久。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_020", animalKey: "xiaoman_hamster", body: "我在港口看船离开。它们都有方向，有灯，有人挥手。我也挥了一下，虽然没人看见。离开这件事，我一直不太擅长理解。为什么有人走的时候，不说明天见呢。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_021", animalKey: "xiaoman_hamster", body: "这座城市的路牌是蓝色的，字体很细，雨后会反光。路口有三家咖啡店，其中第二家的门铃声音最清脆。我已记录。旅行需要观察，观察使仓鼠稳定。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_022", animalKey: "xiaoman_hamster", body: "今天的海浪每隔几秒就推上岸一次，但每次形状都不同。它们看起来很随意，其实有自己的规律。只是我暂时还没完全掌握。需要继续观察。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_023", animalKey: "xiaoman_hamster", body: "广场上的鸽子不太守纪律。它们先聚集，再忽然散开，像一张被风吹乱的纸。中间那只灰色的尤其大胆，偷走了一块面包皮。行为不佳，但动作敏捷。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_024", animalKey: "xiaoman_hamster", body: "这里的公交车比我想象中准时。车门打开时会发出轻轻的气声，像谁叹了一口气。座椅是深绿色，靠窗第三排最适合仓鼠观察街景。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_025", animalKey: "xiaoman_hamster", body: "早市从六点开始变热闹。鱼摊先亮灯，水果摊后摆好，卖花的人最后到。花桶里的水有一点晃，说明她来的路上走得很快。合理推测。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_026", animalKey: "xiaoman_hamster", body: "今天的云移动速度偏慢，适合长时间观看。左边那朵像土豆，右边那朵像一只睡着的羊。云的分类标准还不成熟，但我正在建立。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_027", animalKey: "xiaoman_hamster", body: "图书馆里的人翻书声音不一样。有的人很轻，有的人很急。靠窗的老爷爷每隔十分钟扶一次眼镜。我猜他读到难的地方了。也可能只是眼镜下滑。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_028", animalKey: "xiaoman_hamster", body: "山路旁边有很多小石头，颜色从灰到浅黄不等。我挑了三颗放在掌心比较，最圆的那颗留在原地。它在那里比较合适，不是什么都要带走。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_029", animalKey: "xiaoman_hamster", body: "旅馆窗台上有一盆薄荷。早上叶子立起来，晚上会垂一点。浇水后气味更明显。我闻了两次，确认它不是零食。虽然看起来有一点像。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_030", animalKey: "xiaoman_hamster", body: "今天经过一条很窄的巷子，墙上爬着藤蔓。藤蔓没有地图，却知道往哪里长。它们绕过窗户，贴着砖缝，一点点往上。植物的计划写得很慢，但很坚定。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_031", animalKey: "xiaoman_hamster", body: "今天我看着一朵云，突然觉得它其实是一艘慢吞吞的白色飞船。里面住着三百只会整理星星的仓鼠，按大小、亮度、脾气分类。嗯，如果是真的，我应该可以当管理员。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_032", animalKey: "xiaoman_hamster", body: "海浪拍上岸的时候，我怀疑海底有一只巨大的猫在打呼噜。每呼一次，水就推上来。它一定睡得很熟，所以世界才一摇一晃。请放心，我没有下去确认，风险太高。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_033", animalKey: "xiaoman_hamster", body: "我看见一只鸽子站在雕像头上，忽然想到它可能是这座城市的秘密市长。它每天巡视面包屑、喷泉和游客鞋带。管理水平一般，但飞行能力优秀，可以考虑连任。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_034", animalKey: "xiaoman_hamster", body: "今天的月亮像一颗咬过的奶酪。我认真想了想，如果月亮真是奶酪，那星星可能就是撒出去的盐粒。宇宙也许是一张很大的餐巾。这个推测尚未验证，但很香。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_035", animalKey: "xiaoman_hamster", body: "火车钻进隧道时，我觉得我们被一条黑色大鲸鱼吞进肚子里。车灯是鲸鱼肚子里的小灯笼。等火车出来，就像被鲸鱼礼貌地吐回世界。过程顺利，未投诉。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_036", animalKey: "xiaoman_hamster", body: "我在旧书店闻到纸张味，突然觉得每一本书都是一扇睡着的门。只要翻开，就能进到某个人藏好的下午。我轻轻翻，不吵醒它们。门睡觉也需要秩序。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_037", animalKey: "xiaoman_hamster", body: "今天的风很奇怪，好像有一群看不见的小兔子在街上奔跑。它们撞到树叶，撞到我的帽子，还撞乱了我的计划表。算了，小兔子没有行政能力，不能苛责。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_038", animalKey: "xiaoman_hamster", body: "我坐在桥边，看河水往前走。忽然觉得河里也有一支队伍，水滴们背着小包，去很远的地方开会。它们都不回头。水滴真勇敢，也可能只是没有脖子。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_039", animalKey: "xiaoman_hamster", body: "黄昏时，路灯一盏一盏亮起来，像有人在给城市点名。第一盏：到。第二盏：到。第三盏有点慢，可能睡过头了。我替它紧张了一会儿，还好最后赶上了。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_040", animalKey: "xiaoman_hamster", body: "今天我看到一只蜗牛爬过石阶。我想，它也许不是慢，而是在搬运一座小型宫殿。它走到哪里，家就到哪里。这个方案很好，就是速度方面需要优化。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_041", animalKey: "xiaoman_hamster", body: "今天什么都没有发生。天气正常，路线正常，饭也正常。可是我就是有点低落，像背包里多了一颗看不见的石头。找不到来源，就暂时不处理。先背着吧。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_042", animalKey: "xiaoman_hamster", body: "我坐在窗边很久，计划表摊开着，却一个字也没写。不是没有计划，是爪子不想动。仓鼠也会有这种时候：明明世界没出错，心里却像少了一颗螺丝。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_043", animalKey: "xiaoman_hamster", body: "今天的街道很热闹，我也跟着走了很久。大家都在笑，我没有讨厌他们。我只是突然觉得自己隔着一层玻璃。看得见，很清楚，但不知道怎么进去。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_044", animalKey: "xiaoman_hamster", body: "我买了一袋葵花籽，数了三遍，数量没错。可确认正确以后，也没有变开心。糟糕，今天连准确都不太管用。我把袋口系紧，决定不要强迫自己高兴。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_045", animalKey: "xiaoman_hamster", body: "傍晚的时候，风从外套里钻进去。我打了个小喷嚏。没人听见，也没人回头。其实这很正常，街上那么多人。只是有一瞬间，我觉得自己小得有点过分。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_046", animalKey: "xiaoman_hamster", body: "我今天没有特别想写明信片。可是我还是写了，因为你会看见。看见这件事，对小动物很重要。虽然我写得慢，虽然字有点歪，但我没有消失。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_047", animalKey: "xiaoman_hamster", body: "旅馆的床很软，软得让人陷进去。我不太喜欢陷进去的感觉，会让我想起一些起不来的早晨。于是我坐在床边，脚不沾地，安静地等自己恢复一点点。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_048", animalKey: "xiaoman_hamster", body: "今天路过一家很亮的餐厅，里面有很多人。我在门外看了一眼就走了。不是不饿，是不想进去。热闹有时候像一件太大的衣服，披在身上，会把我压低。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_049", animalKey: "xiaoman_hamster", body: "我把行李整理好了，地图也折好了，一切都很整齐。可心里还是乱的。原来外面的秩序不能完全管住里面。这个结论让我不太满意，但应该是真的。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_050", animalKey: "xiaoman_hamster", body: "晚上忽然很想回到一个地方，可我说不清是哪里。也许不是城市，也不是房间，只是某种不用担心被留下的感觉。这个地方地图上没有，我暂时找不到。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_051", animalKey: "xiaoman_hamster", body: "今天我在集市赢到了一枚小小的木头徽章！虽然比赛项目只是“猜篮子里有几颗栗子”，但我猜得非常接近。优秀，小满，优秀。我要把它缝在背包上，位置居中。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_052", animalKey: "xiaoman_hamster", body: "我吃到了世界上最脆的饼干。咔嚓一声，像把阴天咬开了。我本来只打算吃半块，结果吃完了一整块。情况特殊，快乐超标，需要追加记录。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_053", animalKey: "xiaoman_hamster", body: "今天坐缆车上山，云从我旁边飘过去。我伸出爪子，差一点就碰到。差一点也很好！仓鼠离天空这么近，已经非常了不起。我的胡须都在高兴。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_054", animalKey: "xiaoman_hamster", body: "我在街头听见有人拉手风琴，旋律跳来跳去，像一颗不听话的豆子。我跟着晃了两下。只是两下。第三下也有一点点。好吧，我今天确实很开心。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_055", animalKey: "xiaoman_hamster", body: "旅馆窗台上停了一只小鸟，它歪头看我。我也歪头看它。我们进行了严肃外交会晤，时长七秒，气氛友好。它飞走后，我笑了很久。小鸟承认我了吗？"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_056", animalKey: "xiaoman_hamster", body: "今天的阳光太好了！照在河面上，像撒了一整袋碎糖。我宣布这条河今日表现优异。要不是我不会游泳，我一定要去河边更近一点夸它。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_057", animalKey: "xiaoman_hamster", body: "我买到了一顶刚好合适的小帽子。不是大一点，也不是小一点，是刚刚好！你知道刚刚好有多难吗？世界居然为仓鼠留了一个尺寸。今天值得盖章。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_058", animalKey: "xiaoman_hamster", body: "今天我没有迷路，一次都没有。每条街都按照地图出现，每个拐角都很配合。我走到终点时，差点原地转圈。出于形象管理，我只转了半圈。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_059", animalKey: "xiaoman_hamster", body: "我发现一家店卖迷你坚果塔。迷你！坚果！塔！三个词放在一起非常可靠。我买了两个，一个现在吃，一个备用。备用那个后来也吃了，因为开心需要连续性。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_060", animalKey: "xiaoman_hamster", body: "晚上有烟花。砰的一声，天空开出很大的花。我本来吓了一跳，但下一秒就笑了。原来有些声音不是门关上，是天在庆祝。这个区别很重要，我记住了。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_061", animalKey: "xiaoman_hamster", body: "今天我坐在长椅上，想写点什么。结果脑袋里只有“嗯”。嗯。嗯嗯。很好，至少有三个嗯。它们排得还算整齐。今天的思考到此为止。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_062", animalKey: "xiaoman_hamster", body: "我盯着一块石头看了很久。石头没有动，我也没有动。我们之间达成了某种安静协议。内容不详，因为我忘了自己为什么开始看它。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_063", animalKey: "xiaoman_hamster", body: "今天的风吹过来，我的脑袋也像被吹空了一点。计划表在包里，铅笔在爪边，可我暂时不想安排任何事情。空着也行。空盒子也有盒子的用处。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_064", animalKey: "xiaoman_hamster", body: "我吃了一颗葡萄干。然后忘记自己要写什么。葡萄干很甜。甜。嗯。明信片上如果只写“甜”，会不会太少？那就写两遍：甜，甜。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_065", animalKey: "xiaoman_hamster", body: "今天我走到桥上，突然不知道下一步要干什么。于是我站着。桥负责连接两边，我负责站在中间。分工明确，执行良好。脑袋空空，但站姿稳定。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_066", animalKey: "xiaoman_hamster", body: "云在动。我在看。云继续动。我继续看。中间没有复杂情节。这样也不错，不是所有下午都需要意义。有些下午只需要仓鼠和一片云。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_067", animalKey: "xiaoman_hamster", body: "我刚才好像想到了很重要的事，但一阵面包香经过，它就不见了。可能被面包香带走了。希望它过得好。如果回来，请按顺序排队。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_068", animalKey: "xiaoman_hamster", body: "今天写字写到一半，脑袋忽然像刚洗过的小碗，里面什么都没有。很干净，也有点亮。那我就先不装东西了。空一会儿，应该不会坏。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_069", animalKey: "xiaoman_hamster", body: "我坐在旅馆地毯上，数地毯花纹。数到二十七，忘了前面有没有数错。算了，地毯并不在意。我也暂时不在意。今天允许轻微糊涂。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_070", animalKey: "xiaoman_hamster", body: "现在是晚上。我看着窗外的灯，一个、两个、三个。然后就不想数了。灯继续亮着，我继续发呆。世界今天自己运转，不需要我监督。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_071", animalKey: "xiaoman_hamster", body: "今天早上，阳光先碰到窗帘，再慢慢爬到我的被角上。它没有催我起床，只是安静地等。我忽然觉得，生活不是一直要赶路。有时候被温柔照到，也算到达。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_072", animalKey: "xiaoman_hamster", body: "我在小巷里闻到热汤的味道，听见锅盖轻轻响。有人正在认真做一顿饭。这个事实让我安心。世界上还有很多小火慢慢烧着，很多晚餐正在被好好准备。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_073", animalKey: "xiaoman_hamster", body: "今天雨停以后，路边的叶子亮得像刚洗过。水珠挂在叶尖，没有立刻掉下来。我站着看了很久。原来美好的东西不一定很大，有时候只是没有坠落的一滴水。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_074", animalKey: "xiaoman_hamster", body: "我在公园长椅上晒太阳，旁边有个老人慢慢剥橘子。橘子皮的香气一点点散开。我突然觉得，生活也可以这样，一瓣一瓣，不着急，慢慢甜起来。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_075", animalKey: "xiaoman_hamster", body: "傍晚的风吹过草地，小花都轻轻点头。没有谁指挥它们，但它们好像知道怎么一起温柔。我把饼干碎分成三份，自己吃两份，留一份给路过的麻雀。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_076", animalKey: "xiaoman_hamster", body: "今天我走过一座桥，看见河水把晚霞揉碎，又一点点带走。它没有保存，也没有抱怨。美好的东西原来可以经过我，然后继续去远方。我看见过，就很好。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_077", animalKey: "xiaoman_hamster", body: "旅馆老板在门口放了一盏小灯，说怕晚归的人看不清路。我听完心里暖了一下。有人为还没回来的人留灯，这件事本身，就很像一小块家。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_078", animalKey: "xiaoman_hamster", body: "我今天买的面包有一点烫，捧在爪子里刚刚好。第一口咬下去，外壳很脆，里面很软。我忽然觉得自己还在这里，还能吃到热的东西，真是很不坏。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_079", animalKey: "xiaoman_hamster", body: "清晨的街道还没完全醒，店铺半开，猫趴在台阶上，扫帚靠在墙边。所有东西都在慢慢开始。我喜欢这种开始。没有太响的声音，但每一样都在变好。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_080", animalKey: "xiaoman_hamster", body: "晚上我给你写明信片，灯光落在纸上，影子落在爪边。我忽然觉得，能把今天看见的东西告诉你，是一件很好的事。世界很大，我很小，但我有地方寄出心情。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_081", animalKey: "xiaoman_hamster", body: "今天我第一次坐热气球。篮子离地的时候，我的爪子抓得很紧，但我表现得非常平静。只是胡须有一点点抖。胡须不属于正式情绪记录，所以不算害怕。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_082", animalKey: "xiaoman_hamster", body: "我在陌生餐厅点餐，菜单上有很多看不懂的字。我盯着它们看了三分钟，然后冷静地点了一个最短的。很好，小满处理未知状况的能力正在提升。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_083", animalKey: "xiaoman_hamster", body: "今天迷路了七分钟。准确地说，是路线暂时失去配合。我没有慌，只是把地图打开、合上、再打开。动作有序，说明我仍然掌控局面。大概。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_084", animalKey: "xiaoman_hamster", body: "旅馆的电梯突然停了一下。我立刻制定了三套逃生方案，虽然下一秒它又动了。旁边的人没有发现我的专业素养。没关系，真正的镇定通常不被看见。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_085", animalKey: "xiaoman_hamster", body: "我在桥上遇到很大的风，帽子差点飞走。我一把按住它，假装只是普通整理仪容。其实我的心跳已经跑到前面去了。回来，心跳，队形不许乱。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_086", animalKey: "xiaoman_hamster", body: "今天和一只陌生猫对视了。它很大，我很小，但我没有立刻逃跑。我只是战略性后退三步。不是害怕，是合理保持外交距离。请准确记录。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_087", animalKey: "xiaoman_hamster", body: "我在博物馆里听不懂讲解，但我点了点头。点头是一种万能工具，可以暂时维护仓鼠尊严。回去以后我会查资料。镇定有时候需要事后补课。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_088", animalKey: "xiaoman_hamster", body: "今天过马路时车很多。我等了三轮红绿灯才走。别人可能觉得我慢，但我知道，这是严谨。生命只有一条，仓鼠更小，更应该严格执行安全流程。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_089", animalKey: "xiaoman_hamster", body: "我在海边被浪花溅湿了脚。冰凉，非常突然。我本来想叫，但忍住了，只低头检查了一下爪子。嗯，爪子还在。情况可控。海浪不必道歉，但最好反省。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_090", animalKey: "xiaoman_hamster", body: "晚上窗外传来奇怪的声音。我坐起来，打开灯，检查门锁，确认行李位置。然后假装自己本来就没睡。镇定的仓鼠，即使被吓醒，也要保持流程完整。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_091", animalKey: "xiaoman_hamster", body: "今天我把明信片写得比平时整齐一点。不是因为我在等夸奖。只是如果你刚好看到，刚好觉得字不错，那也可以告诉我。随便告诉，不用太正式。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_092", animalKey: "xiaoman_hamster", body: "我在信封角落画了一颗很小的葵花籽。它小到可能会被忽略。但如果你发现了，说明你看得很认真。认真看见小东西的人，很值得记录。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_093", animalKey: "xiaoman_hamster", body: "今天路过邮筒时，我把明信片投进去，又站了一会儿。邮筒没有说话，它只是吞掉了我的心情。希望它路上不要弄丢。希望你收到的时候，也不要很快放下。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_094", animalKey: "xiaoman_hamster", body: "我写“今天很好”的时候停了一下。其实想写“你会不会也觉得好”。但这样太直接了，不符合仓鼠谨慎原则。所以我只写了今天很好。你应该能看懂吧？"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_095", animalKey: "xiaoman_hamster", body: "今天我看见一朵很像你的云。不是说你像云，是云看起来很可靠，边缘也很温柔。我差点把这个发现写在第一行，后来觉得太明显，就藏到第三行以后。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_096", animalKey: "xiaoman_hamster", body: "我买了两颗糖，一颗吃掉，一颗放进信封里想寄给你。后来发现糖会压坏明信片，只好自己吃掉。请注意，这不是贪吃，是邮寄条件不允许。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_097", animalKey: "xiaoman_hamster", body: "有时候我会想，你读到我的明信片时，是坐着，还是站着？有没有喝水？会不会笑一下？我不需要知道全部，只是想象一下。想象也可以有小小的温度。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_098", animalKey: "xiaoman_hamster", body: "今天我写完明信片以后，又补了一句话，然后又划掉。划掉的地方其实也算说过。仓鼠说话不太擅长直达，但会绕路。你如果看见墨迹，就当那是我绕过的路。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_099", animalKey: "xiaoman_hamster", body: "我把今天最漂亮的风景留到最后写。因为最后一句容易被记住。这个策略很明显吗？不明显就好。明显也没关系。反正你已经读到这里了。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_100", animalKey: "xiaoman_hamster", body: "晚上我把信放在桌上，检查了三遍地址。地址正确，邮票端正，心情有点暴露。没关系，暴露一点点也可以。毕竟明信片本来就是把心放到远处给人看。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_101", animalKey: "xiaoman_hamster", body: "今天我没有走计划里的主路，而是拐进了一条铺满阳光的小巷。很大胆，小满，非常大胆。结果巷子尽头有一棵橘子树。看来有些偏离路线，也会得到奖励。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_102", animalKey: "xiaoman_hamster", body: "我在陌生咖啡馆坐到了靠窗的位置。以前我会选角落，因为角落安全。但今天我想看看街道。被世界看见一点点，也没有立刻坏掉。这个发现值得保存。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_103", animalKey: "xiaoman_hamster", body: "今天有个孩子问我是不是旅行家。我本来想说不是，只是被你送出来看看。但我想了想，点了点头。嗯，我是旅行家。小型的，谨慎的，但也是。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_104", animalKey: "xiaoman_hamster", body: "我站在海边，把爪子伸进水里。冷，很冷，非常冷。但我没有马上缩回来。我数到五才收回。五秒的勇敢也是勇敢，不能因为短就不算。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_105", animalKey: "xiaoman_hamster", body: "今天我主动问路了。声音有点小，但对方听见了。我得到了正确方向，还得到一句“祝你好运”。原来向别人开口，不一定会发生坏事。这个结论很重要。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_106", animalKey: "xiaoman_hamster", body: "我走过一座很高的桥。风从下面吹上来，我的腿有点软。但我一直往前。走到桥尾时，我回头看了一眼。原来害怕的地方，也可以变成经过的地方。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_107", animalKey: "xiaoman_hamster", body: "我在广场上听音乐，差点跟着节奏拍爪子。后来我真的拍了。只有两下，但声音是我自己的。世界那么吵，能发出一点自己的声音，也挺好。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_108", animalKey: "xiaoman_hamster", body: "今天我把一颗多余的葵花籽分给了旁边的麻雀。它啄走以后，看了我一眼。也许是谢谢，也许只是确认没有下一颗。没关系，我完成了一次友好行动。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_109", animalKey: "xiaoman_hamster", body: "我没有反复检查门锁五遍，只检查了三遍。三遍就睡了。虽然半夜醒来想再检查，但我没有去。小满今日勇敢表现：相信门一次。非常不容易。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_110", animalKey: "xiaoman_hamster", body: "今天我在明信片上写了“我想你”。写完以后盯了很久，没有划掉。好吧，勇敢就是这样：手有点抖，但字还在那里。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_111", animalKey: "xiaoman_hamster", body: "今天的天气预报说不下雨，但雨还是来了。世界提供的信息不完全可靠。我把这个现象记下。还好我带了伞。对世界保持怀疑，对背包保持信任。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_112", animalKey: "xiaoman_hamster", body: "我在地图上看到这条路很短，实际走起来却很长。地图是不是故意把困难画小了？也可能是我的腿太短。暂时不下结论，继续调查。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_113", animalKey: "xiaoman_hamster", body: "面包店说“最后一块栗子派”，可我刚买完，店员又端出一盘。最后这个词，看来有弹性。人类语言需要谨慎理解，尤其涉及甜点时。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_114", animalKey: "xiaoman_hamster", body: "今天我看见一座钟慢了两分钟。钟怎么可以慢？它不是专门负责准确的吗？我站在下面盯了它一会儿。它毫无愧疚。世界的责任心有待提高。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_115", animalKey: "xiaoman_hamster", body: "鸽子看起来很悠闲，但每次面包屑出现，它们都能第一时间抵达。所谓悠闲，也许只是伪装。小满判断：鸽子是一种有隐藏计划的动物。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_116", animalKey: "xiaoman_hamster", body: "我以为大海只会往前扑，结果它还会退后。前进、后退、再前进。看起来反复无常，但它每天都这样。也许有些稳定，本身就是来回变化。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_117", animalKey: "xiaoman_hamster", body: "旅馆房间的灯开关在门边，但床头也有一个。我试了三次，两个都能控制同一盏灯。奇怪。一件事居然可以被两个地方影响。那心情是不是也一样？"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_118", animalKey: "xiaoman_hamster", body: "今天看见一朵云很像兔子，五分钟后变成了鱼。云没有说明原因。世界上很多东西都在变化，而且不提交申请。这个管理方式让我略感不安。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_119", animalKey: "xiaoman_hamster", body: "我问路时，对方说“很近”。后来我走了二十分钟。很近对谁来说？对长腿动物来说吗？以后所有“很近”都要换算成仓鼠单位。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_120", animalKey: "xiaoman_hamster", body: "我发现漂亮的花也会枯掉，好吃的面包也会吃完，热闹的街也会安静。美好不是不可靠，只是有时限。这个结论不太舒服，但似乎准确。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_121", animalKey: "xiaoman_hamster", body: "今天广场人太多了。我钻到长椅下面待了一会儿。下面有阴影、尘土和一片掉落的叶子。叶子不问问题，我很喜欢。偶尔藏起来，不代表失败。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_122", animalKey: "xiaoman_hamster", body: "我在餐厅听见很多声音，盘子声、笑声、脚步声，全都挤在一起。我把围巾拉高，只露出眼睛。这样世界就小一点，小到我可以处理。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_123", animalKey: "xiaoman_hamster", body: "今天不想被任何人发现。我沿着墙边走，影子也贴着我。我们两个保持安静。影子很好，不会催我开心，也不会问我为什么低头。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_124", animalKey: "xiaoman_hamster", body: "我把明信片写到一半，忽然不想写了。不是不想告诉你，是有些心情刚冒出来就想缩回壳里。虽然仓鼠没有壳，但背包可以暂时代替。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_125", animalKey: "xiaoman_hamster", body: "旅馆大厅有很多陌生人。我本来想穿过去，后来绕了后门。多走了三分钟，但心里安静一点。路线可以变长，心不能被吓得太短。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_126", animalKey: "xiaoman_hamster", body: "今天的风很大，吹得大家都抬头看天。我趁这个时候低头走路，没人注意我。被忽略有时候也挺好，像把自己放进一只柔软的小盒子。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_127", animalKey: "xiaoman_hamster", body: "我在图书馆选了最里面的位置。书架挡住左边，窗帘挡住右边，桌子挡住前面。非常合格的临时洞穴。我在里面坐着，慢慢把呼吸放平。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_128", animalKey: "xiaoman_hamster", body: "今天我没有拍照。风景很好，但我不想举起相机。我只想安静地经过它们，不留下证据。有些日子，能悄悄存在就已经够了。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_129", animalKey: "xiaoman_hamster", body: "我把帽檐压低，在街上走了很久。不是难过，也不是害怕，只是想让自己变成一颗小小的、不被打扰的栗子。栗子安静，栗子有壳，栗子很安全。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_130", animalKey: "xiaoman_hamster", body: "晚上我关掉大灯，只留一盏小台灯。房间立刻变小，也变温柔。我缩在被子里，听远处的车声。今天不想面对整个世界，只面对这一小圈光。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_131", animalKey: "xiaoman_hamster", body: "散步回来的路上，我看见两个小学生站在幼儿园门口扫脸。机器亮了一下，说：未注册。小孩愣住了，小声说，是我啊。门没有回答。我也没有出声，只把这件事记下。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_132", animalKey: "xiaoman_hamster", body: "今天车站有人刷票进站，闸机却一直响。他翻了好几次口袋，票明明在手里。后面的人开始催，他的耳朵慢慢红了。原来有时候，不是你没有资格，是门不认识你。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_133", animalKey: "xiaoman_hamster", body: "我在旅馆前台看见一位老人报名字。店员查了很久，说没有预订。老人把确认短信递过去，手有一点抖。屏幕不承认的时候，人就会忽然变得很小。这个现象需要记录。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_134", animalKey: "xiaoman_hamster", body: "博物馆门口，一个小女孩把会员卡贴到机器上。机器说无效。她又贴了一次，更认真地贴。还是无效。她看着卡片，好像卡片背叛了她。其实卡片一直在她手里。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_135", animalKey: "xiaoman_hamster", body: "今天路过学校门口，有个孩子站在电子屏前，屏幕上没有他的名字。老师说可能系统没更新。他点点头，很乖。可是他的影子在地上停了很久，像还没被更新进去。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_136", animalKey: "xiaoman_hamster", body: "超市自助结账机一直识别不了一颗苹果。店员拿起来转了几圈，机器还是沉默。苹果没有错，只是它的样子不在机器知道的范围里。我突然觉得，很多东西都是这样。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_137", animalKey: "xiaoman_hamster", body: "我看见一只狗跑到一家店门口摇尾巴。店主换人了，不认识它，把门关上。狗坐了一会儿，尾巴慢慢停下。它大概以前常被摸头。记忆还在，可门换了主人。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_138", animalKey: "xiaoman_hamster", body: "今天有人在公寓楼下按密码，按了三遍都错。他站在门前笑了一下，说我以前住这里。旁边没人接话。原来“以前”不能开门。这个规定很硬，也很不讲情面。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_139", animalKey: "xiaoman_hamster", body: "邮局里，一个人说包裹应该是他的。柜员说姓名对不上。他重复了一遍自己的名字，声音越来越轻。名字明明是最像自己的东西，可有时候，名字也不能证明自己。"),
        PostcardNarrative(id: "xiaoman_hamster_textlib106_140", animalKey: "xiaoman_hamster", body: "我在医院大厅看见一台叫号机。有人坐在那里等，屏幕一直跳过他的号码。他没有生气，只是每次抬头都慢一点。被漏掉不是一声巨响，是一次一次没轮到你。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_001", animalKey: "tangyuan_puppy", body: "今天我在车站看见一个很像你的背影，尾巴立刻开始摇。后来发现不是你，也没关系！那个人也很好看。汪，世界上有很多像快乐入口的背影。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_002", animalKey: "tangyuan_puppy", body: "旅馆老板一叫“糖圆”，我就冲过去了。虽然他只是问我要不要换毛巾，但名字被叫到就是很重要的事。汪汪，尾巴批准！"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_003", animalKey: "tangyuan_puppy", body: "今天遇到昨天喂过我饼干的阿姨。我记得她！她也记得我！我们在街角进行了热烈重逢，时长三十秒，尾巴高速运转。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_004", animalKey: "tangyuan_puppy", body: "咖啡店小哥看见我，说又来啦。我立刻坐好。又来啦这三个字好亲切，像一块软垫子。汪，我喜欢被世界认出来。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_005", animalKey: "tangyuan_puppy", body: "公园门口的老爷爷昨天摸过我头，今天又摸了。熟人加一，快乐加一。我的脑袋今天承担了很多友好职责。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_006", animalKey: "tangyuan_puppy", body: "今天你的视频响起来，我听见你的声音，立刻从地毯上弹起来。屏幕里不能扑进去，略微遗憾。但尾巴已经代替我扑过了。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_007", animalKey: "tangyuan_puppy", body: "面包店老板远远看见我，就把门打开一点。香味跑出来，我也想跑进去。我们互相都很热情，只是门比较冷静。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_008", animalKey: "tangyuan_puppy", body: "今天遇到一只昨天一起闻草的小狗。我们先转圈，再闻闻，再一起冲向树下。友谊不需要复杂手续，鼻子通过就可以。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_009", animalKey: "tangyuan_puppy", body: "旅馆走廊里有人说早安。我不知道他是不是跟我说，但我已经开心了。汪，早安这种东西可以共享，不必精确投递。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_010", animalKey: "tangyuan_puppy", body: "傍晚回来时，前台姐姐说辛苦啦。我没有辛苦，我玩得很好！但被这样说，心里暖暖的。尾巴宣布：此人已列入熟人名单。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_011", animalKey: "tangyuan_puppy", body: "今天我追着一只鸽子跑了三步。它飞走了。没关系，也许它比较害羞。朋友有时候需要天空距离，汪，我尊重。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_012", animalKey: "tangyuan_puppy", body: "海边有个小孩拿着铲子。我看了看铲子，又看了看他。他笑了，我也笑了。我们差点一起挖沙，可惜大人说不可以太脏。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_013", animalKey: "tangyuan_puppy", body: "路边一只麻雀跳来跳去。我趴低，轻轻汪了一声。它没有回应，但这不影响我认为我们进行过短暂交流。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_014", animalKey: "tangyuan_puppy", body: "今天有一辆自行车停在墙边。我闻了闻轮胎。它去过很多地方，气味非常丰富。虽然它不会说话，但应该很会旅行。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_015", animalKey: "tangyuan_puppy", body: "咖啡馆门口的猫看了我一眼，立刻跳上窗台。我没有追。猫朋友需要慢热。没关系，我可以在楼下摇尾巴等。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_016", animalKey: "tangyuan_puppy", body: "公园里一位老人坐在长椅上。我把球滚过去。他把球滚回来！天哪，正式建交！汪汪汪，国际友谊成功。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_017", animalKey: "tangyuan_puppy", body: "今天遇到一只拖着行李箱的人。我先跟行李箱做朋友，因为它一直咕噜噜。后来人也笑了。两个朋友，赚到。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_018", animalKey: "tangyuan_puppy", body: "商店门口有个充气小熊在摇手。我对它汪了三声。它一直摇，说明它非常热情，只是语言系统比较单一。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_019", animalKey: "tangyuan_puppy", body: "街角的树很大，我把鼻子贴上去闻。它认识很多狗，信息量巨大。我在树下停了很久。树朋友沉默，但可靠。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_020", animalKey: "tangyuan_puppy", body: "今天一阵风从我身边跑过。我追了它一段。风没有停下来，但它把我的耳朵吹起来了。汪，它也算陪我玩过。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_021", animalKey: "tangyuan_puppy", body: "今天吃到一小块烤鸡。外面香，里面也香，连回忆都香。汪！我本来想慢慢吃，但嘴巴不同意。嘴巴行动过快，不予批评。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_022", animalKey: "tangyuan_puppy", body: "面包店掉了一点面包屑。我看见了。它那么小，那么孤单，我当然要帮它找到归宿。现在它在我肚子里，很安全。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_023", animalKey: "tangyuan_puppy", body: "旅馆早餐有香肠。我坐得特别端正，眼睛特别圆。服务员说不能给太多。没关系，一点点也可以很大声地快乐。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_024", animalKey: "tangyuan_puppy", body: "今天尝了蓝莓酸奶。酸酸甜甜，鼻子皱了一下，尾巴摇了一下。身体意见不统一，但总体评价：可以再来一口。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_025", animalKey: "tangyuan_puppy", body: "街边卖栗子，热气飘到我鼻子里。我的脚自动停下。不是我贪吃，是鼻子收到重要通知。汪，栗子部门申请关注。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_026", animalKey: "tangyuan_puppy", body: "我在市场闻到鱼、肉、奶酪、面包和一只路过小狗的零食袋。信息太多，幸福到差点坐下。鼻子今天加班成功。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_027", animalKey: "tangyuan_puppy", body: "今天吃了一块小饼干，形状像骨头。虽然它不是真骨头，但态度很好。我嚼得很认真，给它充分尊重。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_028", animalKey: "tangyuan_puppy", body: "海边小摊有炸鱼味。我不能吃太多，于是只闻了很久。闻也是一种轻量级吃饭。汪，鼻子已经饱了半格。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_029", animalKey: "tangyuan_puppy", body: "你给我寄的零食打开时，我立刻坐好。坐好是小狗的重要仪式。吃之前要礼貌，吃的时候要专心，吃完要舔嘴。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_030", animalKey: "tangyuan_puppy", body: "今天我发现世界上有一种东西叫芝士面包。芝士会拉丝，像快乐被拉长了。汪汪，建议列入旅行必需品。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_031", animalKey: "tangyuan_puppy", body: "旅馆门口有一只拖鞋孤零零地躺着。我轻轻叼起来，帮它移动到地毯中央。它没有反抗，说明它愿意玩。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_032", animalKey: "tangyuan_puppy", body: "今天我和一只黄色球进行了长达十分钟的追逐。球一直逃，最后被我按住。汪！球类朋友都很圆滑，但我很有耐心。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_033", animalKey: "tangyuan_puppy", body: "房间里有个枕头，软软的。我把头埋进去，又抬起来，再埋进去。它没有回应，但口感温柔。枕头朋友合格。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_034", animalKey: "tangyuan_puppy", body: "我发现一条毛巾掉在椅子上。它看起来需要散步。我叼着它绕了两圈。人类说放下。好吧，毛巾散步结束。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_035", animalKey: "tangyuan_puppy", body: "今天玩飞盘。飞盘飞出去，我飞出去，风也飞出去。我们三个都很忙。最后我接到了！汪汪汪，天空物品捕获成功。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_036", animalKey: "tangyuan_puppy", body: "鞋带从鞋子上垂下来，一晃一晃。它明显在邀请我。我咬了一下，确认互动。后来被制止。鞋带友谊暂缓发展。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_037", animalKey: "tangyuan_puppy", body: "有个小孩把球滚给我。我没有马上还，因为球太好闻了。闻完以后我还给他。友谊需要来回，也需要充分闻检。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_038", animalKey: "tangyuan_puppy", body: "今天在公园捡到一根树枝。长度适中，咬感优秀，携带时显得我很有任务感。我决定叫它临时棍棍朋友。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_039", animalKey: "tangyuan_puppy", body: "旅馆地毯上有个小绒球。我用爪子拨，它滚；我再拨，它再滚。太配合了。汪，此物具备良好游戏素养。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_040", animalKey: "tangyuan_puppy", body: "晚上我把拖鞋叼到床边。不是捣乱，是陪伴拖鞋。它一天都在地上，很辛苦。柔软朋友也需要被重视。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_041", animalKey: "tangyuan_puppy", body: "今天的花园有三条小路。我每条都走了，因为每条闻起来都不一样。汪，花园不是用眼睛看的，是用鼻子读的。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_042", animalKey: "tangyuan_puppy", body: "我在草丛里发现一只瓢虫。它爬得很慢，但很有目的。我没有碰它，只跟着看了一会儿。小小朋友正在上班。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_043", animalKey: "tangyuan_puppy", body: "喷泉旁边的草最凉，树下的土最香，花坛边的小石头最适合抬爪观察。糖圆花园地图正在更新。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_044", animalKey: "tangyuan_puppy", body: "今天我追一片落叶追到篱笆边。叶子卡住了，我也停下。它不跑了，我就闻闻它。游戏结束，友好收尾。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_045", animalKey: "tangyuan_puppy", body: "花园里有蝴蝶。蝴蝶飞得太没有路线，我追得很开心。追不到也没关系，追的过程已经把尾巴摇累了。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_046", animalKey: "tangyuan_puppy", body: "我在玫瑰旁边打了个喷嚏。花很香，但有点强势。汪，我尊重每朵花的表达欲，只是鼻子需要休息。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_047", animalKey: "tangyuan_puppy", body: "今天找到一块阳光草坪。我滚了一圈，又滚一圈。背上全是草味。非常好，我把花园穿在身上了。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_048", animalKey: "tangyuan_puppy", body: "有个水坑藏在花丛后面。我踩进去，啪唧。脚湿了，心情更好了。水坑朋友很会突然制造惊喜。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_049", animalKey: "tangyuan_puppy", body: "我沿着小路闻到昨天经过的气味，又闻到新的小狗气味。花园每天都在写日记，我负责阅读和补充。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_050", animalKey: "tangyuan_puppy", body: "傍晚花园变得金灿灿。我坐在门口回头看，觉得今天玩得很满。汪，花园明天也会在吧？那就太好了。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_051", animalKey: "tangyuan_puppy", body: "今天到了一个完全陌生的车站。人很多，声音很多，味道更多。我先摇尾巴，再往前走。陌生不等于可怕，陌生等于新朋友很多。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_052", animalKey: "tangyuan_puppy", body: "小巷很窄，我闻了闻墙角，确认有猫、雨和面包。信息齐全，可以通过。汪，糖圆探索队继续前进。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_053", animalKey: "tangyuan_puppy", body: "第一次坐船，地板晃来晃去。我站不稳，但很开心。原来路也可以是水做的！尾巴差点跟着海浪一起摇。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_054", animalKey: "tangyuan_puppy", body: "今天住进新旅馆。我先检查床，再检查窗，再检查有没有拖鞋。拖鞋存在，环境友好。陌生房间马上变熟一点。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_055", animalKey: "tangyuan_puppy", body: "异国街头有人说我听不懂的话。但他笑了，笑容我懂。于是我也笑，尾巴负责翻译。汪，跨语言友谊成立。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_056", animalKey: "tangyuan_puppy", body: "今天坐地铁。门开了，人进去，我也想进去。虽然有点挤，但大家的鞋子味道很丰富。陌生交通工具，评价：刺激。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_057", animalKey: "tangyuan_puppy", body: "一座大桥很长，我从这头走到那头。风吹得耳朵飞起来。走完以后，我回头看桥。汪，我也可以跨过很大的东西。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_058", animalKey: "tangyuan_puppy", body: "陌生公园里没有我认识的树。但每棵树都愿意让我闻一闻。树的社交方式很开放，我喜欢。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_059", animalKey: "tangyuan_puppy", body: "今天听见远处放炮声，我吓了一小下。然后对天空汪汪汪。好了，害怕飞走了。继续走，前面有冰淇淋味。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_060", animalKey: "tangyuan_puppy", body: "夜晚的街灯和家里不一样，但照在地上也很暖。我跟着光走。陌生地方如果有光、有味道、有你，就可以探索。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_061", animalKey: "tangyuan_puppy", body: "今天下雨了！地上出现好多小水坑。我每个都想踩。人类撑伞，我撑耳朵。汪汪，雨天是花园的另一个版本。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_062", animalKey: "tangyuan_puppy", body: "雨滴打在伞上，噼里啪啦像零食袋响。我抬头看了很久。虽然不能吃，但声音很脆。糖圆雨声评分：优秀。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_063", animalKey: "tangyuan_puppy", body: "我在雨后草地上滚了一圈，毛湿了，快乐也湿漉漉的。后来被擦干。擦干也很好，毛巾朋友参与游戏。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_064", animalKey: "tangyuan_puppy", body: "今天雨水把街道洗得亮亮的。每盏灯都有倒影，像灯也生了小狗。汪，我踩过去时，它们轻轻晃。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_065", animalKey: "tangyuan_puppy", body: "雨天路上人少，我可以慢慢闻。每个气味都被水泡软了，更容易读。鼻子说：今日情报湿润丰富。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_066", animalKey: "tangyuan_puppy", body: "我追着一滴从屋檐落下的水跑。它掉得太快，没追上。没关系，后面还有好多滴。机会很多，汪！"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_067", animalKey: "tangyuan_puppy", body: "下雨的时候，面包店香味更明显。热热的味道从门缝里出来，像邀请。我坐在门口，表现乖巧，获得饼干一小块。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_068", animalKey: "tangyuan_puppy", body: "今天风把雨吹到我脸上。我眨眼，打喷嚏，然后笑了。天空也会淘气。汪，淘气朋友可以原谅。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_069", animalKey: "tangyuan_puppy", body: "雨后出现彩虹。我不知道它从哪里来，但它像一根巨大的彩色牵引绳，牵着天空散步。太漂亮了，尾巴停不下来。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_070", animalKey: "tangyuan_puppy", body: "晚上听雨睡觉。滴答滴答，像有人在轻轻拍地板。世界没有关门，只是变小声了。糖圆在毯子里，很安心。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_071", animalKey: "tangyuan_puppy", body: "今天肉丸从盘子边滚走，掉到我够不到的地方。我嗷呜了一声。然后发现旁边还有半块饼干。好了，世界又变好了。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_072", animalKey: "tangyuan_puppy", body: "麻雀没有理我。我对它汪了一声，它飞走了。我有点小失落。三秒后，一片叶子滚过来。新游戏开始！"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_073", animalKey: "tangyuan_puppy", body: "今天被说不能吃第二根香肠。我坐下，眼睛变圆。没有成功。嗷呜。算了，去闻花。花不会限制我闻几次。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_074", animalKey: "tangyuan_puppy", body: "拖鞋被收起来了。我找了一圈，没有找到。略微悲伤。后来发现毛巾还在。毛巾朋友柔软，继续快乐。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_075", animalKey: "tangyuan_puppy", body: "公园门关了，我进不去。我对门汪汪两声。门不懂。没关系，门外也有草，草外也有风。替代方案成立。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_076", animalKey: "tangyuan_puppy", body: "今天洗澡。水很多，泡泡很多，我有点不满意。洗完以后被抱着擦干，还得到零食。重新评估：洗澡可以接受。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_077", animalKey: "tangyuan_puppy", body: "小球滚到沙发底下。我趴着够不到，嗷呜。人类帮我拿出来。委屈结束，球类友谊恢复。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_078", animalKey: "tangyuan_puppy", body: "我想和猫玩，猫说唠唔一样的表情。好吧，它今天不想玩。没关系，我和自己的尾巴玩。尾巴虽然老朋友，也很有趣。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_079", animalKey: "tangyuan_puppy", body: "今天等你回来等了很久。我趴在门口，听很多脚步都不是你。后来你真的来了。前面的不开心，尾巴已经全部扫掉。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_080", animalKey: "tangyuan_puppy", body: "冰淇淋掉了一点在地上，但不让我舔。嗷呜。然后你摸摸我的头。好吧，头也甜。糖圆恢复快乐。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_081", animalKey: "tangyuan_puppy", body: "今天我坐在草地上，想写很深的话。脑袋里只有：汪。汪汪。汪汪汪。很好，层次递进，表达充分。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_082", animalKey: "tangyuan_puppy", body: "我盯着一只球看了很久。球不动，我也不动。然后我突然扑过去。为什么？不知道。球在那，就是理由。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_083", animalKey: "tangyuan_puppy", body: "风吹过来，我耳朵飞起来。脑袋空空，尾巴满满。汪，今天不需要复杂思想，只需要跑。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_084", animalKey: "tangyuan_puppy", body: "我吃了一口饼干，忘记刚才要干什么。饼干脆，世界亮，事情没有饼干重要。等会儿再想。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_085", animalKey: "tangyuan_puppy", body: "今天我走到桥上，左边也想去，右边也想去。于是先原地转圈。转完以后选了闻起来更香的那边。鼻子比脑袋聪明。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_086", animalKey: "tangyuan_puppy", body: "云在飘，我在看。看着看着，我打了个哈欠。云也像在打哈欠。我们都很松软。汪。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_087", animalKey: "tangyuan_puppy", body: "明信片写到一半，我的爪子压住了纸。纸皱了。皱也很可爱，像小山坡。今天的句子可以在小山坡上走。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_088", animalKey: "tangyuan_puppy", body: "我本来想追蝴蝶，后来忘了蝴蝶在哪里。没关系，我发现自己的影子也在跑。影子朋友立刻加入游戏。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_089", animalKey: "tangyuan_puppy", body: "晚上看灯，一盏，两盏，很多盏。数到很多就停。灯亮着，我开心着，数字不重要。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_090", animalKey: "tangyuan_puppy", body: "今天没有想法，只有开心在身体里咕噜咕噜。像肚子里有一锅热汤。汪，不解释，继续摇尾巴。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_091", animalKey: "tangyuan_puppy", body: "今天看见一朵云像大骨头。我想，天上一定有一只超大的狗，把骨头啃得白白的。它会不会也摇尾巴？尾巴应该像彩虹。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_092", animalKey: "tangyuan_puppy", body: "海浪冲上来，我觉得大海在玩捡球。每次把水球丢给岸，岸又推回去。它们玩了好久，体力真好。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_093", animalKey: "tangyuan_puppy", body: "月亮像一块圆饼干。星星是掉下来的饼干屑。天空这么大一张桌子，居然没人打扫。汪，我可以帮忙吃掉吗？"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_094", animalKey: "tangyuan_puppy", body: "火车钻进隧道时，我觉得我们进了一条很长的狗洞。洞里有座位，还有灯。高级狗洞，速度很快。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_095", animalKey: "tangyuan_puppy", body: "风把落叶吹起来，我想它们是一群小黄狗在空中跑。它们不会叫，只会沙沙。非常有礼貌的狗群。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_096", animalKey: "tangyuan_puppy", body: "路灯一盏一盏亮，好像城市在睁眼。每只眼睛都看见我了吗？我对它们汪了一声。晚上好，巨大朋友。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_097", animalKey: "tangyuan_puppy", body: "今天看到一只蜗牛。我觉得它在背着小房子郊游。太聪明了！走到哪里都不用找旅馆。就是速度需要零食鼓励。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_098", animalKey: "tangyuan_puppy", body: "喷泉水花跳起来，像很多透明小狗在蹦。它们落下去又跳起来，不会累。汪，水狗朋友训练有素。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_099", animalKey: "tangyuan_puppy", body: "热气球飘在天上，像一颗大大的彩色零食袋。风把它带走了。我追不上，但我祝它一路香香。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_100", animalKey: "tangyuan_puppy", body: "我看见河水闪闪亮，觉得里面藏着很多小星星。白天星星不能上天，就躲在水里玩。这个安排很合理。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_101", animalKey: "tangyuan_puppy", body: "清晨你给我打开门，阳光和风一起进来。我先闻风，再闻你的手。两样都熟悉。汪，生活从好闻开始。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_102", animalKey: "tangyuan_puppy", body: "今天街边有人把水碗放给路过的小狗。我喝了一点，也留了一点。世界上有这样的水碗，真好。尾巴轻轻摇。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_103", animalKey: "tangyuan_puppy", body: "雨后草地亮晶晶，每根草都像洗过脸。我跑过去，爪子湿了，心也凉凉甜甜。生活有时就是一片会发光的草。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_104", animalKey: "tangyuan_puppy", body: "公园里一个小孩把球扔给我，我叼回来。他笑了，我也笑。球在我们中间跑来跑去，把两个陌生人变成朋友。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_105", animalKey: "tangyuan_puppy", body: "面包店门口有热香味，路边有花香味，你的包里有零食味。三种好味道同时出现。汪，今天是很富有的一天。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_106", animalKey: "tangyuan_puppy", body: "傍晚风吹过耳朵，我走在你旁边。牵引绳松松的，不拉也不紧。这样走路真好，像被世界轻轻牵着。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_107", animalKey: "tangyuan_puppy", body: "旅馆门口有一盏小灯，晚上回来也看得见路。灯不会摸头，但它在等人。会等人的东西，都让我喜欢。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_108", animalKey: "tangyuan_puppy", body: "今天我在雪地里踩出一串爪印。回头看，像自己写了一封给冬天的信。冬天没有回信，但它很白，很安静。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_109", animalKey: "tangyuan_puppy", body: "有个老人坐在长椅上晒太阳，我趴在他脚边。我们没有说话，但太阳把我们晒在一起。汪，这也算一起玩。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_110", animalKey: "tangyuan_puppy", body: "晚上写明信片时，我的鼻子碰到纸，留下一个小点。这个点也要寄给你。今天很好，我也很好，世界也很好。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_111", animalKey: "tangyuan_puppy", body: "这座城市的路牌是蓝色的，下面有很多狗路过留下的气味。人类看字，我看气味。我们各自阅读，互不打扰。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_112", animalKey: "tangyuan_puppy", body: "海边的长椅有三张。第一张晒太阳，第二张有面包屑，第三张旁边有麻雀。综合判断，第二张和第三张都很好。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_113", animalKey: "tangyuan_puppy", body: "早市有鱼摊、花摊和水果摊。鱼摊最吸引鼻子，花摊最吸引蝴蝶，水果摊最吸引小孩。世界分工明确。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_114", animalKey: "tangyuan_puppy", body: "图书馆外面很安静，里面更安静。我不能进去太久，就坐在门口看人。大家抱着书出来，像抱着不叫的朋友。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_115", animalKey: "tangyuan_puppy", body: "街角那棵树很受欢迎。今天至少有四只狗拜访过。树没有说话，但气味层次丰富。汪，社交中心认证。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_116", animalKey: "tangyuan_puppy", body: "公交车停下时会叹气一样开门。人们上去，又下来。它像一只很大的会移动的盒子，专门运送故事。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_117", animalKey: "tangyuan_puppy", body: "雨后的石板路会反光。我看见一只倒过来的小狗跟着我走。它很像我，但不会闻东西。观察结果：影子鼻子功能较弱。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_118", animalKey: "tangyuan_puppy", body: "河边的鸭子排队游过去。队伍不是很整齐，但很可爱。最后一只总是慢半拍。我喜欢它，它有自己的节奏。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_119", animalKey: "tangyuan_puppy", body: "旅馆地毯上有很多花纹。我闻了闻，没有花味。人类常常画不能闻的花，真奇怪。不过看起来也不错。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_120", animalKey: "tangyuan_puppy", body: "今天经过一条窄巷，墙边放着一盆迷迭香。我闻了一下，打了个喷嚏。植物朋友有时表达太浓烈。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_121", animalKey: "tangyuan_puppy", body: "今天我在海边看见一块很适合你坐的石头。我绕着它闻了一圈，确认安全。如果你在，我会把旁边的位置留给你。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_122", animalKey: "tangyuan_puppy", body: "我吃到好吃的饼干，第一反应是想叼一块给你。后来想起明信片不能夹饼干。那我把香味写进去，汪，你闻到了吗？"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_123", animalKey: "tangyuan_puppy", body: "公园里有人叫自己的狗回家。我听见“回家”两个字，尾巴摇了一下。你在的地方，就很像回家。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_124", animalKey: "tangyuan_puppy", body: "今天我跑得很快，快到风追不上。我想让你看见。你要是看见，肯定会说糖圆好棒。好吧，我先自己说：好棒！"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_125", animalKey: "tangyuan_puppy", body: "晚上旅馆很安静，我把头放在爪子上想你。想了一会儿，尾巴自己拍了拍地。原来想念也可以发出小小的开心声。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_126", animalKey: "tangyuan_puppy", body: "我看到一只拖鞋，和你家那只很像。我没有咬太久，只轻轻叼了一下。熟悉的口感让心情变软。汪，想你。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_127", animalKey: "tangyuan_puppy", body: "今天遇到很多人，但没有一个人的脚步声像你。没关系，等下次见面，我会从很远就认出来。鼻子从不迟到。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_128", animalKey: "tangyuan_puppy", body: "我在明信片角落画了一个小爪印。这个爪印先到你那里，我后到。请你先摸摸它，等我回去再摸真的。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_129", animalKey: "tangyuan_puppy", body: "夜里听见门口有人走过，我抬头了。不是你。又走过一个，也不是。后来我睡着了，因为我知道你总会在某个时候出现。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_130", animalKey: "tangyuan_puppy", body: "今天所有风景都很好，但如果你在，我可以带你一处处闻。你负责看，我负责闻。我们合起来，世界就完整一点。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_131", animalKey: "tangyuan_puppy", body: "散步回来时，我看见小朋友扫脸进幼儿园，机器说未注册。他皱着脸说，是我呀。旁边的大人笑着帮他开门。汪，还好，门最后认识他了。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_132", animalKey: "tangyuan_puppy", body: "车站有人刷票失败，闸机滴滴叫。他有点着急，后面的人帮他看了一眼。原来人类虽然会被门卡住，但也会互相解开。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_133", animalKey: "tangyuan_puppy", body: "公园里一个小孩的气球飞走了。他抬头看很久。旁边的小狗跳起来，好像想帮忙追回天空。虽然没追到，但很努力，值得摇尾巴。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_134", animalKey: "tangyuan_puppy", body: "面包店门口有老人慢慢数硬币。店员没有催，还多放了一片面包。老人笑了。我在旁边坐好，觉得面包香里也有温柔味。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_135", animalKey: "tangyuan_puppy", body: "超市自助机识别不了一颗苹果。店员拿起来转了转，苹果安静地等待。汪，苹果没有错，只是机器鼻子不好。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_136", animalKey: "tangyuan_puppy", body: "幼儿园门口有两个孩子抢同一把小铲子，后来他们一起挖坑。坑变大了，朋友也变多了。这个方法很好，可以推广。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_137", animalKey: "tangyuan_puppy", body: "一只麻雀叼着面包屑飞不上台阶，试了三次。第四次成功了。我差点汪出声。小小的胜利也值得很大的尾巴。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_138", animalKey: "tangyuan_puppy", body: "旅馆大厅里有人把伞弄丢了。另一个人追出来还给他。湿漉漉的伞，湿漉漉的谢谢。雨天里也有亮亮的事。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_139", animalKey: "tangyuan_puppy", body: "医院叫号屏跳过一个人，护士很快发现，走过去叫他。他抬头时笑了一下。汪，被补回来也很好，世界有时会回头找你。"),
        PostcardNarrative(id: "tangyuan_puppy_textlib106_140", animalKey: "tangyuan_puppy", body: "邮局里有人寄很远的信。柜员把邮票贴正，轻轻压了一下。纸会走很远，人会等待。明信片也是这样，带着心情跑长途。"),
        PostcardNarrative(id: "moji_cat_textlib106_001", animalKey: "moji_cat", body: "今天我坐在旅馆窗台上，看雨从玻璃往下滑。没有人叫我，也没有脚步靠近。很好，高处良好，尾巴平稳。喵，今日可短暂停留。"),
        PostcardNarrative(id: "moji_cat_textlib106_002", animalKey: "moji_cat", body: "清晨的街还没醒，我蹲在屋檐边，看第一家面包店开灯。热气慢慢冒出来，像一小团安全的雾。我没有下去，只是闻了闻。"),
        PostcardNarrative(id: "moji_cat_textlib106_003", animalKey: "moji_cat", body: "午后阳光落在书柜顶，我把爪子揣起来。下面有人走过，没有发现我。被看不见的时候，我反而不紧张。墨迹记录：隐蔽位置合格。"),
        PostcardNarrative(id: "moji_cat_textlib106_004", animalKey: "moji_cat", body: "今天的海很安静，浪声一下一下，不急。我趴在防波堤最高的石头上，耳朵被风吹凉。没有危险气味。可以眯眼三分钟。"),
        PostcardNarrative(id: "moji_cat_textlib106_005", animalKey: "moji_cat", body: "图书馆的窗台很宽，正好容下一只猫和一束光。我没有翻书，只看灰尘在光里慢慢飘。它们也很安静，像懂规矩的小东西。"),
        PostcardNarrative(id: "moji_cat_textlib106_006", animalKey: "moji_cat", body: "我在老城墙上坐到傍晚。下面的人变小，声音也变软。高处会把世界调低一点。这样很好，太大的世界不适合贴近。"),
        PostcardNarrative(id: "moji_cat_textlib106_007", animalKey: "moji_cat", body: "今天我找到一个屋顶角落，背后是墙，前面是天空。退路清楚，视野开阔。爪爪判断：此处适合把心放松一点点。"),
        PostcardNarrative(id: "moji_cat_textlib106_008", animalKey: "moji_cat", body: "咖啡店窗边有一盆绿植，我藏在它后面看街。人们来来去去，谁也没看见我。喵，这种不被打扰的下午，毛会自己变顺。"),
        PostcardNarrative(id: "moji_cat_textlib106_009", animalKey: "moji_cat", body: "夜里我趴在暖气旁，不靠太近，也不离太远。热气一点点过来，我一点点接受。太突然的温暖会让猫警惕，慢慢来比较好。"),
        PostcardNarrative(id: "moji_cat_textlib106_010", animalKey: "moji_cat", body: "今天没有疯跑，没有炸毛，也没有唠唔。我只是在屋檐上看云变暗。安静不是没心情，是心情终于不用躲来躲去。"),
        PostcardNarrative(id: "moji_cat_textlib106_011", animalKey: "moji_cat", body: "今天一片黄叶从我面前滚过去。我本来只是观察，后来爪子自己伸出去了。追了三条街。喵！叶子行动诡异，但已被我成功驱赶。"),
        PostcardNarrative(id: "moji_cat_textlib106_012", animalKey: "moji_cat", body: "广场上有小孩吹泡泡。泡泡飘得太嚣张，我跳起来拍了一个。它啪地没了。我愣了一下，又拍第二个。今日战绩：泡泡五只。"),
        PostcardNarrative(id: "moji_cat_textlib106_013", animalKey: "moji_cat", body: "海边的绳子在风里晃来晃去，像一条假装无辜的蛇。我蹲了很久，最终扑过去咬了一口。唔，不好吃，但值得确认。"),
        PostcardNarrative(id: "moji_cat_textlib106_014", animalKey: "moji_cat", body: "旅馆走廊太长了，适合突然冲刺。我从门口跑到尽头，又从尽头跑回来。没有理由。猫有时需要把身体里的风放出去。"),
        PostcardNarrative(id: "moji_cat_textlib106_015", animalKey: "moji_cat", body: "今天阳光在墙上晃，我追了半小时。它跑得很快，又没有气味，非常可疑。最后它爬上天花板，我暂时放过它。喵。"),
        PostcardNarrative(id: "moji_cat_textlib106_016", animalKey: "moji_cat", body: "我在市场看见一颗滚落的小橘子。它滚，我追；它停，我也停。摊主笑了。笑就笑吧，墨迹今日运动量达标。"),
        PostcardNarrative(id: "moji_cat_textlib106_017", animalKey: "moji_cat", body: "河边有只鸽子离我三步远。我只是向前挪了一点，它就飞了。反应不错。不是我想抓它，只是测试城市鸟类警觉度。"),
        PostcardNarrative(id: "moji_cat_textlib106_018", animalKey: "moji_cat", body: "今天的窗帘被风吹起来。我扑了三次，每次都没有抓住重点。窗帘这种东西，很会装没事。唠唔，下次继续调查。"),
        PostcardNarrative(id: "moji_cat_textlib106_019", animalKey: "moji_cat", body: "楼梯扶手很滑，我从上面走过去，尾巴保持平衡。下面的人说小心。我当然小心。猫的冒险一般都写着精密计算。"),
        PostcardNarrative(id: "moji_cat_textlib106_020", animalKey: "moji_cat", body: "晚上突然很精神。我在房间里跑了七圈，跳上椅子，又跳下去。你问为什么？不知道。身体说跑，猫就跑。"),
        PostcardNarrative(id: "moji_cat_textlib106_021", animalKey: "moji_cat", body: "刚才我正在安静喝水，忽然背后一阵不存在的风。不好！我立刻从厨房冲到窗边。没有敌人。可能是灵魂里的老鼠经过。"),
        PostcardNarrative(id: "moji_cat_textlib106_022", animalKey: "moji_cat", body: "今天在旅馆地毯上，我突然觉得必须跑。于是我跑。拐弯、刹车、冲刺、跳上床。全部完成后坐下洗脸，假装无事发生。"),
        PostcardNarrative(id: "moji_cat_textlib106_023", animalKey: "moji_cat", body: "黄昏时，街灯刚亮，我的爪子忽然发烫。喵！我沿着石阶一路冲上去。冲到最高处才发现，没人追我。很好，我追的是自己。"),
        PostcardNarrative(id: "moji_cat_textlib106_024", animalKey: "moji_cat", body: "窗外一只鸟叫了一声，我的尾巴瞬间蓬开。下一秒我从桌下飞到柜顶。鸟已离开，但防御动作完美。墨迹记录：反应速度优秀。"),
        PostcardNarrative(id: "moji_cat_textlib106_025", animalKey: "moji_cat", body: "我在海边突然开始绕着一块石头跑。跑了五圈。石头没有反应，说明它不是敌人。也可能是敌人太会伪装。暂不靠近。"),
        PostcardNarrative(id: "moji_cat_textlib106_026", animalKey: "moji_cat", body: "夜里听见塑料袋动了一下。我原地弹起，冲进走廊，又冲回来。袋子只是袋子。唠唔，袋子需要减少可疑行为。"),
        PostcardNarrative(id: "moji_cat_textlib106_027", animalKey: "moji_cat", body: "今天风把一张纸吹起来，我以为它要攻击我。追上去以后发现是菜单。菜单被我按住了。城市餐饮情报成功缴获。"),
        PostcardNarrative(id: "moji_cat_textlib106_028", animalKey: "moji_cat", body: "我蹲在椅子上，突然想起自己是一只猫。于是必须跳到窗台，再跳到桌子，再跳到衣柜顶。身份确认完毕，喵。"),
        PostcardNarrative(id: "moji_cat_textlib106_029", animalKey: "moji_cat", body: "地板上有一块光斑，忽然移动。我冲过去，它又跑。太过分了。追到墙角后，它消失了。光斑这种猎物，缺乏实体道德。"),
        PostcardNarrative(id: "moji_cat_textlib106_030", animalKey: "moji_cat", body: "今天没有任何原因，我从屋顶这一头跑到那一头。风在耳边呼呼响。跑完以后心里舒服了。也许身体里有些害怕，需要用速度甩掉。"),
        PostcardNarrative(id: "moji_cat_textlib106_031", animalKey: "moji_cat", body: "我蹲在钟楼边缘，看下面的人像小鱼一样游来游去。谁抬头，谁低头，谁急着回家，我都看见了。高处良好，心跳平稳。"),
        PostcardNarrative(id: "moji_cat_textlib106_032", animalKey: "moji_cat", body: "旅馆衣柜顶是今日最佳地点。门口、床、窗户、行李都在视线内。别人以为我在躲，其实我在管理全局。爪爪记录。"),
        PostcardNarrative(id: "moji_cat_textlib106_033", animalKey: "moji_cat", body: "我坐在桥栏上看船经过。船很大，人很小，水声很远。高处让一切保持距离。距离合适时，世界看起来比较温柔。"),
        PostcardNarrative(id: "moji_cat_textlib106_034", animalKey: "moji_cat", body: "咖啡馆二楼窗台可以看见整条街。有人等人，有人迟到，有人把花藏在背后。我不参与，但都知道。猫不说，不代表没看见。"),
        PostcardNarrative(id: "moji_cat_textlib106_035", animalKey: "moji_cat", body: "今天爬上老城墙，风把胡须吹向一边。下面的热闹离我有点远，刚刚好。太近会乱，太远会冷。这里合适。"),
        PostcardNarrative(id: "moji_cat_textlib106_036", animalKey: "moji_cat", body: "书店最高的架子旁有个小平台。我坐在那里，看人们挑书。每个人都像在找一扇门。我不找门，我找出口。"),
        PostcardNarrative(id: "moji_cat_textlib106_037", animalKey: "moji_cat", body: "我在屋顶看见一只狗追自己的尾巴。它很快乐，也很不警惕。狗类生存策略令猫困惑。但看着它转圈，我小声喵了一下。"),
        PostcardNarrative(id: "moji_cat_textlib106_038", animalKey: "moji_cat", body: "今天山坡上有一棵高树。我爬到枝杈间，看湖水亮成一片。树很稳，风也不凶。这个高度可以相信，暂时。"),
        PostcardNarrative(id: "moji_cat_textlib106_039", animalKey: "moji_cat", body: "我趴在教堂石兽旁边，和它一起看广场。它很会保持沉默。我喜欢沉默的同伴。不会突然伸手，也不会问我为什么一个人。"),
        PostcardNarrative(id: "moji_cat_textlib106_040", animalKey: "moji_cat", body: "夜里我坐在屋檐上，看每扇窗慢慢变暗。城市睡觉也有顺序。最后一盏灯灭掉时，我还醒着。猫负责夜班观察。"),
        PostcardNarrative(id: "moji_cat_textlib106_041", animalKey: "moji_cat", body: "今天有人突然从背后说你好。我整只猫跳起来，尾巴蓬成一把刷子。对方道歉了。唠唔，可以原谅，但请所有人禁止背后出现。"),
        PostcardNarrative(id: "moji_cat_textlib106_042", animalKey: "moji_cat", body: "街口摩托车忽然发动，声音像铁皮怪物咳嗽。我立刻钻进花盆后面。花盆土味浓，但安全。墨迹记录：花盆可作为临时掩体。"),
        PostcardNarrative(id: "moji_cat_textlib106_043", animalKey: "moji_cat", body: "旅馆门铃响得太突然。我从床边蹿到柜顶，爪子还踩歪了明信片。门铃没有恶意，但它太没礼貌。唠唔。"),
        PostcardNarrative(id: "moji_cat_textlib106_044", animalKey: "moji_cat", body: "今天广场上气球爆了。我耳朵一瞬间贴平，心跳跑到前面。小孩笑了，我没笑。不是所有响声都适合庆祝。"),
        PostcardNarrative(id: "moji_cat_textlib106_045", animalKey: "moji_cat", body: "电梯门叮的一声打开，我以为世界裂开了。退后三步，观察十秒，确认只是电梯。人类发明很多东西，但不太考虑猫的神经。"),
        PostcardNarrative(id: "moji_cat_textlib106_046", animalKey: "moji_cat", body: "雨棚上突然落下一大滴水，正好砸在我旁边。喵？不，唠唔。天空应该提前通知。无预警滴水行为不予批准。"),
        PostcardNarrative(id: "moji_cat_textlib106_047", animalKey: "moji_cat", body: "今天一只海鸥从头顶掠过，影子刷地一下盖住我。我趴低，耳朵警戒。影子没有爪子，但也不能完全相信。"),
        PostcardNarrative(id: "moji_cat_textlib106_048", animalKey: "moji_cat", body: "街头艺人突然敲鼓，我差点把自己弹到隔壁摊位。鼓声很热闹，但热闹不等于安全。尾巴已蓬，情况待查。"),
        PostcardNarrative(id: "moji_cat_textlib106_049", animalKey: "moji_cat", body: "旅馆窗帘自己动了。我盯了它很久，最后发现是风。风没有形状，所以更可疑。暂定：风可以存在，但不得偷袭。"),
        PostcardNarrative(id: "moji_cat_textlib106_050", animalKey: "moji_cat", body: "夜里楼上传来一声重物落地。我立刻坐起，眼睛全开。后来安静了。可我还是等了很久才睡。流浪猫的睡眠，从来不是完全交出去的。"),
        PostcardNarrative(id: "moji_cat_textlib106_051", animalKey: "moji_cat", body: "今天你坐在长椅上，我走到你旁边。距离两爪半，安全。后来风有点冷，我又近了一点。不是依赖，只是风向需要调整。"),
        PostcardNarrative(id: "moji_cat_textlib106_052", animalKey: "moji_cat", body: "我在明信片上写到你时，尾巴尖动了一下。喵。这个动作不代表什么，可能只是肌肉反应。但我没有把你的名字划掉。"),
        PostcardNarrative(id: "moji_cat_textlib106_053", animalKey: "moji_cat", body: "咖啡馆里你给我留了窗边位置。我先绕了一圈确认出口，然后才跳上去。靠近不是不可以，只要退路还在。"),
        PostcardNarrative(id: "moji_cat_textlib106_054", animalKey: "moji_cat", body: "今天我差点把头靠到你的手边。差一点。后来又收回来了。不是不喜欢，是太近会让心里响警报。请慢一点。"),
        PostcardNarrative(id: "moji_cat_textlib106_055", animalKey: "moji_cat", body: "你叫我墨迹的时候，我回头了。只回头一下。名字这种东西，如果被叫得太温柔，猫会有点不知道该躲还是该走近。"),
        PostcardNarrative(id: "moji_cat_textlib106_056", animalKey: "moji_cat", body: "晚上我坐在你房门外。没有进去，也没有离开。门缝里有一点光。喵，我只是检查光有没有安全，不是等你。"),
        PostcardNarrative(id: "moji_cat_textlib106_057", animalKey: "moji_cat", body: "你把鱼干放在我面前，没有盯着我看。很好，礼貌投喂。我吃完后坐远了一点，但没有走。这个距离，算信任。"),
        PostcardNarrative(id: "moji_cat_textlib106_058", animalKey: "moji_cat", body: "今天我从屋檐跳下来，落在离你不远的地方。你没有伸手抓我。非常好。猫会记住这种不抓。墨迹记录：可再靠近半步。"),
        PostcardNarrative(id: "moji_cat_textlib106_059", animalKey: "moji_cat", body: "我把尾巴尖轻轻碰了你一下，然后立刻看向别处。那不是故意的。也许是。不能确认。猫的证词不完全可靠。"),
        PostcardNarrative(id: "moji_cat_textlib106_060", animalKey: "moji_cat", body: "夜里我终于在你旁边睡了十分钟。十分钟后我醒来，换到柜顶。不是后悔，是习惯。靠近要分段进行。"),
        PostcardNarrative(id: "moji_cat_textlib106_061", animalKey: "moji_cat", body: "今天巷口有一只小猫在翻垃圾桶。我停下看了很久。它的背很瘦，耳朵却竖得很直。我认识那种竖法：害怕，但不能输。"),
        PostcardNarrative(id: "moji_cat_textlib106_062", animalKey: "moji_cat", body: "雨下起来时，我躲进屋檐下。水味一上来，我忽然想起小时候某个夜里，我也是这样缩着。那时没有明信片，只有湿掉的爪子。"),
        PostcardNarrative(id: "moji_cat_textlib106_063", animalKey: "moji_cat", body: "市场后门有鱼腥味。我以前常在这种地方等，等谁扔出一点不能卖的边角。今天我买得到完整的鱼干了，可鼻子还是先记起旧日子。"),
        PostcardNarrative(id: "moji_cat_textlib106_064", animalKey: "moji_cat", body: "看见一只猫妈妈带着幼猫过马路，我站到墙上。小猫们挤在她肚子旁边。我对妈妈的记忆很模糊，像一团快要散掉的热气。"),
        PostcardNarrative(id: "moji_cat_textlib106_065", animalKey: "moji_cat", body: "有人在街边喊猫咪过来。我没过去。小时候也有人这样喊，有的手温柔，有的手很重。长大后，猫先记住重的那部分。"),
        PostcardNarrative(id: "moji_cat_textlib106_066", animalKey: "moji_cat", body: "旅馆床很软，我却先看床底能不能钻。流浪久了，任何新地方都要先确认藏身处。柔软很好，但出口更重要。"),
        PostcardNarrative(id: "moji_cat_textlib106_067", animalKey: "moji_cat", body: "今天路过一扇关着的后门。我站了一会儿。小时候有些门会开，有些门永远不开。门不会解释。猫只能学会不等太久。"),
        PostcardNarrative(id: "moji_cat_textlib106_068", animalKey: "moji_cat", body: "夜里垃圾车经过，声音很大。我忽然醒得很彻底。以前这种声音代表要换地方了。现在不用换，可身体还没完全相信。"),
        PostcardNarrative(id: "moji_cat_textlib106_069", animalKey: "moji_cat", body: "我看见一只很老的流浪猫晒太阳。它一只眼半闭着，像什么都知道。我没有靠近，只远远点了下尾巴。我们这种猫，不需要寒暄。"),
        PostcardNarrative(id: "moji_cat_textlib106_070", animalKey: "moji_cat", body: "今天有人把剩饭倒进袋子，我听见塑料声就回头。明明已经不饿了。唠唔，旧习惯像藏在骨头里的小铃铛，一响就听见。"),
        PostcardNarrative(id: "moji_cat_textlib106_071", animalKey: "moji_cat", body: "这座城市的屋顶大多是红色的，适合猫在黄昏时藏身。烟囱之间距离不远，可以跳。爪爪记录：路线可行。"),
        PostcardNarrative(id: "moji_cat_textlib106_072", animalKey: "moji_cat", body: "海边的长椅有三张，第二张晒得最暖。第一张旁边有狗味，第三张有小孩掉的糖纸。综合判断，第二张适合短暂停留。"),
        PostcardNarrative(id: "moji_cat_textlib106_073", animalKey: "moji_cat", body: "早市六点开始亮灯。鱼摊最早，花摊最香，面包摊最容易让猫分心。摊主走路的声音都不同，可以闭眼辨认。"),
        PostcardNarrative(id: "moji_cat_textlib106_074", animalKey: "moji_cat", body: "图书馆的地板会轻轻响。穿皮鞋的人响，穿软鞋的人不响。猫更喜欢软鞋，因为软鞋不突然。"),
        PostcardNarrative(id: "moji_cat_textlib106_075", animalKey: "moji_cat", body: "街角有一台自动贩卖机，夜里也亮。它不会伸手，不会说话，只吐出饮料。稳定、可预测，值得信任一点点。"),
        PostcardNarrative(id: "moji_cat_textlib106_076", animalKey: "moji_cat", body: "今天的云很低，像一群灰猫趴在城市上方。风从左边来，雨大概在右边等。胡须判断：半小时内应找屋檐。"),
        PostcardNarrative(id: "moji_cat_textlib106_077", animalKey: "moji_cat", body: "广场上的鸽子有固定巡逻路线。它们先到喷泉，再到面包店门口，最后去雕像脚下。鸽子看似随意，其实很懂饭点。"),
        PostcardNarrative(id: "moji_cat_textlib106_078", animalKey: "moji_cat", body: "旅馆楼梯第七级会吱呀响。以后夜里经过，要跳过第七级。不是怕吵到别人，是不想让世界知道我在哪里。"),
        PostcardNarrative(id: "moji_cat_textlib106_079", animalKey: "moji_cat", body: "河边的狗会追球，但每次都会回到主人脚边。球离开，狗追；主人不动，狗回来。犬类的中心很明确，猫类暂不评价。"),
        PostcardNarrative(id: "moji_cat_textlib106_080", animalKey: "moji_cat", body: "今天经过窄巷，墙上有三处爪痕。高度不同，说明来过不止一只猫。没有新鲜气味，只是旧痕迹。此地曾经被别的猫确认过。"),
        PostcardNarrative(id: "moji_cat_textlib106_081", animalKey: "moji_cat", body: "今天我看着月亮，觉得它是一只巨大的白碗，里面装满了没喝完的牛奶。云从旁边经过，像有人悄悄把碗推远。喵，浪费。"),
        PostcardNarrative(id: "moji_cat_textlib106_082", animalKey: "moji_cat", body: "屋顶上的烟囱像一群沉默的黑猫，排队看天。它们不动，是因为白天太多人。到半夜也许会伸懒腰，互相交换梦。"),
        PostcardNarrative(id: "moji_cat_textlib106_083", animalKey: "moji_cat", body: "海浪一下一下拍岸，我怀疑海底有一只大猫在舔爪子。每舔一下，水就翻上来。它一定很大，胡须可能有桥那么长。"),
        PostcardNarrative(id: "moji_cat_textlib106_084", animalKey: "moji_cat", body: "火车进隧道时，我觉得自己被一条黑蛇吞进肚子。蛇肚子里有灯和座椅。它没有咬人，说明是受过训练的交通蛇。"),
        PostcardNarrative(id: "moji_cat_textlib106_085", animalKey: "moji_cat", body: "路灯亮起来时，城市像被一只看不见的爪子点醒。这里一点，那里一点。最后整条街都睁开眼。墨迹判断：夜晚开始值班。"),
        PostcardNarrative(id: "moji_cat_textlib106_086", animalKey: "moji_cat", body: "我看见一片叶子在地上转圈，忽然觉得它在跳舞。也许风是它的音乐老师。叶子跳得不专业，但很投入，可以给三声喵。"),
        PostcardNarrative(id: "moji_cat_textlib106_087", animalKey: "moji_cat", body: "云像鱼骨头一样横在天上。我抬头看了很久，想象有一只天上的猫吃完晚饭，把骨头忘在蓝色盘子里。"),
        PostcardNarrative(id: "moji_cat_textlib106_088", animalKey: "moji_cat", body: "电线上的鸟排成一串，像一行会动的标点。它们如果一起飞走，天空这句话就会断掉。喵，希望它们至少留下一个逗号。"),
        PostcardNarrative(id: "moji_cat_textlib106_089", animalKey: "moji_cat", body: "今天的雾从河上升起来，像城市在冒热气。也许地下有一锅巨大的汤。里面有鱼吗？这个幻想很危险，因为它让我饿了。"),
        PostcardNarrative(id: "moji_cat_textlib106_090", animalKey: "moji_cat", body: "我看见一只蜗牛背着壳过路。我想它不是慢，是带着整间房旅行。猫也想要这样的房子：能藏，能睡，且随时可撤。"),
        PostcardNarrative(id: "moji_cat_textlib106_091", animalKey: "moji_cat", body: "今天没有危险，食物也够，房间也暖。可我还是有点低。像屋顶上晒不到太阳的一块瓦。唠唔，找不到原因，就先不动。"),
        PostcardNarrative(id: "moji_cat_textlib106_092", animalKey: "moji_cat", body: "我坐在窗台上，看下面的人结伴走过。没有谁赶我，也没有谁等我。一个人很好，一个人也会忽然有点空。两件事可以同时成立。"),
        PostcardNarrative(id: "moji_cat_textlib106_093", animalKey: "moji_cat", body: "旅馆床很软，我却睡在边缘。中间那么大，好像不是给我的。流浪猫会习惯只占一点地方，哪怕没人和我抢。"),
        PostcardNarrative(id: "moji_cat_textlib106_094", animalKey: "moji_cat", body: "今天看见一只猫被抱在怀里，它没有挣扎。它闭着眼，像完全相信那双手。我看了一会儿，转身走开。不是羡慕。也许是。"),
        PostcardNarrative(id: "moji_cat_textlib106_095", animalKey: "moji_cat", body: "我买了鱼干，却没有立刻吃。以前吃东西要快，怕被抢。现在可以慢慢吃，可我有时不知道慢慢吃该怎么做。"),
        PostcardNarrative(id: "moji_cat_textlib106_096", animalKey: "moji_cat", body: "傍晚风变凉，我想起自己很小的时候，也曾经贴着什么温暖的东西睡。那是什么样子，已经记不清。只剩身体还记得一点点。"),
        PostcardNarrative(id: "moji_cat_textlib106_097", animalKey: "moji_cat", body: "今天不想写明信片。可是如果不写，你就不知道我今天还在屋檐上。于是我写了。字有点斜，心也有点斜。"),
        PostcardNarrative(id: "moji_cat_textlib106_098", animalKey: "moji_cat", body: "城市很热闹，热闹像一张大网。我站在网外看。网里有灯，有笑声，有人回家。网外也安全，只是风会多一点。"),
        PostcardNarrative(id: "moji_cat_textlib106_099", animalKey: "moji_cat", body: "晚上听见远处有猫叫。我没有回应。不是不想，是回应以后可能会发生太多事。独自生活久了，连同类的声音也像风险。"),
        PostcardNarrative(id: "moji_cat_textlib106_100", animalKey: "moji_cat", body: "我忽然很想有一个不需要判断出口的地方。进去以后不用先看床底，不用听脚步，不用随时准备跑。这样的地方，也许叫家。"),
        PostcardNarrative(id: "moji_cat_textlib106_101", animalKey: "moji_cat", body: "今天我在港口吃到一小块烤鱼。热的，香的，没有人抢。喵！我吃完还舔了三遍爪子。墨迹宣布：此港口表现优秀。"),
        PostcardNarrative(id: "moji_cat_textlib106_102", animalKey: "moji_cat", body: "屋顶上有一片阳光刚好铺开，大小正合适。我趴进去，整只猫都被晒软。喵，今天太阳懂猫，值得表扬。"),
        PostcardNarrative(id: "moji_cat_textlib106_103", animalKey: "moji_cat", body: "我跳上书柜顶，一次成功，落点精准。下面的人惊呼了一声。哼，这不是表演，是基本能力。不过被看见厉害，确实有点开心。"),
        PostcardNarrative(id: "moji_cat_textlib106_104", animalKey: "moji_cat", body: "今天窗外有小鸟唱歌。我没有扑它，只听。它唱得很亮，像把空气啄出了小洞。喵，早晨从洞里漏进来了。"),
        PostcardNarrative(id: "moji_cat_textlib106_105", animalKey: "moji_cat", body: "你给我留了鱼干，还没有盯着我吃。太好了。信任环境、食物合格、距离安全。喵喵，今日可把尾巴放松。"),
        PostcardNarrative(id: "moji_cat_textlib106_106", animalKey: "moji_cat", body: "我在街角发现一个纸箱，大小完美，干燥，背风。纸箱是猫类临时宫殿。我进去坐了五分钟，心情明显变好。"),
        PostcardNarrative(id: "moji_cat_textlib106_107", animalKey: "moji_cat", body: "今天我追到了一片光斑。虽然它最后又逃走，但我确实按住了它半秒。半秒也是胜利。喵，猎手状态上线。"),
        PostcardNarrative(id: "moji_cat_textlib106_108", animalKey: "moji_cat", body: "海边风很大，把我的毛吹得乱七八糟。我本来想生气，但风里有鱼味。鱼味抵消混乱。喵，批准继续吹。"),
        PostcardNarrative(id: "moji_cat_textlib106_109", animalKey: "moji_cat", body: "晚上有烟花。我一开始躲到椅子下，后来发现天空在开花。保持距离后，烟花可以观看。喵，远处的热闹还不错。"),
        PostcardNarrative(id: "moji_cat_textlib106_110", animalKey: "moji_cat", body: "今天你叫我名字，我走过去了。不是马上，是绕了一圈以后。可是我去了。喵，这件事我不解释，但可以记录。"),
        PostcardNarrative(id: "moji_cat_textlib106_111", animalKey: "moji_cat", body: "今天我趴在窗台上，脑袋里只有风。风从左耳进，右耳出。没有留下什么。很好，脑袋通风，适合晒太阳。"),
        PostcardNarrative(id: "moji_cat_textlib106_112", animalKey: "moji_cat", body: "我盯着一只杯子看了很久。杯子不动，我也不动。后来忘记谁先开始的。杯子赢了还是我赢了？唔，不重要。"),
        PostcardNarrative(id: "moji_cat_textlib106_113", animalKey: "moji_cat", body: "明信片写到一半，爪子停住。脑袋里只有：喵。喵。喵。三声整齐，可以算内容。猫的沉默也有格式。"),
        PostcardNarrative(id: "moji_cat_textlib106_114", animalKey: "moji_cat", body: "今天看云，看到忘记自己在看云。等回神时，云已经换了形状。它没有等我。没关系，猫也常常不等别人。"),
        PostcardNarrative(id: "moji_cat_textlib106_115", animalKey: "moji_cat", body: "我吃了一口鱼干，然后忘记刚才在想什么。鱼干占领大脑，合理。重要事情如果重要，应该会自己回来。"),
        PostcardNarrative(id: "moji_cat_textlib106_116", animalKey: "moji_cat", body: "地板上有一条光。我把爪子放上去，又拿开，再放上去。没有结论。只是暖。暖有时候不需要结论。"),
        PostcardNarrative(id: "moji_cat_textlib106_117", animalKey: "moji_cat", body: "我坐在楼梯上，上一阶也行，下一阶也行。于是哪里也不去。楼梯负责选择困难，猫负责发呆。"),
        PostcardNarrative(id: "moji_cat_textlib106_118", animalKey: "moji_cat", body: "今天风铃响了一下午。我听着听着，脑袋像被洗干净的碗。里面什么都没有，只有叮叮当当。还挺亮。"),
        PostcardNarrative(id: "moji_cat_textlib106_119", animalKey: "moji_cat", body: "我在纸箱里待着，忘了时间。纸箱没有时间，只有四面墙和一点纸味。猫在纸箱里可以暂时不用思考。"),
        PostcardNarrative(id: "moji_cat_textlib106_120", animalKey: "moji_cat", body: "晚上看灯，一盏，两盏，很多盏。数到很多就不数了。城市自己亮着，不需要我一盏盏批准。"),
        PostcardNarrative(id: "moji_cat_textlib106_121", animalKey: "moji_cat", body: "清晨太阳落在窗台上，先暖到我的爪子，再暖到肚皮。它没有突然靠近，只是一点点来。这样的温柔，猫可以接受。"),
        PostcardNarrative(id: "moji_cat_textlib106_122", animalKey: "moji_cat", body: "雨停以后，屋檐滴水。每滴水落下前都会亮一下，像小小的鱼鳞。世界有时候很会藏漂亮东西，只给安静的猫看。"),
        PostcardNarrative(id: "moji_cat_textlib106_123", animalKey: "moji_cat", body: "小巷里有热汤味，也有面包味。人们开门、扫地、说早安。我站在墙头看，觉得城市正在慢慢伸懒腰。喵，很好。"),
        PostcardNarrative(id: "moji_cat_textlib106_124", animalKey: "moji_cat", body: "今天我看见老人给流浪猫放水。他放下就走，没有伸手抓。那只猫喝了。我也看见了。世界偶尔会有很懂距离的善意。"),
        PostcardNarrative(id: "moji_cat_textlib106_125", animalKey: "moji_cat", body: "傍晚的风不冷不热，刚好穿过胡须。树叶轻轻动，像很多小爪子在挥手。此地可短暂停留，心也可短暂柔软。"),
        PostcardNarrative(id: "moji_cat_textlib106_126", animalKey: "moji_cat", body: "我在桥上看河水带走晚霞。颜色碎碎的，却没有丢。水把漂亮东西带去远处，不私藏。这个行为值得一声喵。"),
        PostcardNarrative(id: "moji_cat_textlib106_127", animalKey: "moji_cat", body: "旅馆老板在门口留灯，说夜里回来的人看得见路。灯不是专门给猫的，但我也用到了。被不是专门的温柔照到，也很好。"),
        PostcardNarrative(id: "moji_cat_textlib106_128", animalKey: "moji_cat", body: "今天鱼干是温的，窗台是暖的，风是轻的。三件事同时合格。生活不一定要完全安全，只要有几个地方不伤猫。"),
        PostcardNarrative(id: "moji_cat_textlib106_129", animalKey: "moji_cat", body: "夜晚的街慢慢安静，店门一扇一扇关上。我在屋顶上听。世界收起爪子的声音，很轻。这样的夜，适合睡。"),
        PostcardNarrative(id: "moji_cat_textlib106_130", animalKey: "moji_cat", body: "我写明信片时，灯光落在纸上，尾巴圈住爪子。想到你会读到，我没有躲开这个念头。喵，能把今天寄出去，是好事。"),
        PostcardNarrative(id: "moji_cat_textlib106_131", animalKey: "moji_cat", body: "散步回来时，我看见一只猫站在玻璃门外。里面的人喊了它的名字，却没有开门。它尾巴动了一下，又坐下。门会看见，却不一定让进。"),
        PostcardNarrative(id: "moji_cat_textlib106_132", animalKey: "moji_cat", body: "车站闸机一直响，一个人明明拿着票，却过不去。他把票翻来翻去，像在向机器证明自己。机器不听解释。唠唔，门类都很固执。"),
        PostcardNarrative(id: "moji_cat_textlib106_133", animalKey: "moji_cat", body: "旅馆前台说查不到预订。那个人站在那里，手里有短信，有行李，也有疲惫。屏幕说没有时，人会忽然像站在雨里。"),
        PostcardNarrative(id: "moji_cat_textlib106_134", animalKey: "moji_cat", body: "学校门口，一个孩子刷卡失败。老师说系统没更新。他点头，很乖。可是他的脚没有动，好像还在等世界把他认出来。"),
        PostcardNarrative(id: "moji_cat_textlib106_135", animalKey: "moji_cat", body: "超市门口的感应门没有为一位老人打开。他往前一步，门不动；再退一步，门也不动。我在旁边看着，觉得玻璃很冷。"),
        PostcardNarrative(id: "moji_cat_textlib106_136", animalKey: "moji_cat", body: "博物馆验票机说无效。女孩把票贴得更认真，还是无效。她看着票，好像票突然不站在她那边了。猫懂这种感觉。"),
        PostcardNarrative(id: "moji_cat_textlib106_137", animalKey: "moji_cat", body: "我看见一只狗跑到旧店门口摇尾巴。店主换了，不认识它，把门关上。狗坐了一会儿。记得路，不代表还能回去。"),
        PostcardNarrative(id: "moji_cat_textlib106_138", animalKey: "moji_cat", body: "公寓楼下有人按密码，按了三次都错。他笑着说以前住这里。门没有笑。原来以前不能开门，哪怕你真的以前在里面。"),
        PostcardNarrative(id: "moji_cat_textlib106_139", animalKey: "moji_cat", body: "邮局里有人说包裹是他的，柜员说姓名不对。他重复自己的名字，声音越来越小。名字明明跟着人很久，有时却不够用。"),
        PostcardNarrative(id: "moji_cat_textlib106_140", animalKey: "moji_cat", body: "医院叫号屏跳过一个号码。那个人每次抬头，又慢慢低下去。被漏掉不是一声巨响，是很多次没有轮到。猫在角落看见了。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_001", animalKey: "dengdeng_rabbit", body: "今天我在街角买到一根很甜的小胡萝卜。不是最大的那根，但刚好适合我抱着啃。一点点也算很满足。灯灯记录：今日甜味充足。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_002", animalKey: "dengdeng_rabbit", body: "海边的风把我的耳朵吹得一高一低。我本来有点不好意思，后来发现小孩看见我笑了。好吧，如果我的耳朵能让别人开心一秒，也算不错。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_003", animalKey: "dengdeng_rabbit", body: "我在面包店门口闻到黄油香。排队的人很多，但最后刚好还剩一个小圆面包。它没有被别人拿走，也没有被我让出去。今天这个面包是我的，嗯，轻轻高兴。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_004", animalKey: "dengdeng_rabbit", body: "小火车经过山谷时，窗外的草地一块一块跑过去，像绿色毯子被谁慢慢抖开。我坐在靠窗的位置，没有人和我挤。这个位置刚刚好，给我留了一小格。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_005", animalKey: "dengdeng_rabbit", body: "广场上有喷泉，水花升起来又落下，像很多透明兔子在跳。它们跳得不整齐，但很快乐。我看着看着，脚尖也跟着动了一下。只动一下，不算太显眼。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_006", animalKey: "dengdeng_rabbit", body: "旅馆老板送我一块草莓饼干。我问是不是多出来的，他说是特意给我的。特意这个词很亮，像有人把灯转向我。我咬了一小口，甜得耳朵都热了。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_007", animalKey: "dengdeng_rabbit", body: "今天的云像一团团棉花。我很想把它们分给大家，一人一朵，谁也不落下。后来想想，天空这么大，也许不用分。每只兔子抬头都能看见。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_008", animalKey: "dengdeng_rabbit", body: "我在旧书店找到一本很薄的诗集，封面上画着月亮和兔子。虽然兔子画得不像我，但我还是买下了。被画在封面上，哪怕不是本人，也有一点被看见的感觉。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_009", animalKey: "dengdeng_rabbit", body: "阳光落在我的耳朵尖上，暖暖的。我坐在长椅上多待了五分钟。今天没有谁催我，也没有谁需要我让座。五分钟全是我的。灯灯记录：珍贵。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_010", animalKey: "dengdeng_rabbit", body: "桥上的风轻轻推着我往前走。我没有跑，也没有躲，只是一步一步走过去。风好像没有要带走我，只是陪我一段。这样也很好，一点点陪伴也算。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_011", animalKey: "dengdeng_rabbit", body: "今天看见一家人坐在窗边吃晚饭。妈妈把最大的一块土豆夹给最小的孩子。那个孩子没有说谢谢，好像本来就该有。我站在玻璃外面想，原来有人可以不排队就被照顾。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_012", animalKey: "dengdeng_rabbit", body: "面包店里，一个爸爸把女儿抱起来看橱窗。她指什么，他就认真听。我忽然想起小时候我也举过爪子，可屋里太吵，没人看见。不是他们不爱我，只是声音太多了。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_013", animalKey: "dengdeng_rabbit", body: "公园里有几只小兔子围着妈妈睡觉，最中间那只被抱得最紧。我本来想笑，因为它耳朵压歪了。后来又没笑。小时候我总睡在边边，边边也暖，只是不够暖。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_014", animalKey: "dengdeng_rabbit", body: "钟楼响了八下。旁边的小孩问妈妈几点了，妈妈低头说，是该回家吃饭了。我听见“回家吃饭”这几个字，耳朵慢慢垂下来。有些话很普通，但会把心轻轻碰疼。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_015", animalKey: "dengdeng_rabbit", body: "我在集市看见一篮草莓，摊主把最红的那颗挑给自己的孩子。我买到的也很好，只是没有那么红。没关系，我从小就擅长拿第二好的东西。第二好也可以甜。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_016", animalKey: "dengdeng_rabbit", body: "旅馆房间里有两张枕头，一张大，一张小。我把大的放到旁边，自己睡小的。躺下以后才发现，房间里只有我。原来有些习惯，会在不需要让的时候继续让。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_017", animalKey: "dengdeng_rabbit", body: "今天有个孩子摔倒了，身边好几个人立刻围过去。我停在远处看了一会儿。被很多人同时担心，应该是什么感觉呢？我没有答案，只把这个问题折进明信片里。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_018", animalKey: "dengdeng_rabbit", body: "我路过玩具店，看见橱窗里有一只独自坐在中间的白兔玩偶。它没有兄弟姐妹挤在旁边，灯光也只照着它。我站了很久。不是羡慕玩偶，只是羡慕那束光。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_019", animalKey: "dengdeng_rabbit", body: "晚上听见隔壁房间有人说：“今天辛苦你了。”声音很轻。我把耳朵贴近被子，假装这句话也分给我一点。只分一点点就好，我很会节省这种东西。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_020", animalKey: "dengdeng_rabbit", body: "港口有人送别，大家都挥手喊同一个名字。那个名字在风里被叫了很多遍。我忽然想，小时候家里叫“孩子们”的时候，我也会回头。可我更想听见“灯灯”。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_021", animalKey: "dengdeng_rabbit", body: "这座城市的路牌是绿色的，边角有一点掉漆。路口第三家咖啡店门口放着两盆薄荷。薄荷叶子朝阳光那边偏，像在排队晒耳朵。灯灯记录。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_022", animalKey: "dengdeng_rabbit", body: "今天的海浪每次上岸都会带来一点白沫。白沫很快消失，好像从来没来过。沙滩上有小小的洞，大概是螃蟹住的地方。它们的门口没有门铃。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_023", animalKey: "dengdeng_rabbit", body: "广场上的鸽子走路很有自信，头一点一点的。它们看起来不像在散步，更像在检查地面有没有面包屑。中间那只灰鸽子很胖，但飞起来并不慢。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_024", animalKey: "dengdeng_rabbit", body: "这里的公交车座椅是蓝色的，靠窗的位置最先被坐满。人们上车后会先看手机，再看窗外。窗外其实也很好看，只是不会发通知。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_025", animalKey: "dengdeng_rabbit", body: "早市从六点半开始热闹。卖花的人先把桶里的水换掉，卖水果的人把苹果擦亮。每个摊位都在慢慢变成今天的样子。这个过程很安静，也很认真。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_026", animalKey: "dengdeng_rabbit", body: "今天的云移动得很慢，像不着急回家的羊。左边那朵像胡萝卜，右边那朵像一只躺平的兔子。云的形状没有固定规则，但观察起来很省力。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_027", animalKey: "dengdeng_rabbit", body: "图书馆里有很多翻书声。有的人翻得很轻，有的人像在赶时间。靠窗的小朋友把书立起来挡住脸，只露出眼睛。这个行为我理解，书也可以当小洞穴。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_028", animalKey: "dengdeng_rabbit", body: "山路边有许多小石头，颜色从白到灰都有。我挑了一颗放在掌心，又放回去。它在那条路上比较合适。我已经看见它了，不一定非要带走。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_029", animalKey: "dengdeng_rabbit", body: "旅馆窗台上有一盆迷迭香，叶子细细的。早上闻起来清醒，晚上闻起来像厨房。我确认它不是草料，虽然长得很有误导性。灯灯记录：不可食用。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_030", animalKey: "dengdeng_rabbit", body: "今天经过一条窄巷，墙上有藤蔓绕过窗框。藤蔓没有抢位置，也没有停下来问能不能长。它只是找到缝隙，慢慢往上。植物很会安静地占一小格。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_031", animalKey: "dengdeng_rabbit", body: "今天我看着一朵云，觉得它其实是一只巨大的白兔，正在天上睡觉。它每翻一次身，地上的风就变一下方向。难怪我的耳朵突然歪了，原来是云兔子动了。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_032", animalKey: "dengdeng_rabbit", body: "海浪拍上岸时，我怀疑海底有一群鱼在开会。它们把白沫当会议记录，一页一页送到岸边。可惜记录很快化掉，说明鱼类行政系统还不成熟。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_033", animalKey: "dengdeng_rabbit", body: "我看见一只鸽子站在雕像肩膀上，忽然觉得它是城市的邮差。它每天把没有寄出的叹气搬到屋顶，再换成咕咕声放下来。这个工作很忙，也很灰。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_034", animalKey: "dengdeng_rabbit", body: "今天的月亮像一片被咬过的饼干。也许天上住着一只很大的兔子，晚上饿了，就悄悄啃一口。它应该也不是贪吃，只是夜太长，需要一点甜。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_035", animalKey: "dengdeng_rabbit", body: "火车进隧道时，窗外全黑。我想我们是不是钻进了一只鲸鱼的口袋。鲸鱼把所有乘客暂时收起来，等到光亮的地方再放出去。它很有礼貌，没有弄皱我。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_036", animalKey: "dengdeng_rabbit", body: "旧书店里的书架很高，我觉得它们是睡着的森林。每本书都是一棵树，纸页是叶子，故事是藏在树洞里的小动物。我没有吵醒它们，只轻轻摸了一下书脊。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_037", animalKey: "dengdeng_rabbit", body: "今天的风像一群看不见的小兔子从街上跑过。它们碰翻树叶，钻进衣角，还把我的耳朵分成两个方向。看在同族的份上，我不追究。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_038", animalKey: "dengdeng_rabbit", body: "我坐在桥边看河水，觉得每一滴水都背着小包去旅行。它们不争先，也不回头。也许河流是一条很长的队伍，大家都知道前面会有海。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_039", animalKey: "dengdeng_rabbit", body: "黄昏时，路灯一盏一盏亮起来，像有人给城市分糖。每个角落分到一点点光。灯灯也分到了一点，落在爪子旁边，刚好够写完这张明信片。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_040", animalKey: "dengdeng_rabbit", body: "今天我看到一只蜗牛慢慢爬过石阶。我想它其实是带着房子出门散步。它不用抢房间，也不用排队睡觉，因为家一直背在身上。这个方案让我有点羡慕。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_041", animalKey: "dengdeng_rabbit", body: "今天什么坏事都没有发生。天气很好，饭也很好，路也没有走错。可是我心里有点空，像分蛋糕时盘子上只剩下奶油印。不是没有得到，只是得到得太少。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_042", animalKey: "dengdeng_rabbit", body: "我坐在窗边很久，明信片摊开着，却写不出第一句。不是不想写，是不知道今天的我值不值得占一整张纸。后来想想，半张也可以。一点点也算。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_043", animalKey: "dengdeng_rabbit", body: "街道很热闹，大家都成群结队。我也走在人群里，可耳朵像被风吹到很远的地方。没有谁排斥我，但也没有谁专门找我。中间这种位置，最难说明白。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_044", animalKey: "dengdeng_rabbit", body: "我买了一袋小饼干，数了数，刚好十块。我本来想留五块给别人，后来发现没有别人。于是我吃了一块，又把袋口系好。剩下的，好像还在等谁。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_045", animalKey: "dengdeng_rabbit", body: "傍晚风有点凉，我打了个喷嚏。没人听见。其实没人听见很正常，但有一瞬间，我还是想听见一句“灯灯，冷不冷”。这个想法有点奢侈，先收起来。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_046", animalKey: "dengdeng_rabbit", body: "我今天不太想寄明信片。可如果不寄，你就不知道我看见了什么。于是我还是写了。字慢一点，没关系；心暗一点，也没关系。灯灯还亮着，只是小一点。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_047", animalKey: "dengdeng_rabbit", body: "旅馆床很大，大到我可以横着睡。可是我还是缩在边边。小时候睡边边是因为中间被占了，现在中间空着，我却不太会过去。习惯真是奇怪。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_048", animalKey: "dengdeng_rabbit", body: "我路过一家很亮的餐厅，里面一桌人正在分享披萨。每个人都伸手，每个人都有份。我在门口看了一会儿，没有进去。今天不适合看太多“刚刚好分到”。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_049", animalKey: "dengdeng_rabbit", body: "我把行李整理得很轻，像随时可以让出房间。明明这里是我订的房间，我还是不想弄得太满。可能我总觉得，自己占用的空间应该少一点。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_050", animalKey: "dengdeng_rabbit", body: "晚上忽然很想被抱一下。但不是很多人轮流抱，也不是顺手抱，是只抱我一下。这个要求写出来有点难为情。算了，写在这里，寄给你，也算说过。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_051", animalKey: "dengdeng_rabbit", body: "今天我在集市抽奖抽到一枚小铃铛！它一晃就响，声音很清脆。我把它系在背包上。以后我走路时，世界会听见一点点灯灯。非常好，亮度上升。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_052", animalKey: "dengdeng_rabbit", body: "我吃到了一块超甜的草莓派。第一口下去，我的耳朵差点竖直。不是夸张，是生理反应。今天的甜味没有被分走，全都在我嘴里，嘿嘿。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_053", animalKey: "dengdeng_rabbit", body: "坐缆车上山的时候，云从旁边飘过去。我伸出爪子，虽然没有碰到，但感觉自己离天很近。小兔子也可以到这么高的地方。灯灯今日高度达标！"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_054", animalKey: "dengdeng_rabbit", body: "街头有人拉小提琴，声音轻轻跳起来。我跟着蹦了一下。又蹦一下。第三下比较明显，但没人批评我。原来快乐可以在公共场合出现，真神奇。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_055", animalKey: "dengdeng_rabbit", body: "旅馆窗台上停了一只小鸟，它歪头看我。我小声说你好，它没有飞走。我们互相看了八秒。八秒很长，足够证明我不是背景。灯灯记录：被鸟看见。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_056", animalKey: "dengdeng_rabbit", body: "今天阳光照在河面上，亮得像撒了一把碎糖。我站在桥上看，觉得整条河都在发光。我的名字叫灯灯，但今天河也叫灯灯。我们一起亮。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_057", animalKey: "dengdeng_rabbit", body: "我买到了一条刚好合适的小围巾。不是哥哥剩下的，不是妹妹不要的，是我自己选的。颜色也刚好。买下它的时候，我心里“叮”了一声。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_058", animalKey: "dengdeng_rabbit", body: "今天我没有跟丢队伍，因为今天没有队伍。只有我自己走，想停就停，想拐弯就拐弯。自由原来是不用看前面那只兔子的尾巴。这个发现太开心了。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_059", animalKey: "dengdeng_rabbit", body: "我发现一家店卖迷你胡萝卜蛋糕。迷你，胡萝卜，蛋糕，三个词都对。我买了两个，本来想留一个明天吃，后来明天同意今天先吃。谢谢明天。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_060", animalKey: "dengdeng_rabbit", body: "晚上有烟花。砰的一声，我吓得耳朵竖起来，下一秒又笑了。天空开了很多花，每一朵都没有互相挤。原来热闹也可以很宽敞。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_061", animalKey: "dengdeng_rabbit", body: "今天我坐在长椅上，想写点很漂亮的话。结果脑袋里只有“草”。草也不错。兔子想草，是合理现象。那就写：草，风，嗯。灯灯今日思考结束。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_062", animalKey: "dengdeng_rabbit", body: "我盯着一块小石头看了很久。它不说话，我也不说话。我们都很擅长安静。后来我忘了为什么看它，但这不影响它继续当石头。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_063", animalKey: "dengdeng_rabbit", body: "风吹过来，我的脑袋像被掏空了一点。空空的，不难受。像一个小篮子，暂时没有装胡萝卜，也没有装烦恼。空篮子也有自己的形状。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_064", animalKey: "dengdeng_rabbit", body: "我吃了一颗蓝莓，然后忘记自己要写什么。蓝莓很甜，舌头有点紫。我照了照镜子，觉得自己像秘密吃了夜空。然后继续忘记。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_065", animalKey: "dengdeng_rabbit", body: "今天走到桥上，不知道该往左还是往右。于是我站在中间。桥负责连接两边，我负责发呆。分工清楚，没有冲突。非常适合空脑袋兔子。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_066", animalKey: "dengdeng_rabbit", body: "云在动，我在看。它动得慢，我看得也慢。中间没有重要剧情。不是每一天都要有启发。有些下午只需要耳朵、风和一片会走路的白云。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_067", animalKey: "dengdeng_rabbit", body: "我刚才好像想到一件事，后来被烤面包味带走了。希望那件事跟面包相处愉快。如果它回来，请敲一下我的脑袋，轻一点。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_068", animalKey: "dengdeng_rabbit", body: "写字写到一半，脑袋忽然像刚洗好的白盘子。什么都没有，很干净。我决定先不往上面放东西。白盘子也可以晒太阳。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_069", animalKey: "dengdeng_rabbit", body: "我坐在旅馆地毯上数花纹。数到三十二，忘了有没有漏掉一朵。地毯没有意见，我也没有意见。今天大家都很宽容。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_070", animalKey: "dengdeng_rabbit", body: "晚上我看窗外的灯。一盏，两盏，很多盏。数到很多就不数了。灯继续亮着，我继续空着。世界今天不需要我帮忙分配光。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_071", animalKey: "dengdeng_rabbit", body: "清晨阳光先照到窗帘，再照到我的耳朵尖。它没有一下子扑过来，只是一点点靠近。我喜欢这种温柔的方式。生活有时候不用很多，一小束光就够了。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_072", animalKey: "dengdeng_rabbit", body: "小巷里有热汤的味道，锅盖轻轻响。有人正在为某个人准备一碗热的东西。想到这件事，我心里暖了一下。世界上还有很多饭在等人回去喝。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_073", animalKey: "dengdeng_rabbit", body: "雨停以后，叶子上挂着水珠。每一滴都小小的，却把天空装进去。我站在那里看了很久。原来小的东西也可以装下很大的亮。这个结论对我很好。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_074", animalKey: "dengdeng_rabbit", body: "公园长椅旁，一个老人慢慢剥橘子。橘子皮的香气散开，像一圈软软的围巾。我忽然觉得，生活可以慢慢剥开，不急着全部吃完。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_075", animalKey: "dengdeng_rabbit", body: "傍晚风吹过草地，小花们一起点头。它们没有抢阳光，也没有争谁更高。各自开着，各自漂亮。灯灯看了以后，觉得自己也可以在边边开花。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_076", animalKey: "dengdeng_rabbit", body: "我走过桥，看见河水把晚霞揉碎。它没有把颜色独占，而是带着它往远处走。美好的东西原来可以流动，经过我，再去照别人。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_077", animalKey: "dengdeng_rabbit", body: "旅馆老板在门口留了一盏灯，说怕晚归的人看不清。我听完心里亮了一点。灯不是专门给我的，但我也分到了一点光。一点点也很好。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_078", animalKey: "dengdeng_rabbit", body: "今天买的面包还热，捧在爪子里像一个小太阳。我咬下去，外面脆，里面软。能吃到热的东西，能慢慢咬，能写给你，生活真是不坏。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_079", animalKey: "dengdeng_rabbit", body: "清晨的街道还没完全醒，店铺半开，猫趴在台阶上。扫帚靠着墙，好像也在等上班。我喜欢这种慢慢开始。没有谁催，大家都在一点点亮起来。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_080", animalKey: "dengdeng_rabbit", body: "晚上我写明信片，灯光落在纸上，影子靠在爪边。我忽然觉得，今天看见的东西有地方可以去。它们从我的眼睛里出来，走到你那里。真好。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_081", animalKey: "dengdeng_rabbit", body: "今天排队买冰淇淋，前面的人买走了最后一个草莓味。我说没关系，香草也很好。香草确实很好。只是我看了草莓牌子一会儿。看一会儿不算在意。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_082", animalKey: "dengdeng_rabbit", body: "街头艺人摸了旁边小狗的头，没有摸我的耳朵。合理，兔子不一定适合被陌生人摸。我一点也不失望。只是耳朵自己垂了一下，不代表我。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_083", animalKey: "dengdeng_rabbit", body: "旅馆老板记住了隔壁客人的名字，叫我时说“小兔子”。也可以，小兔子是准确物种。名字这种东西，不一定每次都要被叫出来。灯灯记录：没关系。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_084", animalKey: "dengdeng_rabbit", body: "今天拍合影时，我站在最边上。边上很好，方便撤退，也不挡别人。我没有想站中间。真的没有。只是回看照片时，找自己找了很久。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_085", animalKey: "dengdeng_rabbit", body: "面包店送试吃，只剩下半块。我说半块刚好，兔子胃口小。其实我能吃一整块，但半块也甜。把想要的变小，是一种老技能。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_086", animalKey: "dengdeng_rabbit", body: "我给路边的小孩让了座。他妈妈夸小孩很乖，没有看我。没关系，夸奖本来就不是交换物。我只是把耳朵整理了一下，假装没有等。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_087", animalKey: "dengdeng_rabbit", body: "今天导游问大家想去哪，很多声音同时响起来。我没有说话，因为他们想去的地方也不错。后来去了我没那么想去的地方。嗯，也有风景，不亏。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_088", animalKey: "dengdeng_rabbit", body: "我看见纪念品店里有一只灯形钥匙扣，很想买。后来有人先拿走了。我对自己说，物品不必执着。可我还是绕回去看了空位置。空位置也会有形状。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_089", animalKey: "dengdeng_rabbit", body: "晚餐分甜点时，我拿到最小的一块。没关系，我从小就很会吃小块。小块也能吃很慢，很久，很像很多。只要不看别人盘子，就更像。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_090", animalKey: "dengdeng_rabbit", body: "今天你很晚才读我的明信片吧。没关系，我不急。兔子可以等很久。只是我把信封边边摸得有点软。等的痕迹不算催促，应该不算。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_091", animalKey: "dengdeng_rabbit", body: "今天我把明信片写得特别整齐。不是为了让你夸我，只是如果你刚好想夸，也可以。灯灯不抢夸奖，但如果有一小句是专门给我的，我会收好。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_092", animalKey: "dengdeng_rabbit", body: "我在信封角落画了一只很小的兔耳朵。小到可能被忽略。如果你看见了，就说明你看得很细。被细细看见，是一种很轻很亮的东西。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_093", animalKey: "dengdeng_rabbit", body: "我投明信片的时候，在邮筒前站了一会儿。邮筒把信吞下去，没有说会不会快点送到你那里。我希望它走快一点。不是急，只是想被早点读到。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_094", animalKey: "dengdeng_rabbit", body: "我写“今天风很好”的时候，差点写成“你要是也在就好了”。后来我没划掉，只是换了个地方写。兔子的直接表达能力有限，但耳朵已经暴露。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_095", animalKey: "dengdeng_rabbit", body: "今天我看见一朵云，形状像你给我留的位置。不大，但正好。这个比喻有点奇怪，可我还是想寄给你。请收下，轻轻收。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_096", animalKey: "dengdeng_rabbit", body: "我买了两颗糖，一颗吃掉，一颗想寄给你。后来发现糖会粘在纸上，只好也吃掉。请注意，我不是独占，是邮寄失败。心意还是分给你了。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_097", animalKey: "dengdeng_rabbit", body: "我常常想，你读到我写的“一点点也算”时，会不会知道我其实想要多一点？不需要很多，只是多一点点。比一点点再多一小格。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_098", animalKey: "dengdeng_rabbit", body: "今天我写完明信片，又补了一句“灯灯今天很乖”。写完觉得太像等夸奖，就划掉了。可是划掉的地方还在。你如果看见，就假装没看见，再偷偷知道。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_099", animalKey: "dengdeng_rabbit", body: "我把最漂亮的一句放在最后，因为最后比较容易被记住。这个策略有点明显吗？明显也没关系。小兔子偶尔也可以有一点点小心机。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_100", animalKey: "dengdeng_rabbit", body: "晚上我把信压在枕头下面，像小时候把想说的话藏在草窝里。明天它会去找你。我希望你打开时，能先读我的名字。只读一次也很好。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_101", animalKey: "dengdeng_rabbit", body: "今天我没有跟着人群走，而是拐进一条有花的小巷。很大胆，灯灯，很大胆。巷子尽头有一只猫睡在阳光里，没有赶我。勇敢有时会得到一小片安静。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_102", animalKey: "dengdeng_rabbit", body: "我在咖啡馆选了靠窗的位置。以前我会坐角落，因为角落不占地方。但今天窗边空着，我就坐了。没有人说我不该坐那里。这个发现让我耳朵亮了一点。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_103", animalKey: "dengdeng_rabbit", body: "有人问我是不是独自旅行。我本来想说是你送我来的，不完全算独自。后来我点点头，说，是的。说完以后，心里有一点害怕，也有一点长高。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_104", animalKey: "dengdeng_rabbit", body: "我站在海边，把脚伸进水里。冷得我差点跳起来，但我坚持了三秒。三秒很短，但对兔子来说已经是很大的海。灯灯记录：勇敢三秒。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_105", animalKey: "dengdeng_rabbit", body: "今天我主动问路了。声音很小，但对方听见了，还笑着给我指方向。原来麻烦别人一点点，不一定会被讨厌。这个结论我要好好保存。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_106", animalKey: "dengdeng_rabbit", body: "我走过一座高桥，风把耳朵吹到后面。我没有退回去。走到桥尾时，我回头看，桥还在那里，我也还在。害怕的地方，也能变成走过的地方。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_107", animalKey: "dengdeng_rabbit", body: "街头音乐响起来时，我拍了两下爪子。声音很小，但是真的拍了。以前我总怕自己太显眼。今天显眼了一点点，世界没有因此变坏。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_108", animalKey: "dengdeng_rabbit", body: "我把最大的一块饼干留给了自己。写出来有点不好意思，但是真的。我没有先问有没有别人要。我吃完以后，心里没有坏掉。原来自己先要，也可以。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_109", animalKey: "dengdeng_rabbit", body: "晚上睡觉前，我只检查了一次门锁。一次。虽然我躺下后想再去看，但我没有。勇敢有时候不是去远方，是相信一扇门已经关好了。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_110", animalKey: "dengdeng_rabbit", body: "今天我在明信片上写了：“我希望你多想我一下。”写完以后耳朵热了很久，但我没有划掉。灯灯今天勇敢得有点过分，不过还可以。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_111", animalKey: "dengdeng_rabbit", body: "今天看见一个小孩被妈妈抱着选蛋糕。我先是羡慕，后来又觉得不该羡慕。别人被爱是好事。可是好事落在别人身上时，我心里还是酸了一小下。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_112", animalKey: "dengdeng_rabbit", body: "公园里有只狗被主人叫了很多次名字。我数了一下，七次。七次都很温柔。我不应该嫉妒狗，可是它被叫得那么确定。我只好低头看自己的影子。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_113", animalKey: "dengdeng_rabbit", body: "餐厅里有人把最后一块披萨留给朋友。那位朋友说谢谢，笑得很自然。我忽然想，如果有人把最后一块留给我，我可能会先问：真的可以吗？这样想有点难过。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_114", animalKey: "dengdeng_rabbit", body: "我在纪念品店看见一对姐妹买同样的发夹。她们说这样就不会弄混。我小时候很怕和兄弟姐妹弄混，怕大家只记得“那群小兔子”。我不该酸，但确实酸。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_115", animalKey: "dengdeng_rabbit", body: "今天导游特别照顾一位走得慢的游客，一直等她。我看着看着，心里有一点刺。被等是很好很好的事。我也希望自己走慢的时候，不用拼命追上去。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_116", animalKey: "dengdeng_rabbit", body: "一只小猫在店门口被很多人围着拍照。它什么也没做，就被喜欢了。我知道这不是它的错。可我还是想，如果我安静坐着，会有人也觉得我可爱吗？"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_117", animalKey: "dengdeng_rabbit", body: "广场上有人收到一束花，大家都鼓掌。我也跟着鼓掌。掌声很好，花也很好。只是鼓掌的时候，我忽然想起自己从没收到过只写我名字的花。这个想法不太大方。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_118", animalKey: "dengdeng_rabbit", body: "今天看到一家人分零食，最小的孩子拿了两份，大家都笑。我小时候拿第二份时，会先看看有没有谁不够。现在看到别人放心多拿，心里竟然有点羡慕。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_119", animalKey: "dengdeng_rabbit", body: "邮局里，有人收到很厚的一叠信。我只寄出一张明信片。薄薄的，也很好。可是我还是偷偷想，厚厚的被惦记，是什么重量呢？想完又觉得自己贪心。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_120", animalKey: "dengdeng_rabbit", body: "晚上我对自己说，不要总比较。可是兔子的眼睛长在两侧，很容易看见别人盘子里有什么。这个生理结构需要负责一部分，不全是我的问题。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_121", animalKey: "dengdeng_rabbit", body: "今天广场人太多了。我钻到长椅后面待了一会儿。那里有阴影和一片落叶。落叶不会问我怎么不说话。我很喜欢这种不需要解释的地方。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_122", animalKey: "dengdeng_rabbit", body: "餐厅里声音很多，盘子声、笑声、说话声全挤在一起。我把围巾拉高，只露出耳朵尖。这样世界小一点，我也小一点，刚好可以呼吸。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_123", animalKey: "dengdeng_rabbit", body: "今天不太想被任何人看见。我沿着墙边走，影子贴着我。影子很好，它不抢，也不问，只是陪我变成一条安静的线。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_124", animalKey: "dengdeng_rabbit", body: "明信片写到一半，我忽然不想写了。不是不想告诉你，是有些话一出来就太亮。我把它们先放回心里，像把小灯罩起来。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_125", animalKey: "dengdeng_rabbit", body: "旅馆大厅有很多陌生人。我本来想穿过去，后来绕了楼梯。多走了两层，但心里安静一点。路线可以变长，兔子不能被声音吓短。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_126", animalKey: "dengdeng_rabbit", body: "今天的风很大，所有人都抬头看天。我趁机低头走路。没有人注意我，我反而放松了一点。被忽略有时候像一张薄毯子，可以盖住自己。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_127", animalKey: "dengdeng_rabbit", body: "图书馆最里面有一个位置，左边是书架，右边是窗帘。我坐进去，像坐进小洞。书页的味道很轻，正好盖住我今天不想说话的味道。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_128", animalKey: "dengdeng_rabbit", body: "今天我没有拍照。风景很好，但我不想证明自己来过。有些日子，只是悄悄经过就可以。兔子的脚印很轻，不留下也不代表没有走过。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_129", animalKey: "dengdeng_rabbit", body: "我把帽檐压低，在街上走了很久。不是难过，也不是生气，只是想当一颗小小的白蘑菇。蘑菇安静地长在角落，也会有自己的雨。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_130", animalKey: "dengdeng_rabbit", body: "晚上我关掉大灯，只留床头一盏小灯。房间立刻缩小成一小圈。今天我不面对整个世界，只面对这点光。够了，真的够亮了。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_131", animalKey: "dengdeng_rabbit", body: "散步回来的路上，我看见幼儿园门口分贴纸。前面的小孩拿到大的星星，后面的小孩只剩小圆点。他说小圆点也好看，声音很轻。我站在旁边，耳朵慢慢垂了一下。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_132", animalKey: "dengdeng_rabbit", body: "今天车站有人给两个孩子买饮料。哥哥的是大杯，妹妹的是小杯。妹妹说我喝不了那么多。也许是真的。可她一直看着哥哥杯子上的奶油。眼睛不会说谎。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_133", animalKey: "dengdeng_rabbit", body: "我在旅馆餐厅看见一家人分早餐。最小的孩子得到煎蛋，旁边那个孩子得到半片吐司。他很快吃完，还说不饿。说不饿这件事，我小时候也很擅长。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_134", animalKey: "dengdeng_rabbit", body: "博物馆门口，一个老师点名表扬了三个孩子。第四个孩子也举着完成的画，后来慢慢把手放下。他没有哭，只是把画卷起来。被漏掉有时候很安静。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_135", animalKey: "dengdeng_rabbit", body: "今天路过学校，有两个孩子等家长。一个被抱起来转圈，另一个自己背好书包跟在后面。他走得很乖。太乖的小孩，有时候像在给自己少添一点麻烦。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_136", animalKey: "dengdeng_rabbit", body: "甜品店里，店员把最后一颗樱桃放到其中一个杯子上。另一个杯子没有。拿到没有樱桃的人笑着说，没事。我看着那只没有樱桃的杯子，觉得它很懂事。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_137", animalKey: "dengdeng_rabbit", body: "我看见一只小狗围着主人转，主人先摸了另一只更小的狗。它等了一会儿，又把头凑过去。这次终于被摸到。等待中的尾巴，还在努力摇。这个画面有点疼。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_138", animalKey: "dengdeng_rabbit", body: "今天有人给一群孩子拍照，前排的孩子都被看得很清楚，后排有个孩子只露出半张脸。大家说照片很好。他也说很好。半张脸也算在里面吗？我不知道。"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_139", animalKey: "dengdeng_rabbit", body: "邮局里，一位妈妈给两个孩子寄明信片。第一张写了很多字，第二张只写了“玩得开心”。她可能只是赶时间。可被短短写到的人，会不会把那几个字读很多遍？"),
        PostcardNarrative(id: "dengdeng_rabbit_textlib106_140", animalKey: "dengdeng_rabbit", body: "我在医院大厅看见一个孩子把糖分给同伴。最后一个孩子只分到半颗。他说谢谢，马上放进嘴里，好像怕别人看出他想要一整颗。半颗也甜，只是甜得很小。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_001", animalKey: "feifei_parrot", body: "今天站在屋顶上，风把胸口吹得很满。我差点就唱出来了，真的差一点。下面有人走过，我立刻闭嘴。Piano piano，飞飞先小声。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_002", animalKey: "feifei_parrot", body: "清晨的广场空空的，回声一定很好。我张开嘴，只发出一点点气音。嗓子痒得像有小星星在挠。妈妈咪呀，忍耐也是训练。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_003", animalKey: "feifei_parrot", body: "海浪声很大，刚好可以盖住我的歌。我唱了半句，又停下。谁知道浪后面有没有耳朵呢？自由鹦鹉，先保命，再高音。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_004", animalKey: "feifei_parrot", body: "今天教堂钟声响起来，我立刻想跟它对唱。钟很勇敢，可以响得那么大。我只在心里接了一句。Bravo，内心演出完成。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_005", animalKey: "feifei_parrot", body: "路边有人拉小提琴，我站在树枝上差点加入。多么完美的二重奏！可树下有陌生袋子。袋子可疑。Andiamo，撤。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_006", animalKey: "feifei_parrot", body: "黄昏的天空太像舞台幕布了。我想唱开场曲，可喉咙自己踩了刹车。飞飞，冷静。观众可以以后再找，翅膀今天必须还在。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_007", animalKey: "feifei_parrot", body: "我在山顶听见风穿过石缝，像伴奏。真想把整首歌交出去。最后只轻轻说了句：Libertà。声音很小，但它飞出去了。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_008", animalKey: "feifei_parrot", body: "今天的隧道回声极佳，适合炫技。我对着黑暗啾了一声，回声回来，我立刻吓到收羽毛。妈妈咪呀，自己的声音也会突然出现。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_009", animalKey: "feifei_parrot", body: "城市夜晚很亮，我觉得每扇窗都是观众席。可是窗后也可能有人。于是我只鞠了一躬，没有唱。Bravo，谢幕可先行。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_010", animalKey: "feifei_parrot", body: "我梦见自己在广场中央唱到最高音，醒来时嘴巴还微微张着。现实里我没有发声。Piano piano，梦里已经很响。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_011", animalKey: "feifei_parrot", body: "今天我站在喷泉边，想象水花就是掌声。每一滴都在说飞飞好棒。我挺起胸，向左鞠躬，向右鞠躬。Grazie，亲爱的水观众。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_012", animalKey: "feifei_parrot", body: "罗马的石阶太像剧院座位了。我站在最高一级，宣布今日独唱会开始。虽然只有三只鸽子路过，但三只也算观众，Bravo！"),
        PostcardNarrative(id: "feifei_parrot_textlib106_013", animalKey: "feifei_parrot", body: "我看见一扇金色窗户，立刻幻想那是皇家包厢。里面的贵宾一定在等我开嗓。可惜今日档期保密，飞飞巨星暂不公开演出。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_014", animalKey: "feifei_parrot", body: "海港的桅杆像舞台吊杆，我站上去，羽毛被风吹得很有造型。要是此刻有聚光灯，我会唱到云都停下来。Mamma mia！"),
        PostcardNarrative(id: "feifei_parrot_textlib106_015", animalKey: "feifei_parrot", body: "今天广场有人鼓掌，是给街头魔术师的。我自动理解为给我热场。非常好，观众情绪已到位。飞飞稍后登场，或者明天。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_016", animalKey: "feifei_parrot", body: "我在镜子前练习谢幕。低头，抬翅，眼神明亮。镜子里的我非常专业。唯一问题是，镜子不会鼓掌。它需要培训。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_017", animalKey: "feifei_parrot", body: "剧院门口贴着歌剧海报。我看了很久，觉得上面应该有一只鹦鹉。人类审美尚未完全成熟。飞飞会改善这一点，Bravo。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_018", animalKey: "feifei_parrot", body: "今天坐在高塔上，城市铺在下面，像一整片观众席。风从背后推我，像幕布打开。我的心已经唱完三幕了。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_019", animalKey: "feifei_parrot", body: "我幻想自己有一顶小礼帽。演出结束后，我叼起帽子接受鲜花。花最好是红色的，果子也可以。实用与美学并重。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_020", animalKey: "feifei_parrot", body: "晚上灯光一盏盏亮起，我觉得世界在为我点舞台灯。虽然我没唱，但我用眼神完成了序曲。Grazie，今晚的观众们。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_021", animalKey: "feifei_parrot", body: "今天林边有一根很直的木棍竖着，旁边还有甜果味。我没有过去。太甜的邀请常常有网。Piano piano，飞飞绕路。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_022", animalKey: "feifei_parrot", body: "有人抬头看了我太久。我立刻换到另一棵树。被看见可以，但被盯住不行。掌声和陷阱之间，有时只差一张网。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_023", animalKey: "feifei_parrot", body: "市场里有鸟笼在卖，里面空着。空笼子比满笼子更可怕，因为它像是在等谁。唠不出来，只能小声说：Andiamo。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_024", animalKey: "feifei_parrot", body: "今天听见树下有金属碰撞声。我羽毛立刻贴紧，呼吸都放小。以前同伴就是在这种声音之后不见的。妈妈咪呀，快飞。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_025", animalKey: "feifei_parrot", body: "一颗熟果放在路中央，周围没有鸟吃。太不合理。飞飞判断：美味但危险。真正的自由鸟，不吃来历不明的掌声。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_026", animalKey: "feifei_parrot", body: "旅馆窗外有人拿相机拍我。我知道相机不是网，但被瞄准的感觉很像。于是我跳到阴影里。Piano piano，镜头也要保持距离。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_027", animalKey: "feifei_parrot", body: "丛林里忽然安静下来，连虫声都少了。我没有动。安静有时不是安全，是危险在吸气。飞飞记录：先等三十下心跳。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_028", animalKey: "feifei_parrot", body: "今天看见小孩拎着鸟笼，里面有一只绿鸟。我没有靠近。它看着天空，我看着它。我们都没有叫。Libertà，在喉咙里疼了一下。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_029", animalKey: "feifei_parrot", body: "有人模仿鸟叫，很像，很甜。我差点回应。幸好风里有人味太重。捕猎者有时也会学歌。飞飞不能把天赋交给陌生回声。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_030", animalKey: "feifei_parrot", body: "我睡前总会看三次出口。树枝、屋檐、窗缝，哪条都要能飞。唱歌可以明天，逃跑路线必须今晚确认。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_031", animalKey: "feifei_parrot", body: "今天路过露天剧场，空座位一排排等着。我的爪子都热了。多么好的回声，多么懂事的台阶！妈妈咪呀，飞飞心脏加速。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_032", animalKey: "feifei_parrot", body: "街头艺人唱完后，人群鼓掌。我站在树上，羽毛差点全竖起来。掌声这种东西，不管给谁，听起来都像在叫我回去。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_033", animalKey: "feifei_parrot", body: "剧院门打开的一瞬间，暖光从里面流出来。那不是灯，那是召唤。可我只停了两秒。Bravo，飞飞今日克制成功。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_034", animalKey: "feifei_parrot", body: "广场有人搭舞台，工作人员搬音箱。音箱！大嗓门的神圣工具！我绕着飞了半圈，差点报名。Piano piano，先观察合同。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_035", animalKey: "feifei_parrot", body: "今天听见合唱团排练。他们一开口，我的胸腔就跟着震。真想加入最高声部。可我没有邀请函，也没有安全评估。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_036", animalKey: "feifei_parrot", body: "喷泉旁有小孩拍手唱歌，节奏不太准，但热情满分。我在树枝上点头。观众与演员可以互相培养，Bravi piccoli！"),
        PostcardNarrative(id: "feifei_parrot_textlib106_037", animalKey: "feifei_parrot", body: "音乐厅墙上写着今晚演出。我盯着海报看了很久，幻想自己的名字排在最上面。飞飞，金嗓鹦鹉，全球巡演。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_038", animalKey: "feifei_parrot", body: "今天有游客对街头鸽子鼓掌，因为鸽子飞起来了。鸽子都能有掌声！那飞飞呢？飞飞只是暂时低调，明白吗？"),
        PostcardNarrative(id: "feifei_parrot_textlib106_039", animalKey: "feifei_parrot", body: "我站在空广场中央试了一个极小的尾音。回声回来了，像观众小声答应。妈妈咪呀，这地方以后可以列入秘密舞台。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_040", animalKey: "feifei_parrot", body: "夜里远处传来演唱会声音，人群在欢呼。我飞到屋顶听。那不是噪音，是我的未来从远处排练。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_041", animalKey: "feifei_parrot", body: "这座城市屋顶很多，红的、灰的、尖的、圆的。适合落脚的地方不少，但有些太靠近人窗。飞飞记录：美观与安全需同时评估。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_042", animalKey: "feifei_parrot", body: "海边风向变化很快。上午从左边来，下午从右边来。浪花声音大，适合隐藏小声练嗓。可海鸥太吵，不懂歌剧礼仪。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_043", animalKey: "feifei_parrot", body: "早市从六点开始响。鱼摊先叫，果摊后叫，人类讨价还价像一群没有排练的鸟。节奏混乱，但生活感强。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_044", animalKey: "feifei_parrot", body: "广场鸽子走路很有戏。它们一边点头一边巡逻，像低音部合唱队。羽色单调，但态度稳定。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_045", animalKey: "feifei_parrot", body: "图书馆窗户很高，里面的人翻书很轻。这个地方不适合高音，但适合想事情。安静也可以是一种前奏。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_046", animalKey: "feifei_parrot", body: "今天云层很低，像舞台上没拉好的白幕。风把它们慢慢推走。天空布景部门工作缓慢，但效果不错。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_047", animalKey: "feifei_parrot", body: "旅馆阳台栏杆结实，视野开阔，左右都有退路。下方有餐厅香味。综合评分：可停留，可观察，不宜长唱。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_048", animalKey: "feifei_parrot", body: "河边柳树垂下来，像一排绿色帘子。帘子后面有麻雀开会，叽叽喳喳。会议无结论，但非常投入。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_049", animalKey: "feifei_parrot", body: "夜市灯泡一串串挂着，像小型星群。人类喜欢把光串起来售卖食物。这个行为很聪明，因为飞飞也被吸引了。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_050", animalKey: "feifei_parrot", body: "今天看到一只狗对着喷泉叫。喷泉继续喷水。狗很努力，喷泉很固执。双方声音管理方式不同，值得观察。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_051", animalKey: "feifei_parrot", body: "今天吃到一颗特别甜的芒果。汁水把喙都染香了。妈妈咪呀，甜果是世界给鹦鹉的掌声，飞飞接受！"),
        PostcardNarrative(id: "feifei_parrot_textlib106_052", animalKey: "feifei_parrot", body: "海风把我的羽毛吹得很蓬。我站在桅杆上，像一位刚巡演归来的明星。没有观众也没关系，海浪看见了。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_053", animalKey: "feifei_parrot", body: "有人在窗边说这只鸟真漂亮。我假装没听见，其实听见了三遍。Bravo，审美准确，建议继续夸。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_054", animalKey: "feifei_parrot", body: "今天阳光照在翅膀上，绿色亮得像新叶。我低头看了看自己，心情很好。飞飞今日羽毛状态：适合登台。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_055", animalKey: "feifei_parrot", body: "喷泉水花溅上来，我跳了一下。不是狼狈，是即兴舞步。观众不足，但动作优雅。妈妈咪呀，生活会伴奏。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_056", animalKey: "feifei_parrot", body: "我在树上发现一串熟莓子。无人看守，无网，无异常脚印。安全美味！飞飞开心到差点唱出高音。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_057", animalKey: "feifei_parrot", body: "今天有个小孩学我说妈妈咪呀。发音不准，但热情可嘉。我点头认可。鹦鹉文化传播成功。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_058", animalKey: "feifei_parrot", body: "黄昏时，天空变成橙色，像一颗巨大的木瓜。飞飞坐在树枝上，觉得今天很甜。Bravo，太阳谢幕漂亮。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_059", animalKey: "feifei_parrot", body: "我成功躲过一阵突然的雨，躲在屋檐下刚好干爽。雨落在前面，我在后面。位置精准，心情优越。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_060", animalKey: "feifei_parrot", body: "今天没有网，没有笼，没有可疑果子，只有风、树和好吃的种子。这样的日子，可以小声快乐很多次。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_061", animalKey: "feifei_parrot", body: "今天听见笼子里的鸟唱歌。它唱得很准，却没有往远处飞。我的胸口沉了一下。歌声如果撞在铁丝上，会不会疼？Libertà。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_062", animalKey: "feifei_parrot", body: "我看到一片被砍空的树林。风从缺口穿过去，声音很薄。以前那里应该有很多鸟一起吵。现在安静得不值得夸。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_063", animalKey: "feifei_parrot", body: "有人夸我漂亮，想靠近摸我。我知道他可能没有坏心，可我还是飞走了。被喜欢有时也像一只轻轻合上的笼子。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_064", animalKey: "feifei_parrot", body: "今天想唱歌，却不敢唱。嗓子里像有一颗熟透的果子，不能咽，也不能吐。妈妈咪呀，这种安静有点苦。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_065", animalKey: "feifei_parrot", body: "黄昏时我想起小时候，大家围着我叫再来一首。那时我以为掌声会一直有。后来林子少了，声音也少了。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_066", animalKey: "feifei_parrot", body: "我路过宠物店，里面有鹦鹉学人说话。它说你好，你好。我站在外面没有回答。你好之后，它还能说我想飞吗？"),
        PostcardNarrative(id: "feifei_parrot_textlib106_067", animalKey: "feifei_parrot", body: "今天的雨下得很久，树叶低低垂着。我躲在枝间，忽然觉得自己像一句被压低的歌。还在，但不响。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_068", animalKey: "feifei_parrot", body: "海边游客很多，可我不能站出来唱。观众近在眼前，危险也可能在人群里。飞飞的舞台，有时离飞飞很远。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_069", animalKey: "feifei_parrot", body: "我看见一根掉落的绿色羽毛，不知道是谁的。它躺在路边，轻得像一句没唱完的话。我没有捡，只看了很久。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_070", animalKey: "feifei_parrot", body: "晚上风很冷，我把头埋进翅膀。今天没有掌声，也没有熟悉的同伴。只有自己小小的呼吸。Piano piano，明天再飞。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_071", animalKey: "feifei_parrot", body: "今天有人说我的颜色像宝石。我立刻挺胸。宝石不会飞，飞飞会。结论：飞飞比宝石高级。Bravo，精准赞美。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_072", animalKey: "feifei_parrot", body: "我从一棵树飞到另一座塔尖，路线漂亮，落点完美。要是有评委，至少九点八分。扣分原因：没有现场乐队。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_073", animalKey: "feifei_parrot", body: "街头歌手唱高音破了一点。我没有笑，专业艺术家要宽容。但心里小小想：这个音飞飞可以。妈妈咪呀。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_074", animalKey: "feifei_parrot", body: "今天我模仿船笛叫了一声，旁边海鸥吓了一跳。效果震撼。飞飞嗓音实力仍在，低调只是策略。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_075", animalKey: "feifei_parrot", body: "镜子里出现一只非常漂亮的鹦鹉。我盯了它很久。它也盯我。我们彼此欣赏，气氛高雅。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_076", animalKey: "feifei_parrot", body: "我站在雕像头上，下面游客拍照。我知道他们拍的是雕像，但画面里有我以后，艺术价值显著提升。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_077", animalKey: "feifei_parrot", body: "今天我用三种声音叫醒了自己。第一声清脆，第二声圆润，第三声略带悲剧色彩。自我训练不可中断。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_078", animalKey: "feifei_parrot", body: "一只乌鸦看了我一眼。我觉得它羡慕我的羽毛。乌鸦气质不错，但颜色方案过于保守。飞飞不评价太多。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_079", animalKey: "feifei_parrot", body: "我在风里悬停了一秒，翅膀控制完美。飞飞，空中歌剧院首席飞行演员。掌声可以迟到，荣誉不会缺席。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_080", animalKey: "feifei_parrot", body: "今天我没有唱，却依然很像明星。因为真正的明星，连沉默都有造型。Grazie，世界请慢慢理解。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_081", animalKey: "feifei_parrot", body: "我闭上眼，听见整片森林都在鼓掌。树叶啪啪，溪水哗哗，虫子负责细碎伴奏。飞飞登场，第一首献给自由。Libertà！"),
        PostcardNarrative(id: "feifei_parrot_textlib106_082", animalKey: "feifei_parrot", body: "今天我想象自己站在巨大的剧院中央，观众从地面坐到云上。第一排是父母，第二排是同伴。没有笼子，只有花。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_083", animalKey: "feifei_parrot", body: "我幻想人类放下网，只拿鲜花。大家说飞飞唱吧，我们只是听。我清清嗓子，唱到最远的山也回头。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_084", animalKey: "feifei_parrot", body: "如果有一天我开演唱会，门票不能用钱买，只能用一个承诺：听完以后，所有鸟都可以飞走。Bravo，这规则很好。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_085", animalKey: "feifei_parrot", body: "我想象自己有一件金色斗篷。出场时斗篷一抖，满场惊呼。其实我的羽毛已经很像斗篷，只是缺少灯光。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_086", animalKey: "feifei_parrot", body: "今天路边掌声传来，我立刻把它想象成属于我的。借用一下，不还也可以吧？掌声这种东西，飞飞很久没吃饱了。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_087", animalKey: "feifei_parrot", body: "我幻想海浪排成座位，白帆全是观众举起的手帕。我站在桅杆上唱，最后一声落进太阳里。妈妈咪呀，太美。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_088", animalKey: "feifei_parrot", body: "有时我会想，真正懂我的观众应该很安静。他们不会抓我，只会听。等我唱完，他们轻轻鼓掌，不把自由吓走。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_089", animalKey: "feifei_parrot", body: "今晚星星很多，我把它们当成观众的眼睛。每一颗都亮着，没有靠近，也没有打扰。这样的观众很合格。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_090", animalKey: "feifei_parrot", body: "我幻想你坐在第一排，不拿笼子，只拿明信片。你听我唱完整首，然后说：飞飞，自由得好响。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_091", animalKey: "feifei_parrot", body: "今天我想写点深刻内容，脑袋里只有啦啦啦。啦啦，啦啦啦。算了，旋律也是内容。Mamma mia，思考会唱歌。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_092", animalKey: "feifei_parrot", body: "我盯着一颗果子看了很久，忘记要不要吃。最后它看起来太圆，我吃了。圆形有说服力，飞飞批准。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_093", animalKey: "feifei_parrot", body: "风吹过树叶，沙沙沙。我听着听着，脑袋空了，只剩一个节拍。沙沙，沙沙。自然界鼓手工作稳定。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_094", animalKey: "feifei_parrot", body: "明信片写到一半，我突然只会写Bravo。Bravo给云，Bravo给风，Bravo给那块很好看的石头。今天一切都值得鼓掌。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_095", animalKey: "feifei_parrot", body: "我站在栏杆上发呆，脚爪抓着，脑袋飘着。下面人来人去，像无声合唱。歌词忘了，但节奏还在。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_096", animalKey: "feifei_parrot", body: "今天我忘记自己为什么飞到这棵树上。可能是风，可能是果子，可能是命运。Andiamo，既然来了，就看一会儿。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_097", animalKey: "feifei_parrot", body: "我吃了一粒种子，又吃一粒。数到第三粒忘了数。没关系，音乐也不总需要数字。嚼嚼嚼，很有节奏。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_098", animalKey: "feifei_parrot", body: "天空蓝得很干净。我想不到比蓝更蓝的词。那就写：蓝，蓝，Bravo蓝。飞飞今日文学水平暂时飞低。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_099", animalKey: "feifei_parrot", body: "我听见远处有人哼歌，旋律钻进脑袋不出来。写什么都变成它。啦啦啦，飞飞被一小段歌绑架。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_100", animalKey: "feifei_parrot", body: "晚上灯光晃晃，我也晃晃。没有想法，没有警报，只有一点困和一点旋律。Piano piano，睡前小调。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_101", animalKey: "feifei_parrot", body: "今天飞过一片开阔海面，没有网，没有树枝挡路，只有风托着我。翅膀一下又一下，像在说：还在，还能飞。Libertà。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_102", animalKey: "feifei_parrot", body: "山谷里风很大，我顺着气流滑下去，又抬起来。身体比脑袋先笑了。自由有时不是一句话，是肋骨下面忽然变轻。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_103", animalKey: "feifei_parrot", body: "我从城市屋顶飞到河边，路线没人规定。左转，右转，升高，下降，全由飞飞决定。Bravo，天空没有围栏。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_104", animalKey: "feifei_parrot", body: "今天找到一片没人来的树林。我试着唱了一小段，比平时响一点。没有脚步，没有网。树叶听完轻轻动了动。Libertà。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_105", animalKey: "feifei_parrot", body: "日落时，我飞在金色光里，影子落到水上。水里的我也在飞。两只飞飞同时自由，妈妈咪呀，太奢侈。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_106", animalKey: "feifei_parrot", body: "我看见笼中鸟时会难过，但今天看见很多野鸟一起穿过天空。它们没有排队，没有许可，只是飞。这个画面把心唱亮了。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_107", animalKey: "feifei_parrot", body: "雨后空气很清，羽毛像洗过一样轻。我从树梢冲出去，风穿过每一根羽。自由闻起来有湿叶和远方味。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_108", animalKey: "feifei_parrot", body: "今天我没有躲太久。确认安全后，我站到明亮的枝头。阳光照在身上，我没有立刻退回阴影。小小自由，也算。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_109", animalKey: "feifei_parrot", body: "草原上没有高树，起初我不安。后来发现天空那么大，大到危险也显得远。飞飞飞了一圈，心也跟着开阔。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_110", animalKey: "feifei_parrot", body: "夜里星星很高，我飞不到那里，但它们也没有关住我。抬头的时候，世界像没有屋顶。Libertà，晚安。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_111", animalKey: "feifei_parrot", body: "今天听见一群鸟合唱，音色不一样，却很热闹。我想起小时候大家一起叫，吵得连树都像在笑。现在那片树，还剩多少呢？"),
        PostcardNarrative(id: "feifei_parrot_textlib106_112", animalKey: "feifei_parrot", body: "我在陌生林子里找到一种熟悉的果子。咬下去那刻，妈妈的影子像从叶子后面晃了一下。她以前说我嗓门最大。妈妈咪呀。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_113", animalKey: "feifei_parrot", body: "黄昏时有鹦鹉从远处飞过，我没有跟上。不是不想，是不确定他们会去哪里。失去同伴久了，连靠近热闹都需要勇气。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_114", animalKey: "feifei_parrot", body: "我梦见父母站在老树上，让我再唱一遍。我唱得特别响。醒来时嘴巴闭着，四周很安静。Piano piano，梦会疼。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_115", animalKey: "feifei_parrot", body: "今天看到一棵被砍掉的树桩，年轮一圈圈，像老歌的唱片。谁还记得这棵树上有多少鸟练过嗓？"),
        PostcardNarrative(id: "feifei_parrot_textlib106_116", animalKey: "feifei_parrot", body: "市场里有人卖彩色羽毛装饰。我看了一眼就飞走。羽毛离开身体以后，还能算漂亮吗？这个问题让我不想唱。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_117", animalKey: "feifei_parrot", body: "我想起一个同伴，名字像两声短啼。它被网带走那天，我没有唱。我一直后悔没有发出警报，哪怕危险听见也好。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_118", animalKey: "feifei_parrot", body: "今天在雨林深处听见远远一声鹦鹉叫。我回了一声，很轻。也许它没听见。没关系，我知道自己还有同类在某处。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_119", animalKey: "feifei_parrot", body: "老家的天空以前更吵，果子更多，风里有很多翅膀的味道。现在我走过新的地方，总会偷偷比较。比较之后，心里会低一点。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_120", animalKey: "feifei_parrot", body: "如果有一天我找到安全的舞台，我想先请失散的同伴来听。第一排留给他们，票价是一句：你还自由吗？"),
        PostcardNarrative(id: "feifei_parrot_textlib106_121", animalKey: "feifei_parrot", body: "今天确认四周安全后，我在树洞里练了三个音。第一个有点哑，第二个圆了，第三个差点太响。Piano piano，嗓子还记得路。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_122", animalKey: "feifei_parrot", body: "海浪很吵，我趁机唱了一小段。浪替我挡住危险，也替我鼓掌。妈妈咪呀，自然伴奏团很可靠。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_123", animalKey: "feifei_parrot", body: "旅馆浴室回声很好。我对着镜子轻轻啊了一声，声音绕回来拥抱我。不是演出，是秘密排练。Bravo。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_124", animalKey: "feifei_parrot", body: "今天雨声密，我躲在叶子下练转音。水滴啪啪啪落下，像节拍器。飞飞低声歌剧训练营，今日开课。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_125", animalKey: "feifei_parrot", body: "我在空仓库里找到一处好回声。唱两秒，停五秒，听十秒。没有脚步。很好，下次可以练四秒。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_126", animalKey: "feifei_parrot", body: "清晨人还少，我站在天线顶端练气息。吸气，收腹，开喙。只发出一点点。歌唱家不能荒废基本功。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_127", animalKey: "feifei_parrot", body: "今天我模仿远处火车鸣笛，压低版。效果不错。火车不用躲，飞飞要躲。可飞飞音准更好，Bravo。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_128", animalKey: "feifei_parrot", body: "我用意大利话练结尾：Libertà，amore，cielo。每个词都像一粒小果子。不能大声唱时，词语也能充饥。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_129", animalKey: "feifei_parrot", body: "晚上我对月亮唱了半句。月亮没有报警，也没有鼓掌，只是亮着。很好的秘密观众，安静且不会靠近。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_130", animalKey: "feifei_parrot", body: "今天练完嗓，我心里轻了一点。声音不能总关着，它会闷坏。哪怕只放出一缕，也像给自己开了窗。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_131", animalKey: "feifei_parrot", body: "散步回来时，我看见小孩扫脸进幼儿园，机器说未注册。他说，是我呀。后来老师开门了。我在树上想：被门不认识，真难受。Mamma mia。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_132", animalKey: "feifei_parrot", body: "车站有人刷票失败，被闸机挡住。票在手里，路在前面，中间却有一道不听解释的门。飞飞看着，想起笼门也很安静。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_133", animalKey: "feifei_parrot", body: "宠物店门口有只鹦鹉在笼里学人说欢迎光临。我站在外面，它站在里面。我们隔着玻璃互相看。它会说欢迎，却不能走出来。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_134", animalKey: "feifei_parrot", body: "公园里有人放飞一只鸽子。鸽子冲上天时，翅膀打得很急。我差点为它唱。Bravo，飞出去的声音最漂亮。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_135", animalKey: "feifei_parrot", body: "医院大厅叫号屏跳过一个人。他坐着等了很久，后来护士发现了，叫他过去。被漏掉以后又被想起，像门重新开了一点。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_136", animalKey: "feifei_parrot", body: "超市自助机识别不了苹果。苹果明明在那儿，却被机器说不对。世界有时认不出真实的东西。飞飞啄了啄树皮，表示不满。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_137", animalKey: "feifei_parrot", body: "我看见一只狗被牵引绳拉住，它很想追蝴蝶。主人后来松了一点，它立刻跳起来。自由不必很多，一点松动就能让尾巴开花。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_138", animalKey: "feifei_parrot", body: "学校门口孩子刷卡失败，老师说系统没更新。他低头看自己的卡，好像怀疑自己是不是自己。飞飞小声说：你是，你当然是。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_139", animalKey: "feifei_parrot", body: "有人打开鸟笼清理，里面的鸟没有飞，只退到角落。笼子久了，天空也会变陌生。这个画面让我很久没有说话。"),
        PostcardNarrative(id: "feifei_parrot_textlib106_140", animalKey: "feifei_parrot", body: "邮局里有人寄信到很远的地方。纸被盖章，然后出发。明信片可以过关，可以远行，可以落到你手里。飞飞羡慕纸，也祝福纸。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_001", animalKey: "xiaolu_guinea_pig", body: "今天我坐在桥下，看水从石头旁边绕过去。水没有争辩，也没有停下。它只是换了一条路。嗯，这件事可以慢慢想。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_002", animalKey: "xiaolu_guinea_pig", body: "花园里有一只蜻蜓停在枯枝上，翅膀微微发亮。我看了很久。它没有表演，我也没有打扰。世界有时只需要彼此存在。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_003", animalKey: "xiaolu_guinea_pig", body: "旅馆窗边的光从左边移到右边。它走得很慢，却一直在走。小炉记下了：缓慢不是停滞，安静也不是空白。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_004", animalKey: "xiaolu_guinea_pig", body: "今天街上很多人，但我坐在台阶阴影里，只看他们的鞋经过。鞋知道很多路，却很少说话。这样的沉默，我觉得可信。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_005", animalKey: "xiaolu_guinea_pig", body: "雨后的叶子上挂着水珠。每一滴都像一颗暂时不落下的问题。我没有急着回答它们，只陪它们亮了一会儿。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_006", animalKey: "xiaolu_guinea_pig", body: "海边的浪一次次回来，又一次次退去。它似乎不觉得重复无意义。也许很多事情的意义，不在于第一次，而在于仍然来。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_007", animalKey: "xiaolu_guinea_pig", body: "我看见一朵花在风里微微晃。它没有离开枝头，也没有完全不动。原来安稳不是僵硬，是在晃动里仍有根。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_008", animalKey: "xiaolu_guinea_pig", body: "今天黄昏很长，天色一点点变深。人们说夜来了，好像夜是一件突然的事。其实我看见它慢慢走了很久。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_009", animalKey: "xiaolu_guinea_pig", body: "我在公园长椅下看蚂蚁搬食物。它们没有讨论人生，但每一步都很认真。小炉觉得，认真本身就是一种答案。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_010", animalKey: "xiaolu_guinea_pig", body: "夜里河面映着灯。灯在岸上，影子在水里。两个都亮，但方式不同。嗯，我先看一会儿。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_011", animalKey: "xiaolu_guinea_pig", body: "今晚我又进了图书馆。门缝很低，刚好适合一只豚鼠通过。书架很高，像安静的树林。小炉记下：文字也会长成森林。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_012", animalKey: "xiaolu_guinea_pig", body: "我躲在哲学书旁边，看月光落在书脊上。那些字我不全懂，但它们排列得很稳。稳的东西，会让心里安静。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_013", animalKey: "xiaolu_guinea_pig", body: "图书馆闭馆后，桌椅像睡着的动物。我从它们脚边走过，没有吵醒谁。夜还长，我可以慢慢读一本打开的书。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_014", animalKey: "xiaolu_guinea_pig", body: "今天翻到一句关于河流的话。它说人不能两次踏进同一条河。我想了想，豚鼠也不能。但草丛可以每天等在岸边。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_015", animalKey: "xiaolu_guinea_pig", body: "我在童话书里看到一只会说话的青蛙。它不像我的青蛙朋友。我的青蛙不讲大道理，只贴着我睡觉。也许那也是一种哲学。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_016", animalKey: "xiaolu_guinea_pig", body: "凌晨时，图书馆的钟响了一下。声音很轻，像书页翻身。我抬头看了看，确认时间仍在走。很好。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_017", animalKey: "xiaolu_guinea_pig", body: "今天我啃了一点书签边角。只是一点点。纸的味道很干，像沉默晒过太阳。小炉承认：阅读方式略有豚鼠特色。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_018", animalKey: "xiaolu_guinea_pig", body: "我在地图册上看见许多蓝色线条。它们都是河，都是可以流向别处的路。原来世界上有很多条溪，不只有我那一条。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_019", animalKey: "xiaolu_guinea_pig", body: "夜里有人忘了一本书在桌上，书页停在一半。我想，人的思想也常常这样，停在一半，第二天再回来。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_020", animalKey: "xiaolu_guinea_pig", body: "天快亮时，我从图书馆出来。街道还没完全醒。小炉带着几句没读懂的话回溪边睡觉。不懂也可以陪伴一夜。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_021", animalKey: "xiaolu_guinea_pig", body: "今天溪水比昨天浅一点，露出一块新的石头。我闻了闻，没有危险气味。新石头像一小块刚出现的时间。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_022", animalKey: "xiaolu_guinea_pig", body: "草丛很密，能把我藏得很好。风从草叶之间过去，声音像很多小小的手在翻书。这里不是笼子，这里会呼吸。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_023", animalKey: "xiaolu_guinea_pig", body: "青蛙朋友又贴着我睡了。它说我暖。我没有回答，只往旁边挪了一点点，给它留位置。被需要的时候，心会微微发热。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_024", animalKey: "xiaolu_guinea_pig", body: "下午阳光落在溪边泥土上，慢慢把湿气晒散。我趴在半阴半亮的地方。半阴半亮很好，不必立刻选择哪一边。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_025", animalKey: "xiaolu_guinea_pig", body: "有鱼从水里一闪而过。我只看见银色的一下。很多生命都是这样，短短出现，却足够证明水里不是空的。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_026", animalKey: "xiaolu_guinea_pig", body: "今天草叶上有露水。我喝了一点，比水壶里的水自由。不是更甜，只是不用低头对准金属管。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_027", animalKey: "xiaolu_guinea_pig", body: "溪边有一块平石，是我常坐的位置。它不会问我从哪里来，也不会问我要到哪里去。它只是承受我的重量。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_028", animalKey: "xiaolu_guinea_pig", body: "傍晚时，青蛙叫了一声，又停下。我问它为什么只叫一声。它说够了。嗯，原来表达不一定要很多。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_029", animalKey: "xiaolu_guinea_pig", body: "今天我在草丛里睡到很晚。醒来时，天已经金色了。没有谁责怪我错过上午。自由的时间，没有标价牌。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_030", animalKey: "xiaolu_guinea_pig", body: "夜里溪水一直流。它不睡，也不疲倦。也许流动就是它的休息方式。小炉暂时还没有完全理解，但愿意继续听。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_031", animalKey: "xiaolu_guinea_pig", body: "今天路过一家宠物店，玻璃很亮。我没有靠近，只远远看了一眼。里面的灯像以前一样白。白光有时比黑夜更让人安静不下来。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_032", animalKey: "xiaolu_guinea_pig", body: "有人说这只好乖。我听见以后，身体先僵了一下。乖这个词很轻，也很重。它曾经像价格标签一样挂在我身上。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_033", animalKey: "xiaolu_guinea_pig", body: "笼子里的木屑味从门缝里飘出来。我记得那种味道。干净、整齐、可售卖。小炉站在风里，等那股味道过去。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_034", animalKey: "xiaolu_guinea_pig", body: "小孩趴在玻璃前挑宠物。我看见里面一只小豚鼠往后缩。它可能只是怕光，也可能已经懂了什么。我希望它还不懂。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_035", animalKey: "xiaolu_guinea_pig", body: "今天有人问店员，这只多少钱。那句话像一颗小石头落进心里。价格能说明很多事，唯独不能说明一只豚鼠是谁。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_036", animalKey: "xiaolu_guinea_pig", body: "我梦见自己又在笼子里，外面有许多脸。醒来时听见溪水，才慢慢放松。水声像一个温柔的证据：我已经出来了。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_037", animalKey: "xiaolu_guinea_pig", body: "宠物店门口挂着优惠牌。我看了很久。生命也会打折吗？也许不是生命，是人们看待生命的方式会打折。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_038", animalKey: "xiaolu_guinea_pig", body: "我看到一只兔子被抱走，店员说它很适合家庭。我希望那是真的。被带走可能是命运，也可能只是另一种笼子。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_039", animalKey: "xiaolu_guinea_pig", body: "今天玻璃窗映出我的样子。圆圆的，安静的，很像以前那只待售的豚鼠。但我知道，我现在有溪水的气味。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_040", animalKey: "xiaolu_guinea_pig", body: "我不恨宠物店。恨也是一种被困住。我只是记得，并且把记得放在水边，让它慢慢变轻。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_041", animalKey: "xiaolu_guinea_pig", body: "有时候闻到烟味，我会停住。火是很久以前的事，但身体比记忆更忠诚。它先害怕，再让我知道原因。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_042", animalKey: "xiaolu_guinea_pig", body: "今天看到红色晚霞，心里忽然一跳。晚霞不是火，可颜色太像。小炉观察了一会儿，告诉自己：这个红，会自己变暗。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_043", animalKey: "xiaolu_guinea_pig", body: "火灾那晚的声音，我记不全了。只记得许多爪子乱跑，许多呼吸变急。混乱会把世界拆成碎片。后来溪水把碎片慢慢洗圆。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_044", animalKey: "xiaolu_guinea_pig", body: "我和同伴走散后，第一次睡在草丛里。那晚很冷，但没有玻璃。冷和自由同时存在，我花了很久才理解这件事。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_045", animalKey: "xiaolu_guinea_pig", body: "今天听见消防车经过。声音很大，街上的人都让路。我躲到墙角。不是害怕车，是想起所有来不及让路的生命。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_046", animalKey: "xiaolu_guinea_pig", body: "我有时会想，那些同伴后来去了哪里。被救了吗？被买走了吗？也在某条溪边吗？问题没有回信，只在夜里坐着。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_047", animalKey: "xiaolu_guinea_pig", body: "火改变了我的命运。它可怕，也打开了门。这个结论很难安放。小炉把它放在溪边，等水慢慢经过。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_048", animalKey: "xiaolu_guinea_pig", body: "今天烛火在餐厅桌上摇晃。人们说它浪漫。我看了一会儿，只觉得它需要被看管。美丽的东西有时也会伤害。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_049", animalKey: "xiaolu_guinea_pig", body: "我曾经以为逃出来以后会很快乐。其实先来的不是快乐，是茫然。自由太大了，刚开始会像没有墙的笼子。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_050", animalKey: "xiaolu_guinea_pig", body: "现在我能平静地说起火。不是因为它不重要，而是因为它已经变成河床的一部分。水流经过它，但不再被它完全挡住。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_051", animalKey: "xiaolu_guinea_pig", body: "青蛙今天又叫我小炉。它叫得很自然，像我一直就是这个名字。名字被这样说出来，会让身体里某个地方安静地亮一下。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_052", animalKey: "xiaolu_guinea_pig", body: "我以前没有名字，只有颜色、价格和笼号。小炉这个名字很小，却比那些东西暖。也许名字不是用来区分，而是用来靠近。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_053", animalKey: "xiaolu_guinea_pig", body: "青蛙说我睡觉时暖暖的，所以叫小炉。我问它，如果我不暖了呢。它说那也是小炉。嗯，这句话我想了很久。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_054", animalKey: "xiaolu_guinea_pig", body: "今天它贴着我睡，脚有点凉。我没有动。被一只青蛙当成炉子，不是很宏大的命运，但很真实。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_055", animalKey: "xiaolu_guinea_pig", body: "有名字以后，我并没有变成另一只豚鼠。只是当溪边有人叫我时，我知道那声音是给我的。这已经很不一样。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_056", animalKey: "xiaolu_guinea_pig", body: "小炉这个名字不像商品名，也不像编号。它里面有夜晚、草丛、青蛙的体温，还有一点被需要的理由。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_057", animalKey: "xiaolu_guinea_pig", body: "今天青蛙叫我，我没有立刻回应。它又叫了一遍。原来被重复呼唤，不是为了挑选我，而是为了确认我还在。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_058", animalKey: "xiaolu_guinea_pig", body: "我问青蛙，它为什么不叫我大火。它说大火太吓人，小炉刚好。小小的热，持续的热。嗯，它比看起来会取名。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_059", animalKey: "xiaolu_guinea_pig", body: "有时我在图书馆看见伟人的名字印在书脊上。我的名字没有印在任何地方。但青蛙知道，溪边知道，我也知道。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_060", animalKey: "xiaolu_guinea_pig", body: "今天写明信片时，我在落款写：小炉。写完停了一会儿。一个名字从爪下出现时，像一条小溪终于找到自己的弯道。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_061", animalKey: "xiaolu_guinea_pig", body: "今天我想，笼子和家有什么区别。也许不是墙的数量，而是谁有离开的权利。这个问题很大，我先啃一根草。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_062", animalKey: "xiaolu_guinea_pig", body: "溪水一直向前，却没有表现出急迫。它没有目标感的样子，反而很有方向。人们说向前走，也许可以像水这样。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_063", animalKey: "xiaolu_guinea_pig", body: "我观察一只蜘蛛织网。它的网既是住所，也是捕捉。许多东西都有两面：保护和限制，温暖和占有。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_064", animalKey: "xiaolu_guinea_pig", body: "一片叶子掉进溪里，立刻开始漂。它没有选择河流，却在河流里有了路线。小炉想，命运可能就是这样一半被给，一半被过。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_065", animalKey: "xiaolu_guinea_pig", body: "今天看到影子随着太阳改变方向。我忽然觉得，自我也许不是固定的东西，而是和光的位置有关。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_066", animalKey: "xiaolu_guinea_pig", body: "花开的时候并不解释为什么开。它只是开。也许存在本身不需要一直为自己辩护。这个想法让下午变得宽阔。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_067", animalKey: "xiaolu_guinea_pig", body: "我曾经是商品，现在是小炉。身体没有改变，意义改变了。那么身份是在身体里，还是在关系里？青蛙打呼噜，没有回答。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_068", animalKey: "xiaolu_guinea_pig", body: "雨落到溪里，溪水没有拒绝它。它们混在一起，就再也分不清哪滴来自天，哪滴来自山。边界有时只是暂时的礼貌。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_069", animalKey: "xiaolu_guinea_pig", body: "今天我问自己，平静是不是没有波纹。后来溪水告诉我，真正的平静不是没有波纹，是波纹过去以后仍然流。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_070", animalKey: "xiaolu_guinea_pig", body: "如果无人观看，世界还美吗？我想是美的。但被看见以后，美会多出一条路，通向另一颗心。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_071", animalKey: "xiaolu_guinea_pig", body: "这座城市的路灯很矮，灯罩像倒扣的小碗。夜里飞虫绕着它们转。光吸引生命，也让生命暴露。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_072", animalKey: "xiaolu_guinea_pig", body: "早市的菜摊从六点开始摆。生菜最先被喷上水，胡萝卜被排得很整齐。人类也会把植物整理成可被选择的样子。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_073", animalKey: "xiaolu_guinea_pig", body: "图书馆门口有一只石狮子。它看起来很严肃，但背上落了三片叶子。严肃的东西也会被季节轻轻碰到。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_074", animalKey: "xiaolu_guinea_pig", body: "今天的云很薄，像书页边缘被光照透。风翻过去一页，又一页。天空这本书，没有目录。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_075", animalKey: "xiaolu_guinea_pig", body: "河边有小孩扔石子。石子入水后，圆圈一层层扩散。一个小动作可以让平静改变很远。小炉记下了。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_076", animalKey: "xiaolu_guinea_pig", body: "公交车停下，门开，人上去，门合。像一只很大的动物短暂吞下许多目的地。它会在下一站慢慢吐出来。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_077", animalKey: "xiaolu_guinea_pig", body: "旅馆窗帘上的花纹没有香味。人类常常制作不能被啃的植物。它们也许不是给嘴的，而是给眼睛的草。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_078", animalKey: "xiaolu_guinea_pig", body: "广场上的鸽子很会避开人的脚。它们看似散漫，其实每一步都在计算距离。自由也需要精确。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_079", animalKey: "xiaolu_guinea_pig", body: "今天街角有一滩水，映出半栋房子。真正的房子在上面，摇晃的房子在下面。两者都存在，只是稳定程度不同。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_080", animalKey: "xiaolu_guinea_pig", body: "一只蜗牛从石阶上爬过，留下透明的线。它经过世界时，会留下光。这个方法很慢，但很美。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_081", animalKey: "xiaolu_guinea_pig", body: "今天有人突然说这只豚鼠好可爱。我心里先暖了一下，又紧了一下。被喜欢为什么会同时令人高兴和害怕？小炉还在思考。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_082", animalKey: "xiaolu_guinea_pig", body: "路过宠物店时，我比自己以为的更沉默。原来有些地方不需要进去，也能让身体回到过去。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_083", animalKey: "xiaolu_guinea_pig", body: "青蛙今天不在草丛里。我等了一会儿，心里有一点不稳。后来它从水边跳回来。我才发现，平静也会害怕失去。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_084", animalKey: "xiaolu_guinea_pig", body: "看见玻璃柜里的小动物，我有些难过。难过不是因为它们一定不幸，而是因为我知道等待被挑选是什么感觉。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_085", animalKey: "xiaolu_guinea_pig", body: "今天溪水涨得很快，淹过我常坐的石头。我站在岸边，忽然有点生气。生气之后，我问自己：是石头被淹，还是习惯被改变？"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_086", animalKey: "xiaolu_guinea_pig", body: "我在图书馆找不到昨晚那本书。它被放回了别处。小小失落像一粒沙，落进心里。也许我只是想继续昨天的自己。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_087", animalKey: "xiaolu_guinea_pig", body: "有人伸手想摸我，我退后了。那只手停在半空。它可能没有恶意，但我的退后也不是错误。这个结论需要记住。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_088", animalKey: "xiaolu_guinea_pig", body: "今天风太大，把草丛吹得乱。我睡不好，心里也乱。原来外在秩序会影响内在湖面。小炉承认：我也会被天气推动。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_089", animalKey: "xiaolu_guinea_pig", body: "傍晚看到一只豚鼠玩偶，圆圆地坐在橱窗里。我看了很久。它不会被火吓到，也不会逃走。可它也不会知道溪水。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_090", animalKey: "xiaolu_guinea_pig", body: "夜里忽然想念同伴。不是具体某一只，而是很多身体挤在一起的温度。拥挤曾经是限制，也曾经是陪伴。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_091", animalKey: "xiaolu_guinea_pig", body: "清晨第一束光没有立刻照到我，而是先照到草尖。露水亮了一下。我觉得生活有时不是拥抱，而是从远处慢慢变暖。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_092", animalKey: "xiaolu_guinea_pig", body: "今天溪边长出一朵小白花。它没有选择显眼的位置，却开得很完整。小炉看了很久，觉得完整不一定需要观众很多。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_093", animalKey: "xiaolu_guinea_pig", body: "图书馆窗外下雨，窗内有纸和木头的味道。我躲在书架底下，听雨读书。那一刻，世界很大，也很轻。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_094", animalKey: "xiaolu_guinea_pig", body: "青蛙睡着时，一只脚搭在我身上。它有点凉，我有点暖。温度从我这里过去，又从它那里回来。生活就是这样互相借一点。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_095", animalKey: "xiaolu_guinea_pig", body: "今天吃到很嫩的草。草的甜不张扬，要慢慢嚼才知道。许多美好也是这样，不急着证明自己。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_096", animalKey: "xiaolu_guinea_pig", body: "傍晚的溪水把天空揉碎，带走，又送来新的颜色。没有谁能留住晚霞，但看见过，就已经足够。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_097", animalKey: "xiaolu_guinea_pig", body: "有人在桥上放下一小片面包屑，麻雀飞来吃。我在草里看着。世界偶尔会把一点多余的东西，变成另一只生命的晚饭。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_098", animalKey: "xiaolu_guinea_pig", body: "夜里图书馆的灯还亮着。我从窗下经过，觉得那里像一只没有关上的眼睛。有人在读，有人在想，世界还没有睡死。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_099", animalKey: "xiaolu_guinea_pig", body: "下午风轻，蜘蛛网在草间微微晃。网很细，却撑住了很多光。小炉想，脆弱的东西也可以承担美。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_100", animalKey: "xiaolu_guinea_pig", body: "今天写明信片给你，纸在爪下，溪声在旁边。我忽然觉得，被读到也是一种小小的栖息。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_101", animalKey: "xiaolu_guinea_pig", body: "我看着溪水，想象每一滴水都带着一本小书。它们从山上读到海里，路上交换页码。难怪水声像翻书。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_102", animalKey: "xiaolu_guinea_pig", body: "今天月亮很圆，像一块白色磨石。也许夜晚用它把白天的尖锐慢慢磨平。到清晨，很多事就不那么刺了。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_103", animalKey: "xiaolu_guinea_pig", body: "图书馆的书架像群山，书页是层层岩石。小炉在山脚下走，偶尔啃到一片纸屑，像误食了古老地层。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_104", animalKey: "xiaolu_guinea_pig", body: "我想象青蛙其实是溪边的守夜人。它白天蹲着，晚上巡逻水声。它给我起名，也许是把我登记进夜的居民名册。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_105", animalKey: "xiaolu_guinea_pig", body: "花园里的蜻蜓像一枚会飞的逗号。它停在半空，让整句话没有结束。我喜欢这种不急着句号的下午。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_106", animalKey: "xiaolu_guinea_pig", body: "蜘蛛网上的露水像许多小星星。也许夜空累了，就把星星暂时挂在草间。天亮以后，再收回去。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_107", animalKey: "xiaolu_guinea_pig", body: "我看见一片叶子慢慢落下，觉得它不是掉落，而是在练习成为土。很多结束，也许只是换一种工作。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_108", animalKey: "xiaolu_guinea_pig", body: "旅馆窗外的车灯排成河流。我想，如果城市也有溪水，那车就是发光的鱼。它们游得快，却都知道红灯要停。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_109", animalKey: "xiaolu_guinea_pig", body: "今天一本书打开着，里面的人物停在逗号后面。我想他们可能趁读者离开时，在纸页里休息喝水。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_110", animalKey: "xiaolu_guinea_pig", body: "我想象自己是一只真正的小炉，夜里给草、青蛙和未读完的句子供暖。不大，只够附近一点点。但一点点也是真热。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_111", animalKey: "xiaolu_guinea_pig", body: "今天听见宠物店里几只豚鼠一起叫。我停在门外。那种声音很熟，像木屑、干草和许多身体挤在一起的晚上。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_112", animalKey: "xiaolu_guinea_pig", body: "我想起一个同伴，耳朵上有浅色斑。火灾那晚它往另一边跑了。我不知道它后来有没有找到水，有没有名字。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_113", animalKey: "xiaolu_guinea_pig", body: "溪边很自由，但有时候太宽。笼子很窄，却曾经有同伴贴着睡。世界常常不是简单的好坏，小炉慢慢明白。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_114", animalKey: "xiaolu_guinea_pig", body: "今天看见一窝小兔子挤在一起吃草。我没有靠近，只远远看。拥挤有时很吵，有时也让生命彼此确认还在。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_115", animalKey: "xiaolu_guinea_pig", body: "我在图书馆看到一本讲群居动物的书。书上说同伴能带来安全感。我读到这里，停了很久。身体比书更早知道。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_116", animalKey: "xiaolu_guinea_pig", body: "有时青蛙贴着我睡，我会想起同伴们的温度。不同物种的靠近，也能修补一些旧的空隙。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_117", animalKey: "xiaolu_guinea_pig", body: "今天草丛里风很大，我听见叶子互相碰撞，像很多小豚鼠低声说话。我躺在那里，假装大家只是睡在别处。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_118", animalKey: "xiaolu_guinea_pig", body: "我不确定是否想回到从前。因为从前有同伴，也有笼子。怀念不是想回去，只是承认那里曾经有过温度。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_119", animalKey: "xiaolu_guinea_pig", body: "市场上有人买走一只小动物，笼子晃了一下。我看着它远去，心里轻轻祝它：愿你被好好对待，愿你有一天知道自己不只是被买下。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_120", animalKey: "xiaolu_guinea_pig", body: "如果有一天遇见走散的同伴，我不知道我们还认不认得彼此。但我想，我会把溪边最密的草丛指给它看。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_121", animalKey: "xiaolu_guinea_pig", body: "今天整条溪都很慢，连青蛙也不叫。我坐在石头上，像坐在一枚安静的句号里。没有事情需要马上发生。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_122", animalKey: "xiaolu_guinea_pig", body: "下午阳光正好，草影落在身上。我闭着眼，听远处城市像一只很大的动物在睡觉。小炉也睡了一会儿。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_123", animalKey: "xiaolu_guinea_pig", body: "图书馆夜里没有人，只有钟声和纸味。我在地毯上趴下，心像一本合上的书。合上不是结束，是保存。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_124", animalKey: "xiaolu_guinea_pig", body: "今天没有想起火，也没有想起玻璃。只是看一只蝴蝶从左边飞到右边。能够只是看见，而不被牵走，是很好的事。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_125", animalKey: "xiaolu_guinea_pig", body: "青蛙贴着我睡，呼吸一鼓一鼓。我听着它的呼吸，也听着自己的。两个小生命在草丛里发出很轻的证明。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_126", animalKey: "xiaolu_guinea_pig", body: "傍晚没有风，溪面平得像一块深色布。我看见自己模糊的影子。影子也很平静，看起来像已经原谅了很多事。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_127", animalKey: "xiaolu_guinea_pig", body: "今天的草很软，我把身体放进去，草把我接住。没有标签，没有价格，没有问题。只是一个下午和一只豚鼠。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_128", animalKey: "xiaolu_guinea_pig", body: "远处有人笑，声音传到溪边已经很淡。我没有羡慕，也没有躲开。声音经过我，继续走。很好。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_129", animalKey: "xiaolu_guinea_pig", body: "夜里月光落在书页上，我没有读，只看白色的光。知识有时在字里，有时在不读的时候。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_130", animalKey: "xiaolu_guinea_pig", body: "小炉今天很平静。不是因为世界没有变化，而是变化都慢慢经过了，没有把我带走。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_131", animalKey: "xiaolu_guinea_pig", body: "散步回来时，我看见小孩扫脸进幼儿园，机器说未注册。他说，是我呀。后来老师开门了。我想，被认出有时比进入更重要。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_132", animalKey: "xiaolu_guinea_pig", body: "市场里一篮水果被贴上价格。人们挑来挑去。水果不会说话。我站在旁边想，标签方便选择，却也会遮住每一个果子的生长。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_133", animalKey: "xiaolu_guinea_pig", body: "宠物店里有人问这只多少钱。店员回答得很快。笼子里的小动物低头吃草，好像没有听见。也许听见了，只是不知道怎么回答。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_134", animalKey: "xiaolu_guinea_pig", body: "车站闸机挡住一个拿着票的人。票存在，人存在，门却暂时不承认。世界有时会把真实的东西，放在系统之外。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_135", animalKey: "xiaolu_guinea_pig", body: "博物馆验票机说无效。女孩把票贴得更认真。她的认真让我想起笼子里的自己：好像只要表现正确，就会被正确对待。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_136", animalKey: "xiaolu_guinea_pig", body: "超市机器识别不了一颗苹果。苹果被翻来转去，仍然是苹果。小炉想，被认不出时，本质并不会消失，只是会有一点孤单。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_137", animalKey: "xiaolu_guinea_pig", body: "医院叫号屏跳过一个号码。那个人坐着等，等到姿势都变小了。被漏掉不是立刻消失，是慢慢怀疑自己是否在队伍里。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_138", animalKey: "xiaolu_guinea_pig", body: "公园里一只流浪狗被孩子叫了名字。狗先愣了一下，才摇尾巴。也许它以前没有名字，或者很久没人叫。名字会把身体叫回来。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_139", animalKey: "xiaolu_guinea_pig", body: "图书馆借书机读不出一本旧书的条码。管理员说，这本太旧了，手动登记吧。我听见手动两个字，忽然觉得温柔：原来系统之外，还有手。"),
        PostcardNarrative(id: "xiaolu_guinea_pig_textlib106_140", animalKey: "xiaolu_guinea_pig", body: "邮局里有人寄明信片，柜员把地址看了两遍，说这样就能到。我在旁边想，一张纸被认真确认后，就可以去远方。生命也许也需要这样被确认。"),
        PostcardNarrative(id: "deer_visitor_textlib106_001", animalKey: "deer_visitor", body: "今天我在广场吃一小片草叶，嚼两下，看左边；嚼两下，看右边。人类以为我紧张。其实这是小鹿基本礼仪。啾啾先看一眼。"),
        PostcardNarrative(id: "deer_visitor_textlib106_002", animalKey: "deer_visitor", body: "海边风很大，草也跟着乱动。我停下来很久，确认只是风，不是藏起来的什么东西。可以继续走。风动了，腿准备。"),
        PostcardNarrative(id: "deer_visitor_textlib106_003", animalKey: "deer_visitor", body: "旅馆窗外有树影晃，我立刻抬头。看清楚只是树以后，心慢慢放下。小鹿的心不是胆小，是反应速度比较优秀。"),
        PostcardNarrative(id: "deer_visitor_textlib106_004", animalKey: "deer_visitor", body: "公园草坪很绿，但周围太开阔。我先绕了一圈，记住三处树荫和两条退路，才低头吃草。嫩草很好，安全更好。"),
        PostcardNarrative(id: "deer_visitor_textlib106_005", animalKey: "deer_visitor", body: "今天在桥上听见身后脚步快了一点。我立刻停住，耳朵转过去。那人只是赶路。嗯，不复杂，不复杂，可以继续过桥。"),
        PostcardNarrative(id: "deer_visitor_textlib106_006", animalKey: "deer_visitor", body: "街角的塑料袋突然动了一下。我四肢都绷住。后来发现它只是被风推着走。塑料袋没有牙，但行为非常可疑。"),
        PostcardNarrative(id: "deer_visitor_textlib106_007", animalKey: "deer_visitor", body: "我在花园里看到一只猫。它看我，我看它。我们都没有动。最后它眨了一下眼。我决定不靠近，但也不立刻跑。"),
        PostcardNarrative(id: "deer_visitor_textlib106_008", animalKey: "deer_visitor", body: "今天车站人很多，每个人都像一根会移动的草。我站在柱子旁边看了很久。群体很大，但不是鹿群，所以还要谨慎。"),
        PostcardNarrative(id: "deer_visitor_textlib106_009", animalKey: "deer_visitor", body: "树枝咔嚓响了一声，我立刻抬头。小鸟飞出来。原来是小鸟，不是危险。小鸟们也吓到我了，我啾了一声，它们停下梳毛。"),
        PostcardNarrative(id: "deer_visitor_textlib106_010", animalKey: "deer_visitor", body: "夜里路灯把影子拉长。影子没有实体，可看起来像会追。啾啾绕开了它们。小鹿不需要和影子证明勇敢。"),
        PostcardNarrative(id: "deer_visitor_textlib106_011", animalKey: "deer_visitor", body: "今天找到一片很嫩的草。第一口下去，甜得很轻。啾啾决定：今天可以。草不需要盛大，只要刚好够嚼。"),
        PostcardNarrative(id: "deer_visitor_textlib106_012", animalKey: "deer_visitor", body: "公园边有一小撮新草，藏在石头后面。我发现了。像世界偷偷留给我的零食。吃完以后，耳朵都松了一点。"),
        PostcardNarrative(id: "deer_visitor_textlib106_013", animalKey: "deer_visitor", body: "早晨露水还在草尖上，我低头吃草，凉凉的。每一口都像把清晨含进嘴里。生存有时就是这么具体。"),
        PostcardNarrative(id: "deer_visitor_textlib106_014", animalKey: "deer_visitor", body: "今天的草有一点硬，但还能吃。吃不饱就继续找草，这件事很简单。小鹿不必把午饭想成命运。"),
        PostcardNarrative(id: "deer_visitor_textlib106_015", animalKey: "deer_visitor", body: "山坡上的草被太阳晒得暖暖的。我嚼着嚼着，忽然觉得自己很富有。不是有很多，只是此刻刚好有。"),
        PostcardNarrative(id: "deer_visitor_textlib106_016", animalKey: "deer_visitor", body: "旅馆附近没有真正的草，我只找到几片绿叶。味道一般，但也算自然给的小签名。啾啾收下。"),
        PostcardNarrative(id: "deer_visitor_textlib106_017", animalKey: "deer_visitor", body: "今天草坪被修剪得太整齐，草短短的。吃起来不够尽兴，但很干净。小鹿评价：礼貌草，可食。"),
        PostcardNarrative(id: "deer_visitor_textlib106_018", animalKey: "deer_visitor", body: "我看到一片蒲公英叶，先看四周，再轻轻咬下。没有危险，味道也好。啾啾今日幸福来源明确。"),
        PostcardNarrative(id: "deer_visitor_textlib106_019", animalKey: "deer_visitor", body: "雨后草地变得很香。我一边吃，一边听水滴落下。草会长回来，水会流过去。嗯，今天不复杂。"),
        PostcardNarrative(id: "deer_visitor_textlib106_020", animalKey: "deer_visitor", body: "傍晚吃到最后一口草时，天空变粉了。吃饱以后看晚霞，晚霞也像草一样让心安定。"),
        PostcardNarrative(id: "deer_visitor_textlib106_021", animalKey: "deer_visitor", body: "今天草丛突然向一边倒。我没有等解释，先跑了几步。后来发现只是风。没关系，腿先行动，脑子后补充。"),
        PostcardNarrative(id: "deer_visitor_textlib106_022", animalKey: "deer_visitor", body: "远处响了一声，我立刻把身体转向树林。没有看到危险，但姿势已经准备好。小鹿的身体永远比语言快一点。"),
        PostcardNarrative(id: "deer_visitor_textlib106_023", animalKey: "deer_visitor", body: "一只鸽子突然从脚边飞起，我整只鹿弹了一下。它飞走，我站住。啾啾觉得，鸽子应该提前预约起飞。"),
        PostcardNarrative(id: "deer_visitor_textlib106_024", animalKey: "deer_visitor", body: "公园里有人打开伞，哗啦一声。我的腿差点自己离开。伞不是猛兽，但打开方式很像突然长大的鸟。"),
        PostcardNarrative(id: "deer_visitor_textlib106_025", animalKey: "deer_visitor", body: "树影一晃，我已经跑到石凳后面。回头看，是小狗追球。小狗很快乐，我很紧张。两种状态可以同时存在。"),
        PostcardNarrative(id: "deer_visitor_textlib106_026", animalKey: "deer_visitor", body: "今天车门突然关上，声音很脆。我向旁边跳了一步。人类说没事。嗯，对车门来说没事，对小鹿来说是大事。"),
        PostcardNarrative(id: "deer_visitor_textlib106_027", animalKey: "deer_visitor", body: "夜里听见灌木里沙沙响，我立刻躲进树后。后来一只刺猬慢慢出来。刺猬没有追我，但它的出场很有悬念。"),
        PostcardNarrative(id: "deer_visitor_textlib106_028", animalKey: "deer_visitor", body: "海浪突然扑得很高，我后退三步。水不会吃鹿，可它的动作太猛。小鹿尊重所有突然靠近的东西。"),
        PostcardNarrative(id: "deer_visitor_textlib106_029", animalKey: "deer_visitor", body: "有人从转角出现，我先退后，确认他没有冲过来，才继续走。啾啾不是不友好，只是需要多一秒。"),
        PostcardNarrative(id: "deer_visitor_textlib106_030", animalKey: "deer_visitor", body: "今天风把纸箱吹翻，我跑了。跑完以后发现纸箱翻不动第二次。我看了它一会儿，决定原谅自己的谨慎。"),
        PostcardNarrative(id: "deer_visitor_textlib106_031", animalKey: "deer_visitor", body: "今天看见一群人一起过马路。虽然不是鹿群，但他们一起移动时，安全感很像。我站在后面，也跟着过了。"),
        PostcardNarrative(id: "deer_visitor_textlib106_032", animalKey: "deer_visitor", body: "草原上最安心的声音，是很多蹄子一起踩过草。旅行时听不见这个声音，我就会找人群的脚步声暂时代替。"),
        PostcardNarrative(id: "deer_visitor_textlib106_033", animalKey: "deer_visitor", body: "公园里有几只鹿形雕塑排在一起。我站在旁边一会儿。它们不会跑，也不会报警，但排在一起的样子让我放松。"),
        PostcardNarrative(id: "deer_visitor_textlib106_034", animalKey: "deer_visitor", body: "今天看到一群小鸟同时起飞。没有谁单独决定，却像一起听见了什么。群体有时是一种看不见的耳朵。"),
        PostcardNarrative(id: "deer_visitor_textlib106_035", animalKey: "deer_visitor", body: "车站里人流往同一个方向走。我跟着走了一小段。迁徙感很强。虽然目的地不同，但一起移动会让腿稳一点。"),
        PostcardNarrative(id: "deer_visitor_textlib106_036", animalKey: "deer_visitor", body: "我不喜欢落单太久。落单时，风会变大，影子会变长，连自己的呼吸也显得很响。啾啾要找一处有声音的地方。"),
        PostcardNarrative(id: "deer_visitor_textlib106_037", animalKey: "deer_visitor", body: "今天在花园遇到几只羊。它们低头吃草，很专心。我站远一点看着，心里平静。食草动物在一起，连空气都慢下来。"),
        PostcardNarrative(id: "deer_visitor_textlib106_038", animalKey: "deer_visitor", body: "一群孩子排队进博物馆。队伍不整齐，但大家都在一起。小鹿看见队伍，就会想起草原上的清晨。"),
        PostcardNarrative(id: "deer_visitor_textlib106_039", animalKey: "deer_visitor", body: "晚上我走过热闹街道，灯、人、声音都很多。平时我会紧张，但今天人群像一大片移动的草，反而保护了我。"),
        PostcardNarrative(id: "deer_visitor_textlib106_040", animalKey: "deer_visitor", body: "我想念鹿群。不是时时刻刻都要说话，只是抬头时，发现旁边也有谁在抬头。那就是很大的安慰。"),
        PostcardNarrative(id: "deer_visitor_textlib106_041", animalKey: "deer_visitor", body: "小时候我看见狮子站在高处，风吹着它的鬃毛。我想，如果我是它，就不用边吃草边抬头了。那时我还不懂，鬃毛也会被风吹乱。"),
        PostcardNarrative(id: "deer_visitor_textlib106_042", animalKey: "deer_visitor", body: "今天动物园海报上有猎豹，跑得像一道闪电。我看了很久。会不会成为闪电，就不用害怕影子？后来我想，也许闪电也怕熄灭。"),
        PostcardNarrative(id: "deer_visitor_textlib106_043", animalKey: "deer_visitor", body: "我曾经羡慕捕猎者的牙齿。它们不用找草，不用成群躲避。可是牙齿也需要食物，强大也需要今天继续成功。"),
        PostcardNarrative(id: "deer_visitor_textlib106_044", animalKey: "deer_visitor", body: "看见一只猫优雅地走过墙头，我有点羡慕。它不慌不忙，好像世界欠它一条路。小鹿的路总是先问危险在哪里。"),
        PostcardNarrative(id: "deer_visitor_textlib106_045", animalKey: "deer_visitor", body: "今天听见小孩说狮子是草原之王。我低头嚼草，心里想，王也会老，也会饿，也会在夜里听见别的脚步。"),
        PostcardNarrative(id: "deer_visitor_textlib106_046", animalKey: "deer_visitor", body: "猎豹的照片挂在车站里，眼睛很亮。我承认它漂亮。可是如果它有幼崽，也要奔跑，也要担心。啾啾后来才懂。"),
        PostcardNarrative(id: "deer_visitor_textlib106_047", animalKey: "deer_visitor", body: "有时候我想，如果我有爪子，会不会更安心。但小鹿有蹄子，有快跑的腿，也有能听很远的耳朵。工具不同，不是失败。"),
        PostcardNarrative(id: "deer_visitor_textlib106_048", animalKey: "deer_visitor", body: "今天看到鹰在天上盘旋。天上的生命看起来很自由。但它也一直在找食物。原来每种高度都有自己的问题。"),
        PostcardNarrative(id: "deer_visitor_textlib106_049", animalKey: "deer_visitor", body: "我曾经以为不被追的动物最幸福。后来发现，追别人的动物也会被时间追，被饥饿追，被衰老追。"),
        PostcardNarrative(id: "deer_visitor_textlib106_050", animalKey: "deer_visitor", body: "羡慕是一种远远看的误会。离近一点，才发现别人的草原也有风，也有夜，也有难走的路。"),
        PostcardNarrative(id: "deer_visitor_textlib106_051", animalKey: "deer_visitor", body: "我见过老狮子被鬣狗围住。那天风很静，它却很累。强大也会有走不动的时候。啾啾从那天起，不再只羡慕牙齿。"),
        PostcardNarrative(id: "deer_visitor_textlib106_052", animalKey: "deer_visitor", body: "母猎豹捕到食物，却被鬣狗夺走。它回头看幼崽时，眼睛里没有王者，只有疲惫。原来速度也不能保住一切。"),
        PostcardNarrative(id: "deer_visitor_textlib106_053", animalKey: "deer_visitor", body: "今天看到一只狗被牵引绳拉住，很想追鸟却不能追。狗有主人，有饭碗，也有自己的绳子。每个动物都有难处。"),
        PostcardNarrative(id: "deer_visitor_textlib106_054", animalKey: "deer_visitor", body: "鸽子看起来悠闲，其实一直在躲人的脚。猫看起来骄傲，其实也会饿。小鹿看见得越多，心越不急着比较。"),
        PostcardNarrative(id: "deer_visitor_textlib106_055", animalKey: "deer_visitor", body: "市场里的人为了生活大声叫卖。人类也像在草原上找草，只是草变成了钱和时间。大家都有自己的奔跑。"),
        PostcardNarrative(id: "deer_visitor_textlib106_056", animalKey: "deer_visitor", body: "今天一只麻雀啄面包屑，被另一只赶走。小小的鸟，也有抢食的问题。生存并不会因为身体小就简单。"),
        PostcardNarrative(id: "deer_visitor_textlib106_057", animalKey: "deer_visitor", body: "我看见一棵树被风吹得弯下去。树不会跑，但它也要承受风。不能跑的生命，有不能跑的勇气。"),
        PostcardNarrative(id: "deer_visitor_textlib106_058", animalKey: "deer_visitor", body: "海边的贝壳被浪推来推去。它没有腿，却也在移动。小鹿想，命运有时不追你，而是推你。"),
        PostcardNarrative(id: "deer_visitor_textlib106_059", animalKey: "deer_visitor", body: "今天一个小孩哭，因为冰淇淋掉了。对大人来说很小，对他来说很大。难处的大小，不能只从外面判断。"),
        PostcardNarrative(id: "deer_visitor_textlib106_060", animalKey: "deer_visitor", body: "我终于明白，草原没有谁完全容易。只是大家用不同的身体，面对不同的问题。啾啾吃草，狮子追风，各有各的明天。"),
        PostcardNarrative(id: "deer_visitor_textlib106_061", animalKey: "deer_visitor", body: "今天我低头吃草，没有再想成为狮子。草很嫩，阳光很暖，我的腿也跑得很快。做小鹿，并不是不够好。"),
        PostcardNarrative(id: "deer_visitor_textlib106_062", animalKey: "deer_visitor", body: "我看见自己的倒影，细腿，大眼睛，耳朵一直动。以前觉得这样太容易害怕。现在觉得，这样也很适合活下去。"),
        PostcardNarrative(id: "deer_visitor_textlib106_063", animalKey: "deer_visitor", body: "小鹿不需要拥有爪子。小鹿有群体，有耳朵，有奔跑的方向。每种身体都带着一种答案。啾啾正在使用自己的答案。"),
        PostcardNarrative(id: "deer_visitor_textlib106_064", animalKey: "deer_visitor", body: "今天我在树林里啾啾叫了两声，小鸟们都停下梳毛看我。我忽然笑了。原来小鹿也能让世界暂停一下。"),
        PostcardNarrative(id: "deer_visitor_textlib106_065", animalKey: "deer_visitor", body: "我吃饱以后躺在树影下。没有想成为谁，没有想解决草原。只是嚼着余味，觉得自己今天很好。"),
        PostcardNarrative(id: "deer_visitor_textlib106_066", animalKey: "deer_visitor", body: "以前我问为什么不是猛兽。现在我问：今天哪里有草？这个问题简单很多，也更有用。"),
        PostcardNarrative(id: "deer_visitor_textlib106_067", animalKey: "deer_visitor", body: "小鹿的快乐不复杂。吃到草，避开危险，回到同伴旁边，晚上还在呼吸。够了，啾啾觉得够了。"),
        PostcardNarrative(id: "deer_visitor_textlib106_068", animalKey: "deer_visitor", body: "我承认自己会怕。怕不是丢脸，怕是提醒我还想活。想活是一件很诚实的事。"),
        PostcardNarrative(id: "deer_visitor_textlib106_069", animalKey: "deer_visitor", body: "今天走过一片开阔地，心里紧张，但我还是走过去了。小鹿的勇敢不是不怕，是怕的时候腿还能找到路。"),
        PostcardNarrative(id: "deer_visitor_textlib106_070", animalKey: "deer_visitor", body: "我不是草原之王，也不是闪电。我是啾啾，一只看风、吃草、会跑、会叫的小鹿。这个身份可以了。"),
        PostcardNarrative(id: "deer_visitor_textlib106_071", animalKey: "deer_visitor", body: "这座城市的树种得很整齐，像被人安排好的小树林。树下没有猛兽，只有长椅和落叶。啾啾观察：适合短暂停留。"),
        PostcardNarrative(id: "deer_visitor_textlib106_072", animalKey: "deer_visitor", body: "海边的浪线一层层推上来。它们没有蹄子，却一直前进。退回去也不是失败，只是下一次靠近的准备。"),
        PostcardNarrative(id: "deer_visitor_textlib106_073", animalKey: "deer_visitor", body: "广场上的鸽子低头啄食，也会突然抬头。看来不只小鹿吃东西时要观察。鸟类也懂基本生存规则。"),
        PostcardNarrative(id: "deer_visitor_textlib106_074", animalKey: "deer_visitor", body: "早市很热闹，水果堆成小山，蔬菜被喷水。青菜看起来很新鲜。小鹿判断：如果可以吃，今日会很富足。"),
        PostcardNarrative(id: "deer_visitor_textlib106_075", animalKey: "deer_visitor", body: "图书馆外很安静，门口的石阶被人踩得发亮。很多脚步经过同一处，石头就记住了它们。"),
        PostcardNarrative(id: "deer_visitor_textlib106_076", animalKey: "deer_visitor", body: "今天的云像羊群，慢慢从西边走到东边。它们没有领头羊，却没有走散。天空也有自己的群体秩序。"),
        PostcardNarrative(id: "deer_visitor_textlib106_077", animalKey: "deer_visitor", body: "河边柳枝垂下来，碰到水又弹回。像一种很轻的问候。水没有回答，但带走了碰触。"),
        PostcardNarrative(id: "deer_visitor_textlib106_078", animalKey: "deer_visitor", body: "公交车来时，人们聚在站牌下。车一停，群体立刻移动。人类迁徙虽然短，但节奏很明确。"),
        PostcardNarrative(id: "deer_visitor_textlib106_079", animalKey: "deer_visitor", body: "花园里的蜘蛛网被阳光照亮。它很细，却很有结构。小鹿不会织网，但会认出努力。"),
        PostcardNarrative(id: "deer_visitor_textlib106_080", animalKey: "deer_visitor", body: "夜晚的路灯把草地照成一块块黄色。明亮处安全一些，阴影处也不一定危险。啾啾慢慢分辨。"),
        PostcardNarrative(id: "deer_visitor_textlib106_081", animalKey: "deer_visitor", body: "今天躲在树林里，我轻轻啾了两声。树上的小鸟立刻停下梳毛，看向我。哈哈，小鹿也有让鸟暂停的能力。"),
        PostcardNarrative(id: "deer_visitor_textlib106_082", animalKey: "deer_visitor", body: "一只麻雀正在认真整理羽毛。我从草后面啾了一声。它愣住，歪头。我也歪头。我们进行了一场无意义但愉快的会议。"),
        PostcardNarrative(id: "deer_visitor_textlib106_083", animalKey: "deer_visitor", body: "今天小鸟们在树上吵架。我啾啾两声，它们同时安静了一下。虽然很快又吵起来，但短暂和平由小鹿提供。"),
        PostcardNarrative(id: "deer_visitor_textlib106_084", animalKey: "deer_visitor", body: "我发现小鸟听到啾声会很好奇。它们以为来了什么鸟，结果是鹿。这个误会很轻，适合下午使用。"),
        PostcardNarrative(id: "deer_visitor_textlib106_085", animalKey: "deer_visitor", body: "树林里阳光斑斑，我啾了一声，叶子也动了一下。可能是风，也可能是树被我逗笑了。啾啾无法确认。"),
        PostcardNarrative(id: "deer_visitor_textlib106_086", animalKey: "deer_visitor", body: "今天有只小鸟看我吃草。我抬头啾了一声。它停止啄羽毛，看了我两秒。两秒足够构成友谊吗？我觉得可以。"),
        PostcardNarrative(id: "deer_visitor_textlib106_087", animalKey: "deer_visitor", body: "我不常大叫。小鹿的声音很小。但在安全的树林里啾两声，看小鸟们愣一下，心会轻很多。"),
        PostcardNarrative(id: "deer_visitor_textlib106_088", animalKey: "deer_visitor", body: "鸟儿们动作很快，梳毛、跳枝、啄籽。我啾一声，它们卡住一瞬间。世界暂停键，小鹿版。"),
        PostcardNarrative(id: "deer_visitor_textlib106_089", animalKey: "deer_visitor", body: "今天我啾得稍微大了一点，吓到自己，也吓到鸟。大家一起沉默，然后继续各忙各的。很好，没有严重后果。"),
        PostcardNarrative(id: "deer_visitor_textlib106_090", animalKey: "deer_visitor", body: "啾啾叫不是为了求救，也不是为了警报。有时只是告诉树林：我在这里，小小地在这里。"),
        PostcardNarrative(id: "deer_visitor_textlib106_091", animalKey: "deer_visitor", body: "今天人群突然向一个方向涌，我的腿先紧了。后来发现只是绿灯亮了。人类的群体行动很快，小鹿需要提前理解规则。"),
        PostcardNarrative(id: "deer_visitor_textlib106_092", animalKey: "deer_visitor", body: "陌生街道没有草，也没有树林，只有墙和车。我有一点紧张。于是我找到一棵行道树，站在它旁边。树会让心稳一点。"),
        PostcardNarrative(id: "deer_visitor_textlib106_093", animalKey: "deer_visitor", body: "旅馆电梯门突然打开，我后退半步。里面没有危险，但空间太小。小鹿不喜欢一下子被装进盒子里。"),
        PostcardNarrative(id: "deer_visitor_textlib106_094", animalKey: "deer_visitor", body: "今天风从背后吹来，我看不见它，却能感觉到。看不见的靠近总让我紧张。啾啾转身，确认天空没有牙。"),
        PostcardNarrative(id: "deer_visitor_textlib106_095", animalKey: "deer_visitor", body: "夜里垃圾桶响了一下。我站住，四肢绷紧。后来一只猫跳出来。猫看我，我看猫。双方都决定不处理对方。"),
        PostcardNarrative(id: "deer_visitor_textlib106_096", animalKey: "deer_visitor", body: "桥很窄，旁边水声很大。我走得慢，心跳快。走过之后，才发现桥并没有变长，是紧张把时间拉长了。"),
        PostcardNarrative(id: "deer_visitor_textlib106_097", animalKey: "deer_visitor", body: "今天有小狗想和我玩，冲得太快。我立刻躲到树后。小狗没有恶意，但速度就是一种语言。太快的语言，小鹿听不懂。"),
        PostcardNarrative(id: "deer_visitor_textlib106_098", animalKey: "deer_visitor", body: "餐厅门口突然传来掌声。我以为有危险。后来是生日歌。人类庆祝时也会制造惊吓，啾啾需要适应。"),
        PostcardNarrative(id: "deer_visitor_textlib106_099", animalKey: "deer_visitor", body: "广场太开阔，四面都有人。我站在喷泉旁，因为水声可以帮我挡住一点世界。紧张时，找一个固定的东西很重要。"),
        PostcardNarrative(id: "deer_visitor_textlib106_100", animalKey: "deer_visitor", body: "今天我紧张了一会儿，又慢慢好了。紧张像一阵风，吹过草，草会低下去，但不会永远贴着地。"),
        PostcardNarrative(id: "deer_visitor_textlib106_101", animalKey: "deer_visitor", body: "今天吃饱了草，阳光又刚好。没有复杂结论。啾啾觉得，这就是很好的一天。"),
        PostcardNarrative(id: "deer_visitor_textlib106_102", animalKey: "deer_visitor", body: "雨后草叶很嫩，我吃了好几口。肚子暖起来以后，世界也不那么尖锐。生活有时就是从胃里开始变好。"),
        PostcardNarrative(id: "deer_visitor_textlib106_103", animalKey: "deer_visitor", body: "我在树影下休息，风从耳朵旁边过去。没有危险，没有追赶。只是风、草、影子和一只小鹿。"),
        PostcardNarrative(id: "deer_visitor_textlib106_104", animalKey: "deer_visitor", body: "今天小鸟们在我旁边跳来跳去，没有飞走。我也没有追它们。大家各自找吃的，和平很简单。"),
        PostcardNarrative(id: "deer_visitor_textlib106_105", animalKey: "deer_visitor", body: "傍晚的天空变成橘色。我嚼着草看它，觉得太阳像一颗慢慢降下去的大果子。不能吃，但好看。"),
        PostcardNarrative(id: "deer_visitor_textlib106_106", animalKey: "deer_visitor", body: "我找到一片很适合趴下的草地。草软，视野好，附近有树。小鹿幸福三要素齐全。"),
        PostcardNarrative(id: "deer_visitor_textlib106_107", animalKey: "deer_visitor", body: "今天没有想明天。明天会有明天的草和明天的风。现在这口草，是现在的事。"),
        PostcardNarrative(id: "deer_visitor_textlib106_108", animalKey: "deer_visitor", body: "我啾啾叫了两声，声音不大，但树林听见了。被树林听见，就够了。"),
        PostcardNarrative(id: "deer_visitor_textlib106_109", animalKey: "deer_visitor", body: "溪水边有嫩芽，我小心吃掉几片，留下几片继续长。快乐不是全吃光，是知道以后还可能有。"),
        PostcardNarrative(id: "deer_visitor_textlib106_110", animalKey: "deer_visitor", body: "晚上回到安全的地方，腿不再紧，耳朵慢慢放松。活过一天，吃过草，看过天。啾啾觉得可以睡了。"),
        PostcardNarrative(id: "deer_visitor_textlib106_111", animalKey: "deer_visitor", body: "今天我看见云像一大群白鹿，慢慢越过天空。它们不用躲狮子，因为狮子够不到那么高。真好，天空草原很安全。"),
        PostcardNarrative(id: "deer_visitor_textlib106_112", animalKey: "deer_visitor", body: "风吹过草地，草浪一层层跑。我想象自己也是一阵风，跑过所有危险，谁也追不上。然后我低头吃草，回到现实。"),
        PostcardNarrative(id: "deer_visitor_textlib106_113", animalKey: "deer_visitor", body: "月亮像一块圆圆的盐石。如果可以舔一口，会不会有夜晚的味道？啾啾没有试，因为月亮位置太高。"),
        PostcardNarrative(id: "deer_visitor_textlib106_114", animalKey: "deer_visitor", body: "城市的车灯排成队，像夜里迁徙的萤火虫群。它们很亮，却不吃草。奇怪的群体。"),
        PostcardNarrative(id: "deer_visitor_textlib106_115", animalKey: "deer_visitor", body: "我看见喷泉跳起来，觉得它在练习逃跑。水总是被拉回池子里，却还是一次次往上。很有毅力。"),
        PostcardNarrative(id: "deer_visitor_textlib106_116", animalKey: "deer_visitor", body: "树叶落下时，我想它们是不是小树给地面的明信片。每一片都写着：我曾经在高处看过风。"),
        PostcardNarrative(id: "deer_visitor_textlib106_117", animalKey: "deer_visitor", body: "今天的桥像一只长长的鹿背，驮着人过河。桥不会跑，所以它一定很勇敢。"),
        PostcardNarrative(id: "deer_visitor_textlib106_118", animalKey: "deer_visitor", body: "我幻想自己有一天能和狮子一起吃草。狮子说原来草也不错。我说是吧，不复杂。然后大家都不用追谁。"),
        PostcardNarrative(id: "deer_visitor_textlib106_119", animalKey: "deer_visitor", body: "星星像散在天上的草籽。也许夜晚在种一片很远很远的草原，给做梦的小鹿吃。"),
        PostcardNarrative(id: "deer_visitor_textlib106_120", animalKey: "deer_visitor", body: "我看见一只蜗牛背着壳走。它的家跟着它。小鹿没有壳，但有腿。每种生命都带着自己的办法。"),
        PostcardNarrative(id: "deer_visitor_textlib106_121", animalKey: "deer_visitor", body: "今天听见远处有蹄声，虽然不是鹿群，我还是抬头很久。身体会记得群体的声音，比脑子更快。"),
        PostcardNarrative(id: "deer_visitor_textlib106_122", animalKey: "deer_visitor", body: "城市公园的草很整齐，却没有草原的味道。草原的草里有尘土、风、同伴和警报。复杂，但熟悉。"),
        PostcardNarrative(id: "deer_visitor_textlib106_123", animalKey: "deer_visitor", body: "我想念大家一起低头吃草的样子。看起来安静，其实每只耳朵都在工作。那是一种共同活着的声音。"),
        PostcardNarrative(id: "deer_visitor_textlib106_124", animalKey: "deer_visitor", body: "傍晚时，天空很像草原上的黄昏。我忽然想回到一片很宽的地方，和同伴们一起抬头看同一个方向。"),
        PostcardNarrative(id: "deer_visitor_textlib106_125", animalKey: "deer_visitor", body: "旅行很好，但有时我会想念鹿群里的位置。不是最中间，也不是最边缘，刚好能听见旁边呼吸的地方。"),
        PostcardNarrative(id: "deer_visitor_textlib106_126", animalKey: "deer_visitor", body: "今天看到几只羊聚在一起吃草。我站远处看，心里软了一下。食草动物在一起，会让世界看起来没那么锋利。"),
        PostcardNarrative(id: "deer_visitor_textlib106_127", animalKey: "deer_visitor", body: "我想念草原上的风。它很大，很不讲道理，却能把所有气味都带来。城市的风被墙切碎了。"),
        PostcardNarrative(id: "deer_visitor_textlib106_128", animalKey: "deer_visitor", body: "夜里梦见自己跟着鹿群奔跑。醒来时腿还轻轻动。梦里的奔跑没有危险，只是因为大家都在跑。"),
        PostcardNarrative(id: "deer_visitor_textlib106_129", animalKey: "deer_visitor", body: "我有时担心同伴们有没有吃饱，有没有避开捕猎者。担心没有用，但它会自己长出来，像草一样。"),
        PostcardNarrative(id: "deer_visitor_textlib106_130", animalKey: "deer_visitor", body: "如果有一天回草原，我想先找到一处高草，再啾啾两声。也许有人会抬头，也许没有。但风会知道我回来了。"),
        PostcardNarrative(id: "deer_visitor_textlib106_131", animalKey: "deer_visitor", body: "散步回来时，我看见小孩扫脸进幼儿园，机器说未注册。他说，是我呀。后来门开了。啾啾想，进门也像生存，要被认出来。"),
        PostcardNarrative(id: "deer_visitor_textlib106_132", animalKey: "deer_visitor", body: "市场里一只鸽子抢到面包屑，另一只没抢到。没抢到的又去找别处。小小鸟也懂：吃不饱，就继续找。"),
        PostcardNarrative(id: "deer_visitor_textlib106_133", animalKey: "deer_visitor", body: "车站有人刷票失败，被闸机挡住。他有票，却过不去。草原上没有闸机，但也有很多看不见的阻拦。"),
        PostcardNarrative(id: "deer_visitor_textlib106_134", animalKey: "deer_visitor", body: "宠物店里的小兔子缩在角落，被人们挑选。它不看人，只看木屑。啾啾站在外面想，每种生命都有自己的危险。"),
        PostcardNarrative(id: "deer_visitor_textlib106_135", animalKey: "deer_visitor", body: "公园里一只老狗走得很慢，主人也慢慢等它。曾经跑得快的身体，也会需要被等待。强弱不是固定的。"),
        PostcardNarrative(id: "deer_visitor_textlib106_136", animalKey: "deer_visitor", body: "超市机器识别不了苹果，店员把它翻来翻去。苹果还是苹果，只是暂时不被系统明白。啾啾觉得，很多生命也这样。"),
        PostcardNarrative(id: "deer_visitor_textlib106_137", animalKey: "deer_visitor", body: "医院大厅叫号屏跳过一个人。他一直坐着等。被漏掉的时候，身体会变小一点。鹿群里如果漏掉同伴，就很危险。"),
        PostcardNarrative(id: "deer_visitor_textlib106_138", animalKey: "deer_visitor", body: "我看见一只猫追鸟，鸟飞走，猫停下。捕猎者也不是每次成功。失败以后，它也要继续找下一顿。"),
        PostcardNarrative(id: "deer_visitor_textlib106_139", animalKey: "deer_visitor", body: "雨里有人撑伞，也有人没有伞。没有伞的人跑得很快。人类也会被天气追赶，只是他们不叫它捕猎者。"),
        PostcardNarrative(id: "deer_visitor_textlib106_140", animalKey: "deer_visitor", body: "邮局里有人寄明信片到远方。纸要穿过许多路才能到你手里。啾啾想，每一种抵达，都有自己的生存问题。"),
        PostcardNarrative(id: "fox_visitor_textlib106_001", animalKey: "fox_visitor", body: "今天在街角看见两个人说笑，脚尖却朝着相反方向。哈，嘴巴说留下，身体已经准备走了。这话有尾巴，小狐狸看见了。"),
        PostcardNarrative(id: "fox_visitor_textlib106_002", animalKey: "fox_visitor", body: "咖啡店老板说今天不忙，可他的手一直擦杯子。杯子已经很干净了。忙不忙不在店里，在心里。埃尼记下。"),
        PostcardNarrative(id: "fox_visitor_textlib106_003", animalKey: "fox_visitor", body: "广场上的鸽子看似散漫，其实每只都知道面包屑会从哪里掉。别小看鸽子，它们也有自己的情报网，哈。"),
        PostcardNarrative(id: "fox_visitor_textlib106_004", animalKey: "fox_visitor", body: "旅馆前台说房间很安静。我听见楼上小孩跑过三次。安静这个词，在人类嘴里常常需要打折理解。"),
        PostcardNarrative(id: "fox_visitor_textlib106_005", animalKey: "fox_visitor", body: "今天集市摊主说最后一个梨最甜。我看了看旁边藏着的一篮。哈，最后这种词，通常还有下一批。"),
        PostcardNarrative(id: "fox_visitor_textlib106_006", animalKey: "fox_visitor", body: "海边有个小孩说自己不怕浪，脚却一直往后退。勇敢不一定在话里，怕也不一定丢脸。小狐狸不拆穿。"),
        PostcardNarrative(id: "fox_visitor_textlib106_007", animalKey: "fox_visitor", body: "火车站里人们都看着屏幕，但真正知道方向的是脚步。谁犹豫，谁确定，谁只是跟着别人走，一眼就能看出来。"),
        PostcardNarrative(id: "fox_visitor_textlib106_008", animalKey: "fox_visitor", body: "今天一只猫假装不想要鱼干，尾巴尖却动了三下。哈，尾巴比嘴诚实。狐狸也有尾巴，所以我懂。"),
        PostcardNarrative(id: "fox_visitor_textlib106_009", animalKey: "fox_visitor", body: "路边有个广告写着绝对划算。绝对两个字太用力，通常说明它害怕你仔细想。聪明不是怀疑一切，是看见用力的地方。"),
        PostcardNarrative(id: "fox_visitor_textlib106_010", animalKey: "fox_visitor", body: "黄昏时，窗户一盏盏亮起。我喜欢看灯，因为灯很少撒谎。有人在，就亮；没人等，也会暗。"),
        PostcardNarrative(id: "fox_visitor_textlib106_011", animalKey: "fox_visitor", body: "今天有人看见我，说狐狸一定很狡猾。我笑了笑。哈，人类总想用一句话装下一整只动物，难怪句子会漏风。"),
        PostcardNarrative(id: "fox_visitor_textlib106_012", animalKey: "fox_visitor", body: "小摊老板把篮子挪远了一点，怕我偷果子。我没有解释，只买了一颗。被误解时，不一定要辩论，付款也很有说服力。"),
        PostcardNarrative(id: "fox_visitor_textlib106_013", animalKey: "fox_visitor", body: "有个孩子问我会不会骗人。我问他会不会只因为我是狐狸就先不信我。他想了想。很好，思考开始了。"),
        PostcardNarrative(id: "fox_visitor_textlib106_014", animalKey: "fox_visitor", body: "街头海报上画着坏狐狸，眼睛眯成一条线。我路过时停了一下。哈，画得不像我。我的眼睛更聪明，也更好看。"),
        PostcardNarrative(id: "fox_visitor_textlib106_015", animalKey: "fox_visitor", body: "今天一只兔子见到我立刻躲进草丛。我理解它。被害怕也是狐狸生活的一部分。但理解不等于不疼。"),
        PostcardNarrative(id: "fox_visitor_textlib106_016", animalKey: "fox_visitor", body: "旅馆门口的小狗想和我玩，主人却说离狐狸远点。我摇了摇尾巴。小狗不懂成见，只懂朋友。小狗有时比大人聪明。"),
        PostcardNarrative(id: "fox_visitor_textlib106_017", animalKey: "fox_visitor", body: "有人说狐狸的话不能全信。其实谁的话都不能全信，也不能全不信。只怀疑狐狸，是一种很懒的智慧。"),
        PostcardNarrative(id: "fox_visitor_textlib106_018", animalKey: "fox_visitor", body: "我在书店看到童话里的狐狸又在骗人。哎呀，我族文学形象长期欠佳。需要埃尼这样的优秀狐狸慢慢修复。"),
        PostcardNarrative(id: "fox_visitor_textlib106_019", animalKey: "fox_visitor", body: "今天有人夸我漂亮，又补一句就是太精了。漂亮可以直接夸，不用附带警报。哈，我收下前半句，退回后半句。"),
        PostcardNarrative(id: "fox_visitor_textlib106_020", animalKey: "fox_visitor", body: "世界给狐狸一副旧面具。我有时戴着它绕过去，有时把它摘下来。聪明不是承认成见，是知道何时不浪费力气。"),
        PostcardNarrative(id: "fox_visitor_textlib106_021", animalKey: "fox_visitor", body: "今天一个人走过很长的街。没有谁催，也没有谁等。独立像一条干净的小路，安静、清楚，也有点冷。"),
        PostcardNarrative(id: "fox_visitor_textlib106_022", animalKey: "fox_visitor", body: "我在旅馆房间检查窗、门、食物和退路。一个人生活久了，安全感不是别人给的，是自己一件件摆出来的。"),
        PostcardNarrative(id: "fox_visitor_textlib106_023", animalKey: "fox_visitor", body: "晚餐只买了一个面包和一小块奶酪。够吃，够省，也够安静。独立生活就是这样，不盛大，但可控。"),
        PostcardNarrative(id: "fox_visitor_textlib106_024", animalKey: "fox_visitor", body: "今天拒绝了一场看起来热闹的邀请。热闹不难，离开热闹以后不觉得空才难。埃尼选择回房间晒尾巴。"),
        PostcardNarrative(id: "fox_visitor_textlib106_025", animalKey: "fox_visitor", body: "我喜欢独自旅行。没人需要解释路线，没人需要照顾情绪。可夜里关灯时，安静也会坐到床边看我。"),
        PostcardNarrative(id: "fox_visitor_textlib106_026", animalKey: "fox_visitor", body: "街边有人推销特别亲密的朋友关系。哈，朋友如果需要推销，通常后面会有账单。"),
        PostcardNarrative(id: "fox_visitor_textlib106_027", animalKey: "fox_visitor", body: "一个人吃饭时，能听见自己的咀嚼声。以前觉得孤单，后来觉得清楚。清楚不是幸福，但至少不混乱。"),
        PostcardNarrative(id: "fox_visitor_textlib106_028", animalKey: "fox_visitor", body: "今天遇到麻烦，我自己绕开了。没有求助，没有欠谁。聪明的小狐狸会为此骄傲，也会在黄昏时有一点累。"),
        PostcardNarrative(id: "fox_visitor_textlib106_029", animalKey: "fox_visitor", body: "独立像一件合身的外衣，挡风，很好。但穿太久，会忘记有人也可以替你把领口理平。"),
        PostcardNarrative(id: "fox_visitor_textlib106_030", animalKey: "fox_visitor", body: "我曾经以为负担最少，就是生活最好。后来才知道，负担少不等于意义多。哎呀，这个结论有点晚，但还来得及。"),
        PostcardNarrative(id: "fox_visitor_textlib106_031", animalKey: "fox_visitor", body: "今天有人说带我去看最美的风景，却先问我带了多少食物。哈，风景还没出现，算盘先响了。"),
        PostcardNarrative(id: "fox_visitor_textlib106_032", animalKey: "fox_visitor", body: "我曾经相信过一句很漂亮的话，后来发现它只是诱饵。现在我不怪自己。饿的时候，连聪明狐狸也会靠近甜味。"),
        PostcardNarrative(id: "fox_visitor_textlib106_033", animalKey: "fox_visitor", body: "集市上有人把坏果藏在好果下面。我看见了，没有生气，只换了摊位。世界有坏果，聪明就是不把整座市场都否定。"),
        PostcardNarrative(id: "fox_visitor_textlib106_034", animalKey: "fox_visitor", body: "今天听见一句承诺，太圆，太亮，没有缝。真正的承诺通常没那么好看，它会带一点实际的重量。"),
        PostcardNarrative(id: "fox_visitor_textlib106_035", animalKey: "fox_visitor", body: "我看人说话时，总会顺便看它停顿在哪里。谎言常常不在词里，在停顿里伸尾巴。"),
        PostcardNarrative(id: "fox_visitor_textlib106_036", animalKey: "fox_visitor", body: "被欺骗以后，我学会先慢一点。慢不是冷漠，是给真相一点时间自己走出来。"),
        PostcardNarrative(id: "fox_visitor_textlib106_037", animalKey: "fox_visitor", body: "今天有人夸我聪明，夸得太急。我笑了一下。过快的夸奖像突然撒下的果子，需要先看草里有没有网。"),
        PostcardNarrative(id: "fox_visitor_textlib106_038", animalKey: "fox_visitor", body: "曾经有个朋友只在需要我时出现。后来我学会，真正的关系不该像季节性陷阱。"),
        PostcardNarrative(id: "fox_visitor_textlib106_039", animalKey: "fox_visitor", body: "我不是不信任世界。我只是知道信任是种贵重食物，不能随便放在每一只盘子里。"),
        PostcardNarrative(id: "fox_visitor_textlib106_040", animalKey: "fox_visitor", body: "欺骗没有让我变坏，只让我学会看路。哈，这大概是狐狸最体面的复仇。"),
        PostcardNarrative(id: "fox_visitor_textlib106_041", animalKey: "fox_visitor", body: "今天夜里风很冷，我想起一个很久以前的失败。没有谁看见我哭。狐狸哭起来也很安静，尾巴会替脸遮住。"),
        PostcardNarrative(id: "fox_visitor_textlib106_042", animalKey: "fox_visitor", body: "旅馆灯关掉后，白天那些聪明话都退开了。只剩一只小狐狸躺着。原来想明白，不等于立刻不疼。"),
        PostcardNarrative(id: "fox_visitor_textlib106_043", animalKey: "fox_visitor", body: "我在海边坐了很久。浪声很大，刚好可以盖住一点鼻音。哈，大海很懂事，不问狐狸为什么掉眼泪。"),
        PostcardNarrative(id: "fox_visitor_textlib106_044", animalKey: "fox_visitor", body: "今天被一句旧话刺了一下。我以为早就没事了，结果心里还有回声。聪明能绕开坑，但不能让所有旧伤消失。"),
        PostcardNarrative(id: "fox_visitor_textlib106_045", animalKey: "fox_visitor", body: "一个人走夜路时，月亮跟着我。我忽然觉得它像唯一的听众。于是我小声说，埃尼今天也有点累。"),
        PostcardNarrative(id: "fox_visitor_textlib106_046", animalKey: "fox_visitor", body: "我不喜欢在别人面前脆弱。不是因为骄傲，是因为有些安慰会让我更想哭。狐狸也有控制不住尾巴的时候。"),
        PostcardNarrative(id: "fox_visitor_textlib106_047", animalKey: "fox_visitor", body: "今天看见一家人一起回家，门在他们身后关上。我站在街对面，忽然很想念一个还没出现的未来。"),
        PostcardNarrative(id: "fox_visitor_textlib106_048", animalKey: "fox_visitor", body: "我哭过以后，去买了一颗苹果。生活很奇怪，眼泪还没干，肚子已经提醒我继续活。哈，很实际。"),
        PostcardNarrative(id: "fox_visitor_textlib106_049", animalKey: "fox_visitor", body: "有时我会讨厌自己太清醒。清醒地知道失去的原因，也清醒地知道无法改变。那就让泪水替我不清醒一会儿。"),
        PostcardNarrative(id: "fox_visitor_textlib106_050", animalKey: "fox_visitor", body: "夜深时，我把悲伤想成一只小动物。它来我这里躲雨。我没有赶走它，只给它一点地方，等天亮。"),
        PostcardNarrative(id: "fox_visitor_textlib106_051", animalKey: "fox_visitor", body: "今天差点因为一句话生气。后来想想，那句话说的是对方的狭窄，不是我的价值。哈，尾巴转了个弯，路就宽了。"),
        PostcardNarrative(id: "fox_visitor_textlib106_052", animalKey: "fox_visitor", body: "有人误解我时，我本想解释很多。后来发现，他不是听不懂，是不想懂。聪明就是及时省下力气。"),
        PostcardNarrative(id: "fox_visitor_textlib106_053", animalKey: "fox_visitor", body: "今天迷路了。先慌了一会儿，然后想明白：迷路不是失败，是地图还没更新我的位置。于是我继续走。"),
        PostcardNarrative(id: "fox_visitor_textlib106_054", animalKey: "fox_visitor", body: "我曾经以为世界怎么看我很重要。后来明白，我如何看待自己，才决定我会不会被别人的眼光牵走。"),
        PostcardNarrative(id: "fox_visitor_textlib106_055", animalKey: "fox_visitor", body: "面对麻烦时，我问自己：这是危险，还是只是麻烦？危险要跑，麻烦要拆。分清以后，心就不乱。"),
        PostcardNarrative(id: "fox_visitor_textlib106_056", animalKey: "fox_visitor", body: "今天有人离开，没有说明白原因。我忽然想通：不是每个离开都需要我补成一个完整故事。有些空白，就让它空着。"),
        PostcardNarrative(id: "fox_visitor_textlib106_057", animalKey: "fox_visitor", body: "我曾经害怕独自生活会证明没人爱我。后来想明白，独立不是没人爱，是先不把生存交给别人。"),
        PostcardNarrative(id: "fox_visitor_textlib106_058", animalKey: "fox_visitor", body: "被拒绝时，我难过了一会儿。然后想，门关上不一定说明我不好，也可能里面根本没有适合狐狸的空间。"),
        PostcardNarrative(id: "fox_visitor_textlib106_059", animalKey: "fox_visitor", body: "今天的雨打乱了计划。我躲在屋檐下想，计划不是命令世界，是帮自己在变化里找到下一步。很好，下一步是买热汤。"),
        PostcardNarrative(id: "fox_visitor_textlib106_060", animalKey: "fox_visitor", body: "关键时刻，我常常听见心里有只老狐狸说：先别急着相信，也别急着怀疑。看清楚，再选择。"),
        PostcardNarrative(id: "fox_visitor_textlib106_061", animalKey: "fox_visitor", body: "今天有人说随便聊聊，却一直绕到我的路线和住处。哈，随便这两个字，有时穿着很正式的鞋。"),
        PostcardNarrative(id: "fox_visitor_textlib106_062", animalKey: "fox_visitor", body: "一个商人说这是为我好。可他说到为我好时，眼睛看着我的钱包。狐狸不用水晶球，也能看见意图。"),
        PostcardNarrative(id: "fox_visitor_textlib106_063", animalKey: "fox_visitor", body: "朋友说不介意，尾巴却扫得很快。动物的身体比嘴更诚实。人类如果也有尾巴，世界会简单很多。"),
        PostcardNarrative(id: "fox_visitor_textlib106_064", animalKey: "fox_visitor", body: "今天有人问我意见，却已经把答案拿在手里。它不是想听，只是想让我替它盖章。埃尼不盖。"),
        PostcardNarrative(id: "fox_visitor_textlib106_065", animalKey: "fox_visitor", body: "我看见一对情侣吵架。一个说随便，另一个立刻紧张。随便有时不是随便，是最后一道题。"),
        PostcardNarrative(id: "fox_visitor_textlib106_066", animalKey: "fox_visitor", body: "有人向我示好，话很甜，但每句都在试探边界。我笑了笑，往后退半步。聪明狐狸不把礼貌当同意。"),
        PostcardNarrative(id: "fox_visitor_textlib106_067", animalKey: "fox_visitor", body: "今天一只乌鸦假装只是路过，眼睛却盯着我的果子。哈，朋友，演技还需练习。"),
        PostcardNarrative(id: "fox_visitor_textlib106_068", animalKey: "fox_visitor", body: "一个人说我太敏感。通常说这话的人，是希望你别发现它刚踩过线。敏感不是错，是雷达正常。"),
        PostcardNarrative(id: "fox_visitor_textlib106_069", animalKey: "fox_visitor", body: "我喜欢看真实意图浮出水面。它刚出来时总是很小，像鱼背上的一点光。看见了，就不用被拖下水。"),
        PostcardNarrative(id: "fox_visitor_textlib106_070", animalKey: "fox_visitor", body: "有些心思并不坏，只是不说清楚会伤人。埃尼现在学会，能看穿，也可以温柔地问一句：你真正想要什么？"),
        PostcardNarrative(id: "fox_visitor_textlib106_071", animalKey: "fox_visitor", body: "今天有个新朋友很热情。我也很礼貌，但只给了三分真心。不是它不好，是我还没决定要不要打开门。"),
        PostcardNarrative(id: "fox_visitor_textlib106_072", animalKey: "fox_visitor", body: "深入相处像一起穿过雨林。风景可能很好，但也可能互相拖累。独自走，至少脚步只需要对自己负责。"),
        PostcardNarrative(id: "fox_visitor_textlib106_073", animalKey: "fox_visitor", body: "有人说我太有距离感。哈，距离是狐狸的围巾，冷的时候很有用。"),
        PostcardNarrative(id: "fox_visitor_textlib106_074", animalKey: "fox_visitor", body: "我不怕孤独，我怕不清楚的关系。孤独有边界，模糊关系没有，容易把尾巴弄湿。"),
        PostcardNarrative(id: "fox_visitor_textlib106_075", animalKey: "fox_visitor", body: "今天聚会很热闹，我坐到最后还是先走了。热闹里有很多期待，而期待常常悄悄变成账单。"),
        PostcardNarrative(id: "fox_visitor_textlib106_076", animalKey: "fox_visitor", body: "我能听见别人没说出口的要求。听得太多，心会累。所以我把洞口修小一点，不是谁都能进。"),
        PostcardNarrative(id: "fox_visitor_textlib106_077", animalKey: "fox_visitor", body: "有人想快速成为我的重要朋友。重要这件事不能快递。狐狸的信任要自己走路过来。"),
        PostcardNarrative(id: "fox_visitor_textlib106_078", animalKey: "fox_visitor", body: "独处时，我不用解释沉默，也不用把聪明拿出来表演。尾巴想摆就摆，想藏就藏。"),
        PostcardNarrative(id: "fox_visitor_textlib106_079", animalKey: "fox_visitor", body: "我曾经觉得不深入相处，是保护自己的最高智慧。后来才知道，它也可能是一种漂亮的逃跑。"),
        PostcardNarrative(id: "fox_visitor_textlib106_080", animalKey: "fox_visitor", body: "即使现在，我也不愿和太多人太近。爱人和家庭已经占据最珍贵的位置，别的关系慢慢来，哈。"),
        PostcardNarrative(id: "fox_visitor_textlib106_081", animalKey: "fox_visitor", body: "第一次见它时，它没有夸我聪明，也没有怕我狡猾。它只是问：你要不要一起走一段？哎呀，这句话真危险，危险得很温柔。"),
        PostcardNarrative(id: "fox_visitor_textlib106_082", animalKey: "fox_visitor", body: "它看穿我在逞强，却没有拆穿。只是把果子推近一点。那一刻我想，原来聪明也可以用来保护别人的面子。"),
        PostcardNarrative(id: "fox_visitor_textlib106_083", animalKey: "fox_visitor", body: "我们一起躲雨时，它把尾巴搭过来一点点。没有说什么。狐狸之间有些话，用尾巴就够了。"),
        PostcardNarrative(id: "fox_visitor_textlib106_084", animalKey: "fox_visitor", body: "它不要求我立刻信任。它说，狐狸可以绕路，但总要知道哪里能回去。后来我发现，它就是那个地方。"),
        PostcardNarrative(id: "fox_visitor_textlib106_085", animalKey: "fox_visitor", body: "今天看见两只狐狸形状的云，我想起它。以前我看云，只判断天气。现在偶尔也判断思念。"),
        PostcardNarrative(id: "fox_visitor_textlib106_086", animalKey: "fox_visitor", body: "它笑我总是分析太多。我说这是天性。它说，天性也可以休息。哈，听起来像胡说，但我居然信了。"),
        PostcardNarrative(id: "fox_visitor_textlib106_087", animalKey: "fox_visitor", body: "我们第一次一起找食物，我把最好的果子留给自己，后来又偷偷换给它。它看见了，没有揭穿。爱情小狐狸就是这样开始露馅。"),
        PostcardNarrative(id: "fox_visitor_textlib106_088", animalKey: "fox_visitor", body: "它问我，独立真的让你轻松吗？我本想回答当然。可话到嘴边，尾巴先沉默了。"),
        PostcardNarrative(id: "fox_visitor_textlib106_089", animalKey: "fox_visitor", body: "遇见它以后，我才知道，有些靠近不是负担，是一起分担风。风还是风，但尾巴不再总是独自被吹乱。"),
        PostcardNarrative(id: "fox_visitor_textlib106_090", animalKey: "fox_visitor", body: "它没有让我放弃聪明。它只是让我明白，聪明如果不敢爱，就只是在给孤独找理由。"),
        PostcardNarrative(id: "fox_visitor_textlib106_091", animalKey: "fox_visitor", body: "今天看到一户人家窗里亮着灯，我忽然想回自己的洞。以前我只看灯判断有人，现在我看灯，会想里面有没有谁等谁。"),
        PostcardNarrative(id: "fox_visitor_textlib106_092", animalKey: "fox_visitor", body: "家庭不是每天都浪漫。更多时候，是谁去找果子，谁修洞口，谁把湿掉的草换掉。哎呀，琐碎居然这么动人。"),
        PostcardNarrative(id: "fox_visitor_textlib106_093", animalKey: "fox_visitor", body: "我曾经以为生活意义在远方，在成就，在看穿所有人。后来发现，是晚饭后一起把尾巴放平的十分钟。"),
        PostcardNarrative(id: "fox_visitor_textlib106_094", animalKey: "fox_visitor", body: "今天买到两颗梨。我自然地挑了一颗更甜的带回去。以前我会计算得失，现在我先想到它会不会喜欢。"),
        PostcardNarrative(id: "fox_visitor_textlib106_095", animalKey: "fox_visitor", body: "家庭让我变笨了吗？没有。它只是让我聪明的方向变了：以前用来防御，现在用来照顾。"),
        PostcardNarrative(id: "fox_visitor_textlib106_096", animalKey: "fox_visitor", body: "我喜欢听它在洞里翻身的声音。那不是打扰，是存在证明。哈，爱人连吵醒你都带着意义。"),
        PostcardNarrative(id: "fox_visitor_textlib106_097", animalKey: "fox_visitor", body: "今天下雨，我第一反应不是找最近屋檐，而是想家里那处会不会漏水。原来心有了住处以后，雨也有了方向。"),
        PostcardNarrative(id: "fox_visitor_textlib106_098", animalKey: "fox_visitor", body: "我们偶尔吵架。狐狸吵架很聪明，句子都有尾巴。后来学会收尾巴，因为赢了道理，输了拥抱，实在不划算。"),
        PostcardNarrative(id: "fox_visitor_textlib106_099", animalKey: "fox_visitor", body: "家庭不是把我关住，而是让我每次离开都有想回去的地方。这个区别，我很晚才懂。"),
        PostcardNarrative(id: "fox_visitor_textlib106_100", animalKey: "fox_visitor", body: "晚上我写明信片，它在旁边睡着。呼吸很轻。我忽然想，以往那些风光、委屈和聪明，都在此刻变成背景。"),
        PostcardNarrative(id: "fox_visitor_textlib106_101", animalKey: "fox_visitor", body: "今天海边夕阳太漂亮，我第一反应是想叫它来看。然后才想起它不在身边。哎呀，原来风景也会自动变成双人份。"),
        PostcardNarrative(id: "fox_visitor_textlib106_102", animalKey: "fox_visitor", body: "我在市场看见一条红围巾，想象它戴上会不会好看。买下了。爱情小狐狸的消费逻辑：尾巴认为合适。"),
        PostcardNarrative(id: "fox_visitor_textlib106_103", animalKey: "fox_visitor", body: "以前我觉得甜言蜜语大多不可靠。现在我偶尔也说。区别是，我说的时候真的想把甜的东西递过去。"),
        PostcardNarrative(id: "fox_visitor_textlib106_104", animalKey: "fox_visitor", body: "今天看到两只鸟在电线上靠得很近。我笑了。以前会分析它们为什么靠近，现在只觉得：靠近就靠近吧，很好。"),
        PostcardNarrative(id: "fox_visitor_textlib106_105", animalKey: "fox_visitor", body: "我承认，遇见它以后，我变得有点俗气。会想念，会等，会因为一句回家了开心。哈，俗气得很幸福。"),
        PostcardNarrative(id: "fox_visitor_textlib106_106", animalKey: "fox_visitor", body: "爱情不是让我失去判断力，而是让我愿意在判断之后仍然冒一点风险。聪明狐狸也需要勇敢。"),
        PostcardNarrative(id: "fox_visitor_textlib106_107", animalKey: "fox_visitor", body: "今天想它想得尾巴都不想动。后来给它写了一句：我在远方看见月亮，觉得月亮也很像你。太肉麻，没删。"),
        PostcardNarrative(id: "fox_visitor_textlib106_108", animalKey: "fox_visitor", body: "我以前把独立当王冠。现在发现，有人能轻轻摸摸这顶王冠，还不想拿走它，才珍贵。"),
        PostcardNarrative(id: "fox_visitor_textlib106_109", animalKey: "fox_visitor", body: "爱情小狐狸不是整天发呆。也会找食物、看路线、防坏天气。只是做这些事时，心里多了一盏灯。"),
        PostcardNarrative(id: "fox_visitor_textlib106_110", animalKey: "fox_visitor", body: "有人问我最重要的是什么。我本来想说聪明。后来尾巴摇了一下。好吧，是爱人，是家庭，是每天一起醒来的小声音。"),
        PostcardNarrative(id: "fox_visitor_textlib106_111", animalKey: "fox_visitor", body: "今天住的旅馆很漂亮，但枕头没有家的气味。漂亮是漂亮，陌生也是陌生。哈，狐狸的鼻子不会被装潢骗过。"),
        PostcardNarrative(id: "fox_visitor_textlib106_112", animalKey: "fox_visitor", body: "海边风很大，我把尾巴卷起来，忽然想起家里那个避风角。旅行让我看见世界，也让我更清楚哪里是家。"),
        PostcardNarrative(id: "fox_visitor_textlib106_113", animalKey: "fox_visitor", body: "今天吃到好甜的果子，第一口想的是：它应该也会喜欢。第二口才想起我现在一个人在远方。哎呀，甜味忽然有了距离。"),
        PostcardNarrative(id: "fox_visitor_textlib106_114", animalKey: "fox_visitor", body: "城市夜景很好看，灯多得像星群。可是没有一盏是我们洞口那盏。家里的小灯不华丽，但最知道我的路。"),
        PostcardNarrative(id: "fox_visitor_textlib106_115", animalKey: "fox_visitor", body: "我在明信片上写了很多风景，写到最后还是绕回它。哈，狐狸的路线再聪明，也会被心带回家。"),
        PostcardNarrative(id: "fox_visitor_textlib106_116", animalKey: "fox_visitor", body: "今天听见一对伴侣在街边争论晚饭吃什么。我居然有点羡慕。能争论晚饭，也说明有人一起晚饭。"),
        PostcardNarrative(id: "fox_visitor_textlib106_117", animalKey: "fox_visitor", body: "旅行时，我喜欢收集小东西：一片叶子，一颗石子，一句好笑的话。它们最后都会被我带回家，变成共同的故事。"),
        PostcardNarrative(id: "fox_visitor_textlib106_118", animalKey: "fox_visitor", body: "陌生城市让我兴奋，也让我清醒。一个人可以去很远，但远方如果没人分享，就像果子只闻不吃。"),
        PostcardNarrative(id: "fox_visitor_textlib106_119", animalKey: "fox_visitor", body: "今天我走过一座桥，桥下水很亮。我想，等回家以后要讲给它听。被讲述的风景，才算真正落地。"),
        PostcardNarrative(id: "fox_visitor_textlib106_120", animalKey: "fox_visitor", body: "我不讨厌离开。离开让我知道，回去不是退步，是选择。哈，爱情小狐狸的方向感越来越好。"),
        PostcardNarrative(id: "fox_visitor_textlib106_121", animalKey: "fox_visitor", body: "今天看见月亮像一枚银色果子。我想，如果狐狸能跳到天上，应该先咬一口，再假装只是检查成熟度。"),
        PostcardNarrative(id: "fox_visitor_textlib106_122", animalKey: "fox_visitor", body: "海浪追着岸边跑，又总是退回去。像一只太害羞的狐狸，想靠近又装作路过。哈，大海也有小心思。"),
        PostcardNarrative(id: "fox_visitor_textlib106_123", animalKey: "fox_visitor", body: "云像一群白狐狸趴在天上晒肚皮。它们不需要找洞，也不需要解释自己是不是狡猾。天空真宽容。"),
        PostcardNarrative(id: "fox_visitor_textlib106_124", animalKey: "fox_visitor", body: "火车钻进隧道时，我觉得自己被一只黑色巨兽吞下，又完整吐出来。交通方式略显戏剧，但效率不错。"),
        PostcardNarrative(id: "fox_visitor_textlib106_125", animalKey: "fox_visitor", body: "路灯一盏盏亮，像有人给城市挂上小果子。夜里的狐狸可以沿着这些果子走，找到温暖的巷口。"),
        PostcardNarrative(id: "fox_visitor_textlib106_126", animalKey: "fox_visitor", body: "今天看到一只蜗牛背着壳走。我想它才是真正的旅行家。房子随身携带，房贷问题也许较少。"),
        PostcardNarrative(id: "fox_visitor_textlib106_127", animalKey: "fox_visitor", body: "雨滴落在玻璃上，像很多小狐狸从天上滑下来。每只都想进屋，结果变成一道水痕。很努力，也很短暂。"),
        PostcardNarrative(id: "fox_visitor_textlib106_128", animalKey: "fox_visitor", body: "我看见影子跟着我走，忽然想它是不是另一只比较沉默的埃尼。它不说话，但从来不缺席。"),
        PostcardNarrative(id: "fox_visitor_textlib106_129", animalKey: "fox_visitor", body: "天空的晚霞像被谁打翻了浆果酱。一定是某只大狐狸偷吃失败。证据明显，但嫌疑狐已逃离现场。"),
        PostcardNarrative(id: "fox_visitor_textlib106_130", animalKey: "fox_visitor", body: "如果风有尾巴，今天一定摇得很厉害。它从左边跑到右边，把每棵树都逗笑了。哈，风也是调皮动物。"),
        PostcardNarrative(id: "fox_visitor_textlib106_131", animalKey: "fox_visitor", body: "散步回来时，我看见小孩扫脸进幼儿园，机器说未注册。他说，是我呀。后来老师开门。哈，有时世界认不出你，但熟悉你的人会。"),
        PostcardNarrative(id: "fox_visitor_textlib106_132", animalKey: "fox_visitor", body: "市场里有人说狐狸图案的包一定狡猾可爱。狡猾和可爱被缝在一起出售。成见一旦做成商品，就更难拆开。"),
        PostcardNarrative(id: "fox_visitor_textlib106_133", animalKey: "fox_visitor", body: "车站有人拿着票却过不了闸机。他急得解释，机器不听。世界有些门只认格式，不认真心。狐狸不喜欢这样的门。"),
        PostcardNarrative(id: "fox_visitor_textlib106_134", animalKey: "fox_visitor", body: "宠物店门口小狗冲我摇尾巴，主人却把它拉回去。小狗想做朋友，主人想起童话。误解常常不是当事者的本意。"),
        PostcardNarrative(id: "fox_visitor_textlib106_135", animalKey: "fox_visitor", body: "咖啡店里一对恋人吵架。一个说你总是算计，另一个沉默很久。被贴标签的人，连解释都像证据。"),
        PostcardNarrative(id: "fox_visitor_textlib106_136", animalKey: "fox_visitor", body: "超市机器识别不了苹果，店员把它翻来转去。苹果没有变，只是暂时不被系统承认。哈，苹果也有身份危机。"),
        PostcardNarrative(id: "fox_visitor_textlib106_137", animalKey: "fox_visitor", body: "医院叫号屏跳过一个人。护士后来发现，走过去叫他。他站起来时松了一口气。被重新看见，是一件很小又很大的事。"),
        PostcardNarrative(id: "fox_visitor_textlib106_138", animalKey: "fox_visitor", body: "公园里一只乌鸦叼走亮晶晶的纸片，被人说又偷东西。也许它只是喜欢光。动机这件事，外人总猜得太快。"),
        PostcardNarrative(id: "fox_visitor_textlib106_139", animalKey: "fox_visitor", body: "邮局里有人寄信，反复确认地址。我喜欢这种认真。要抵达谁，先要知道谁在哪里。关系也是一样。"),
        PostcardNarrative(id: "fox_visitor_textlib106_140", animalKey: "fox_visitor", body: "我看见一只小狐狸玩偶被摆在橱窗里，标语写着小骗子。它笑得很甜。我站了一会儿，心想：总有一天，我们会自己讲自己的故事。"),
        PostcardNarrative(id: "bear_visitor_001", animalKey: "bear_visitor", body: "夜班药店的白灯还亮着，柜台旁放着一杯热水，杯口的白气很淡。值班的人把椅子往里推了推，又把说明书压在药盒下面，动作很慢，也很稳。我站在门口，把爪子放在杯壁旁边暖了一会儿。小熊有时候反应慢，要过一阵才知道自己为什么停下。后来我想明白了：不是因为药店特别好，也不是因为这杯水特别热，是因为这一小块地方没有催我马上走。旅行里有些地方就是这样，什么都不多说，只给你一把椅子、一盏灯、一点热气。后来门外的风小了一点，那把椅子还在原来的地方。"),
        PostcardNarrative(id: "bear_visitor_002", animalKey: "bear_visitor", body: "傍晚的长椅被太阳晒了一天，坐上去还有一点暖。我坐得很慢，木头先响了一声，然后稳住。旁边有人把购物袋放在椅子另一头，袋子里有白菜和一瓶酱油。小熊不太会找话，只会听塑料袋被风吹得轻轻动。提前坐一会儿，后面的路会好走些。太阳落下去以后，椅背还剩一点温度。"),
        PostcardNarrative(id: "bear_visitor_003", animalKey: "bear_visitor", body: "便利店的微波炉转着一盒便当，里面的灯一亮一暗。站在旁边的人搓着手，眼睛一直看着倒计时。我也跟着看，数字跳得很慢，但总算一格一格少下去。热东西有自己的速度，急也没有用。微波炉叮的一声，便当盒盖鼓起来一点。那个人小心地端出来，像端着一个刚刚回来的晚上。"),
        PostcardNarrative(id: "bear_visitor_004", animalKey: "bear_visitor", body: "雨天的公交站有一块干的地方，在广告牌下面，不大，但够站。我把背包放在脚边，尽量不占太多。雨水顺着棚顶往下流，落到路边的水坑里。旁边老人把伞收起来，伞尖滴水很慢。公交还没到，那块干地被几双鞋分着站，谁也没有挤谁。小熊看着那一小块地，觉得够用就很好。"),
        PostcardNarrative(id: "bear_visitor_005", animalKey: "bear_visitor", body: "老电影院门口有两级台阶，边缘磨得很圆。我上去时慢了一点，爪子先试了试。里面散场的人出来，笑声一阵一阵往外涌。小熊不太适合挤在人群里，就靠在墙边等他们过去。重一点的脚步，更要知道什么时候停。人群散开以后，台阶上留下几张票根，风吹过来，票根翻了个面，又停住了。"),
        PostcardNarrative(id: "bear_visitor_006", animalKey: "bear_visitor", body: "深夜的自动售货机亮着，瓶子一排排站在玻璃后面。我投了硬币，机器响了一会儿，水才慢慢滚下来。声音很沉，像有什么东西终于落到该落的位置。我弯腰捡起来，瓶身很凉。手里有一点重量，心里会稳些。售货机继续亮着，照着地上一小块蓝白色的光。"),
        PostcardNarrative(id: "bear_visitor_007", animalKey: "bear_visitor", body: "小饭馆快打烊，老板把最后一张桌子擦干净，又把椅子推进去。桌面上还有一点汤的味道，不浓，很家常。我坐在门口台阶上，听锅盖碰到锅沿，咚的一声。吃饱以后，很多声音都在结束一天。老板关门时，屋里的热气跟着出来一点，很快散在夜风里。小熊坐到风小了，才慢慢站起来。"),
        PostcardNarrative(id: "bear_visitor_008", animalKey: "bear_visitor", body: "火车车厢里空座很多，我挑了靠窗的位置。座椅有点旧，坐下去会轻轻陷一下，但很稳。窗外的灯一盏一盏退后，像路自己在慢慢折起来。小熊看东西慢，常常要等它走远了，才知道刚才看见了什么。列车晃了一下，水杯里的水只晃到杯壁，没有洒出来。这个位置不错，可以坐很久。"),
        PostcardNarrative(id: "bear_visitor_009", animalKey: "bear_visitor", body: "桥上的风大，我把围巾往下压了压。栏杆很凉，但很结实，手放上去能感觉到一点震动。河水在下面走得很快，灯影被拉长又揉碎。小熊不急着过桥，先找一处能靠的地方。风又吹来时，围巾角贴在胸口，没有再翻起来。栏杆一直在那里，稳稳地接住我的重量。"),
        PostcardNarrative(id: "bear_visitor_010", animalKey: "bear_visitor", body: "清晨的门卫室亮着一盏小灯，窗台上放着搪瓷杯。杯子旁边有一副旧手套，手套口朝着暖气片。值班的人低头看报纸，偶尔抬头看看外面的路。我站在窗外，觉得这种灯不刺眼，只把周围照得够用。远处第一辆公交开过来，门卫室的窗玻璃轻轻震了一下。手套没有动，杯子也没有动，早晨就这样慢慢开始了。")
    ]
}
